        if (states[i] == last_state_id) {
            last_state = malloc(sizeof(struct State));
            if (!last_state) {
                return NULL; // Insufficient memory
            }
            last_state->id = states[i];
            last_state->next = NULL;
            break;
        }
    }

    if (!last_state) {
        return NULL; // Last state not found in the FSA
    }

    struct State *current_state = last_state;
    for (int i = num_states - 1; i >= 0; --i) {
        if (states[i] != last_state_id) {
            struct State *new_state = malloc(sizeof(struct State));
            if (!new_state) {
                return NULL; // Insufficient memory
            }
            new_state->id = states[i];
            new_state->next = current_state;
            current_state = new_state;
        }
    }

    last_state->next = current_state;
    return current_state;
}
