#include <stdlib.h>
#include <string.h>

char* copy_array_of_strings(const char** in, int count) {
    if (in == NULL || count <= 0) {
        return NULL;
    }

    // Calculate the total length of all strings including null terminators
    size_t total_length = 0;
    for (int i = 0; i < count; ++i) {
        if (in[i] != NULL) {
            total_length += strlen(in[i]) + 1; // +1 for the null terminator
        } else {
            return NULL; // If any string is NULL, return NULL
        }
    }

    // Allocate memory for the new array of strings
    char* result = (char*)malloc(total_length);
    if (result == NULL) {
        return NULL; // Allocation failed
    }

    // Copy each string into the new array
    char* current_pos = result;
    for (int i = 0; i < count; ++i) {
        strcpy(current_pos, in[i]);
        current_pos += strlen(in[i]) + 1; // Move to the next position
    }

    return result;
}
