#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int transaction_id;
    time_t timestamp;
    double weighted_sum;
} Transaction;

typedef struct {
    int total_transactions;
    int filtered_transactions;
    double max_weighted_sum;
    int max_weighted_sum_id;
} Metrics;

void updateMetrics(Metrics *metrics) {
    metrics->total_transactions++;
}

int filterTransactions(Transaction transactions[], int size, Metrics *metrics) {
    time_t current_time = time(NULL);
    int count = 0;

    for (int i = 0; i < size; i++) {
        double age = difftime(current_time, transactions[i].timestamp);
        if (age <= 3) { // Assuming the transaction is within the last 3 seconds
            metrics->filtered_transactions++;
            updateMetrics(metrics);
            count++;
        }
    }

    return count;
}

int main() {
    Transaction transactions[] = {
        {1, time(NULL) - 2, 5.0},
        {2, time(NULL) - 4, 3.0},
        {3, time(NULL) - 5, 7.0}
    };
    int size = sizeof(transactions) / sizeof(transactions[0]);
    Metrics metrics = {0, 0, 0, 0};

    int filtered_count = filterTransactions(transactions, size, &metrics);

    printf("Filtered Transactions: %d\n", filtered_count);
    printf("Total Transactions: %d\n", metrics.total_transactions);
    printf("Filtered Transactions: %d\n", metrics.filtered_transactions);
    printf("Max Weighted Sum: %f, ID: %d\n", metrics.max_weighted_sum, metrics.max_weighted_sum_id);

    return 0;
}
