#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct ResourceBundle {
    char **items;
    int num_items;
};

int loadResourceBundle(const char *path, struct ResourceBundle *bundle) {
    FILE *file = fopen(path, "r");
    if (!file) {
        perror("Failed to open resource file");
        return -1; // Return error code for failure
    }

    int capacity = 10; // Initial capacity for the bundle items array
    bundle->items = (char **)malloc(capacity * sizeof(char *));
    if (!bundle->items) {
        perror("Failed to allocate memory");
        fclose(file);
        return -1; // Return error code for failure
    }

    bundle->num_items = 0;
    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        if (bundle->num_items >= capacity) {
            capacity *= 2;
            char **new_items = (char **)realloc(bundle->items, capacity * sizeof(char *));
            if (!new_items) {
                perror("Failed to reallocate memory");
                free(bundle->items);
                fclose(file);
                return -1; // Return error code for failure
            }
            bundle->items = new_items;
        }
        buffer[strcspn(buffer, "\n")] = '\0'; // Remove newline character
        bundle->items[bundle->num_items] = (char *)malloc((strlen(buffer) + 1) * sizeof(char));
        if (!bundle->items[bundle->num_items]) {
            perror("Failed to allocate memory for item");
            for (int i = 0; i < bundle->num_items; i++) {
                free(bundle->items[i]);
            }
            free(bundle->items);
            fclose(file);
            return -1; // Return error code for failure
        }
        strcpy(bundle->items[bundle->num_items], buffer);
        bundle->num_items++;
    }

    fclose(file);
    return 0; // Success
}
