#define L_BUFSIZE 1024

typedef struct {
    char *line;
} Line;

Line* readLine(FILE *fp) {
    char buf[L_BUFSIZE];
    if (fgets(buf, sizeof(buf), fp) != NULL) {
        Line *line = (Line *)malloc(sizeof(Line));
        line->line = strdup(buf);
        return line;
    }
    return NULL;
}

void printCommaSeparated(Line **lines, int numLines) {
    for (int i = 0; i < numLines; i++) {
        char *token = strtok(lines[i]->line, " \t\n");
        while (token != NULL) {
            printf("%s", token);
            if (i == numLines - 1 && token == strtok(NULL, " \t\n")) {
                float sum = 0;
                int count = 0;
                char *lastToken = NULL;
                while (token != NULL) {
                    lastToken = token;
                    sum += atof(token);
                    count++;
                    token = strtok(NULL, " \t\n");
                }
                if (count >= 2) {
                    printf(",%.2f", sum / count);
                } else {
                    printf(",0.00"); // Handle case where there are less than 2 numbers
                }
            } else {
                printf(",");
            }
            token = strtok(NULL, " \t\n");
        }
        printf("\n");
    }
}

void freeLines(Line **lines, int numLines) {
    for (int i = 0; i < numLines; i++) {
        free(lines[i]->line);
        free(lines[i]);
    }
    free(lines);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return 1;
    }

    FILE *fp = fopen(argv[1], "r");
    if (!fp) {
        perror("Error opening file");
        return 1;
    }

    Line **lines = (Line **)malloc(sizeof(Line *) * L_BUFSIZE);
    int numLines = 0;
    while ((lines[numLines] = readLine(fp)) != NULL) {
        numLines++;
        if (numLines >= L_BUFSIZE) {
            L_BUFSIZE *= 2;
            lines = (Line **)realloc(lines, sizeof(Line *) * L_BUFSIZE);
        }
    }

    printCommaSeparated(lines, numLines);
    freeLines(lines, numLines);
    fclose(fp);
    return 0;
}
