#include <stdlib.h>

typedef struct BSTNode {
    int offset;
    struct BSTNode *left, *right;
} BSTNode;

BSTNode* createNode(int offset) {
    BSTNode* newNode = (BSTNode*)malloc(sizeof(BSTNode));
    if (newNode == NULL) {
        return NULL; // Allocation failed
    }
    newNode->offset = offset;
    newNode->left = newNode->right = NULL;
    return newNode;
}

BSTNode* insert(BSTNode** root, int offset) {
    if (*root == NULL) {
        *root = createNode(offset);
        return *root;
    }
    
    BSTNode* current = *root;
    while (1) {
        if (offset < current->offset) {
            if (current->left == NULL) {
                current->left = createNode(offset);
                return current->left;
            }
            current = current->left;
        } else if (offset > current->offset) {
            if (current->right == NULL) {
                current->right = createNode(offset);
                return current->right;
            }
            current = current->right;
        } else {
            // Offset already exists, do nothing or handle as needed
            return current;
        }
    }
}
