#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <errno.h>

#define BUFFER_SIZE 1024

typedef struct {
    int socket;
    struct sockaddr_in server_address;
} udp_client_t;

udp_client_t *create_udp_client(const char *server_ip, int port) {
    udp_client_t *client = (udp_client_t *)malloc(sizeof(udp_client_t));
    if (!client) {
        perror("Failed to allocate memory for UDP client");
        return NULL;
    }

    client->socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (client->socket < 0) {
        perror("Failed to create socket");
        free(client);
        return NULL;
    }

    memset(&client->server_address, 0, sizeof(client->server_address));
    client->server_address.sin_family = AF_INET;
    client->server_address.sin_port = htons(port);
    inet_pton(AF_INET, server_ip, &client->server_address.sin_addr);

    return client;
}

int receive_file(udp_client_t *client, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        close(client->socket);
        free(client);
        return -1;
    }

    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;
    while ((bytes_received = recvfrom(client->socket, buffer, BUFFER_SIZE, 0, NULL, NULL)) > 0) {
        if (fwrite(buffer, 1, bytes_received, file) != bytes_received) {
            perror("Failed to write to file");
            fclose(file);
            close(client->socket);
            free(client);
            return -1;
        }
    }

    if (bytes_received < 0) {
        perror("Failed to receive data");
        fclose(file);
        close(client->socket);
        free(client);
        return -1;
    }

    fclose(file);
    close(client->socket);
    free(client);
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <server_ip> <port> <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *server_ip = argv[1];
    int port = atoi(argv[2]);
    const char *filename = argv[3];

    udp_client_t *client = create_udp_client(server_ip, port);
    if (!client) {
        return EXIT_FAILURE;
    }

    if (receive_file(client, filename) < 0) {
        return EXIT_FAILURE;
    }

    printf("File received and saved as %s\n", filename);
    return EXIT_SUCCESS;
}
