    int show_manpage = 0;
    int cstyle_highlighting = 0;

    while ((opt = getopt(argc, argv, "o:cs-:")) != -1) {
        switch (opt) {
            case 'o':
                outputfile = optarg;
                break;
            case 'c':
                cstyle_highlighting = 1;
                break;
            case 's':
                // Assuming '-s' is for something else, not used in this example.
                break;
            case ':':
                fprintf(stderr, "Option -%c requires an argument.\n", optopt);
                print_usage();
                return 1;
            case '?':
                if (isprint(optopt)) {
                    fprintf(stderr, "Unknown option `-%c'.\n", optopt);
                } else {
                    fprintf(stderr, "Unknown option character `\\x%x'.\n", optopt);
                }
                print_usage();
                return 1;
            case '-':
                if (strcmp(optarg, "manpage") == 0) {
                    show_manpage = 1;
                } else if (strcmp(optarg, "cs") == 0) {
                    cstyle_highlighting = 1;
                } else if (strcmp(optarg, "o") == 0) {
                    // This is handled above by 'o' option.
                } else {
                    fprintf(stderr, "Unknown long option `--%s'.\n", optarg);
                    print_usage();
                    return 1;
                }
                break;
            default:
                // This should not happen as we handle all options above.
                abort();
        }
    }

    if (show_manpage) {
        printf("Manpage information here...\n");
        return 0;
    }

    // If no input file is provided, print usage and exit.
    if (optind >= argc) {
        fprintf(stderr, "No input file provided.\n");
