// Define a structure for context parameters
typedef struct {
    char config_file_path[256];
    char log_file_path[256];
    char service_root_dir[256];
    char network_address[128];
} Context;

// Function to initialize the context structure
void init_context(Context *ctx, const char *config_file, const char *log_file, const char *service_root) {
    strncpy(ctx->config_file_path, config_file, sizeof(ctx->config_file_path));
    ctx->config_file_path[sizeof(ctx->config_file_path) - 1] = '\0'; // Ensure null-termination

    strncpy(ctx->log_file_path, log_file, sizeof(ctx->log_file_path));
    ctx->log_file_path[sizeof(ctx->log_file_path) - 1] = '\0'; // Ensure null-termination

    strncpy(ctx->service_root_dir, service_root, sizeof(ctx->service_root_dir));
    ctx->service_root_dir[sizeof(ctx->service_root_dir) - 1] = '\0'; // Ensure null-termination

    ctx->network_address[0] = '\0'; // Initialize as empty string
}

// Function to set the network address from command line argument
void set_network_address(Context *ctx, const char *arg) {
    if (arg != NULL && strlen(arg) > 0) {
        strncpy(ctx->network_address, arg, sizeof(ctx->network_address));
        ctx->network_address[sizeof(ctx->network_address) - 1] = '\0'; // Ensure null-termination
    }
}

// Main function to demonstrate usage of the context structure
int main(int argc, char *argv[]) {
    Context ctx;

    init_context(&ctx, "config.txt", "log.txt", "/srv/service");

    if (argc > 1) {
        set_network_address(&ctx, argv[1]);
    }

    printf("Config File Path: %s\n", ctx.config_file_path);
    printf("Log File Path: %s\n", ctx.log_file_path);
    printf("Service Root Directory: %s\n", ctx.service_root_dir);
    printf("Network Address: %s\n", ctx.network_address);

    return 0;
}
