    uint16_t samplesPerPixel, bitsPerSample;
    TIFFGetField(in, TIFFTAG_IMAGEWIDTH, &width);
    TIFFGetField(in, TIFFTAG_IMAGELENGTH, &height);
    TIFFGetField(in, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel);
    TIFFGetField(in, TIFFTAG_BITSPERSAMPLE, &bitsPerSample);

    // Set up output file with the same parameters as input
    TIFFSetField(out, TIFFTAG_IMAGEWIDTH, width);
    TIFFSetField(out, TIFFTAG_IMAGELENGTH, height);
    TIFFSetField(out, TIFFTAG_SAMPLESPERPIXEL, samplesPerPixel);
    TIFFSetField(out, TIFFTAG_BITSPERSAMPLE, bitsPerSample);
    TIFFSetField(out, TIFFTAG_COMPRESSION, COMPRESSION_LZW); // Example compression type
    TIFFSetField(out, TIFFTAG_PHOTOMETRIC, PHOTOMETRIC_RGB); // Adjust based on input

    uint32_t row;
    for (row = 0; row < height; row++) {
        if (TIFFReadScanline(in, buf + row * width * samplesPerPixel, row, 0) == -1) {
            TIFFError("compressTIFF", "Error reading scanline %d", row);
            TIFFClose(out);
            free(buf);
            return 0; // Failed to read scanline
        }

        // Reverse the order of pixels in each scanline
        uint8_t *scanline = buf + row * width * samplesPerPixel;
        for (uint32_t i = 0; i < width * samplesPerPixel / 2; i++) {
            uint8_t temp = scanline[i];
            scanline[i] = scanline[(width * samplesPerPixel) - 1 - i];
            scanline[(width * samplesPerPixel) - 1 - i] = temp;
        }

        if (TIFFWriteScanline(out, buf + row * width * samplesPerPixel, row, 0) == -1) {
            TIFFError("compressTIFF", "Error writing scanline %d", row);
            TIFFClose(out);
            free(buf);
            return 0; // Failed to write scanline
        }
    }

    TIFFClose(out);
    free(buf);
    return 1; // Success
}
