// Function to calculate the average size of a dataset and allocate an array for distribution
double* calculate_average_size(int *data, int num_items, int num_blocks, double reserved_size) {
    // Calculate total number of items including reserved size
    int total_items = num_items + (num_blocks * reserved_size);
    
    // Allocate memory for the distribution array
    double* distribution = (double*)malloc(total_items * sizeof(double));
    if (!distribution) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    
    // Calculate average size and populate the distribution array
    double sum = 0.0;
    for (int i = 0; i < num_items; ++i) {
        sum += data[i];
    }
    
    double average = sum / num_items;
    
    // Populate the distribution array with the average size and reserved sizes
    for (int i = 0; i < num_items; ++i) {
        distribution[i] = data[i];
    }
    for (int i = num_items; i < total_items; ++i) {
        distribution[i] = average + reserved_size;
    }
    
    return distribution;
}
