// Function to create a complex matrix with given number of rows and columns
complex double** create_complex_matrix(int rows, int cols) {
    // Allocate memory for the row pointers
    complex double** matrix = (complex double**)malloc(rows * sizeof(complex double*));
    if (!matrix) {
        return NULL; // Return NULL if memory allocation fails
    }

    // Allocate memory for each row and initialize it to zero
