        if (!matrix[i]) {
            // Free previously allocated memory in case of failure
            for (int j = 0; j < i; ++j) {
                free(matrix[j]);
            }
            free(matrix);
            return NULL; // Return NULL if memory allocation fails
        }
    }

    return matrix;
}
