TIGValue* concatenateStrings(const char *str1, const char *str2, int index) {
    if (index < 0 || index > strlen(str1)) {
        return NULL; // Invalid index
    }

    size_t len1 = strlen(str1);
    size_t len2 = strlen(str2);
    TIGValue *result = (TIGValue *)malloc(sizeof(TIGValue));
    if (!result) {
        return NULL; // Memory allocation failed
    }

    result->length = len1 + len2;
    result->data = (char *)malloc(result->length + 1);
    if (!result->data) {
        free(result);
        return NULL; // Memory allocation failed
    }

    strncpy(result->data, str1, index);
    strcpy(result->data + index, str2);
    strcpy(result->data + index + len2, str1 + index);

    result->data[result->length] = '\0'; // Null-terminate the string

    return result;
}
