#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Scheduler {
    pthread_t *threads;
    int num_threads;
    int *suspension_thresholds;
    int *cpu_assignments;
    pthread_mutex_t mutex;
} Scheduler;

Scheduler* init_scheduler(int num_threads, void* (*thread_func)(void*), int *cpu_assignments) {
    Scheduler *sched = (Scheduler *)malloc(sizeof(Scheduler));
    sched->num_threads = num_threads;
    sched->threads = (pthread_t *)malloc(num_threads * sizeof(pthread_t));
    sched->suspension_thresholds = (int *)malloc(num_threads * sizeof(int));
    sched->cpu_assignments = cpu_assignments;

    pthread_mutex_init(&sched->mutex, NULL);

    for (int i = 0; i < num_threads; i++) {
        if (pthread_create(&sched->threads[i], NULL, thread_func, &sched->suspension_thresholds[i]) != 0) {
            perror("Failed to create thread");
            exit(EXIT_FAILURE);
        }
        // Assign CPU based on cpu_assignments array
        if (pthread_setaffinity_np(sched->threads[i], sizeof(cpu_set_t), &cpu_assignments[i]) != 0) {
            perror("Failed to set thread affinity");
            exit(EXIT_FAILURE);
        }
    }

    return sched;
}
