struct Server* parse_servers(const char* server_list) {
    if (server_list == NULL || strlen(server_list) == 0) return NULL;

    struct Server* servers = NULL;
    size_t count = 0;
    size_t capacity = 10; // Initial capacity for the list of servers

    servers = (struct Server*)malloc(capacity * sizeof(struct Server));
    if (servers == NULL) {
        return NULL; // Allocation failed
    }

    char* str = strdup(server_list); // Duplicate the input string to avoid modifying it
    if (str == NULL) {
        free(servers); // Free allocated memory in case of allocation failure
        return NULL; // Allocation failed
    }

    char* token = strtok(str, ", ");
    while (token != NULL) {
        struct Server server;
        char* colon = strchr(token, ':');
        if (colon == NULL || colon == token || *(colon - 1) != ':' || isspace(*(colon + 1))) {
            // Invalid format for a server entry
            free(str);
            free(servers);
            return NULL;
        }
        *colon = '\0'; // Null-terminate the hostname part
        strcpy(server.hostname, token);
        server.port = atoi(colon + 1);
        if (count >= capacity) {
            capacity *= 2;
            struct Server* new_servers = (struct Server*)realloc(servers, capacity * sizeof(struct Server));
            if (new_servers == NULL) {
                free(str);
                free(servers);
                return NULL; // Allocation failed
            }
            servers = new_servers;
        }
        servers[count++] = server;
        token = strtok(NULL, ", ");
    }

    free(str);
    if (count < capacity && count > 0) { // If not all slots are used but some were allocated
        struct Server* new_servers = (struct Server*)realloc(servers, count * sizeof(struct Server));
        if (new_servers != NULL) {
            servers = new_servers;
        }
    }

    return servers;
}
