#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *data;
    int top;
} Stack;

Stack* create_stack(int size) {
    Stack *stack = (Stack *)malloc(sizeof(Stack));
    stack->data = (char *)malloc(size);
    stack->top = -1;
    return stack;
}

void push(Stack *stack, char c) {
    if (stack->top == -1 || stack->top < 999) { // Assuming max size of 1000 characters for simplicity
        stack->data[++stack->top] = c;
    } else {
        printf("Stack overflow\n");
    }
}

char pop(Stack *stack) {
    if (stack->top >= 0) {
        return stack->data[stack->top--];
    } else {
        printf("Stack underflow\n");
        return '\0'; // Return null character for underflow
    }
}

void process_input(const char *input) {
    int size = strlen(input) + 2; // Adding space for newline and null terminator
    Stack *stack = create_stack(size);

    // Copy input to stack
    for (int i = 0; i < strlen(input); i++) {
        push(stack, input[i]);
    }

    // Append newline character
    push(stack, '\n');

    // Parse the line into a function call and its arguments (simplified example)
    char *line = (char *)malloc(size);
    int index = 0;
    while (stack->top >= 0) {
        line[index++] = pop(stack);
    }
    line[index] = '\0'; // Null-terminate the string

    printf("Processed line: %s", line);

    free(line);
    free(stack->data);
    free(stack);
}

int main() {
    const char *input = "function_call arg1 arg2";
    process_input(input);
    return 0;
}
