#include <stdlib.h>
#include <string.h>
#include <stdio.h>

void* xcalloc(size_t num, size_t size) {
    size_t res;
    if (check_mul_overflow(num, size, &res))
        abort();

    void *ptr = malloc(res);
    if (ptr) {
        memset(ptr, '\0', res);
    }
    return ptr;
}

int check_mul_overflow(size_t a, size_t b, size_t *result) {
    // Check for overflow
    if (b != 0 && a > SIZE_MAX / b) {
        return 1;
    }
    *result = a * b;
    return 0;
}

// Function to create a symmetric matrix dynamically
int** create_symmetric_matrix(size_t size) {
    // Calculate the required memory for the matrix
    size_t matrix_size = (size * (size + 1)) / 2;
    int* data = (int*)xcalloc(matrix_size, sizeof(int));

    // Allocate memory for the rows of the matrix
    int** matrix = (int**)malloc(size * sizeof(int*));
    if (!matrix) {
        free(data);
        return NULL;
    }

    size_t index = 0;
    for (size_t i = 0; i < size; ++i) {
        matrix[i] = &data[index];
        index += (size - i);
    }

    return matrix;
}

// Function to free a symmetric matrix
void free_symmetric_matrix(int** matrix, size_t size) {
    if (!matrix) {
        return;
    }
    free((int*)*matrix); // Free the underlying data array
    free(matrix);         // Free the row pointers
}

// Example usage
int main() {
    size_t size = 3;
    int** matrix = create_symmetric_matrix(size);

    if (!matrix) {
        printf("Failed to allocate memory for symmetric matrix.\n");
        return 1;
    }

    // Assign values to the symmetric matrix
    matrix[0][0] = 1;
    matrix[1][0] = 2; matrix[1][1] = 3;
    matrix[2][0] = 4; matrix[2][1] = 5; matrix[2][2] = 6;

    // Print the symmetric matrix
    for (size_t i = 0; i < size; ++i) {
        for (size_t j = 0; j <= i; ++j) {
            printf("%d ", matrix[i][j]);
        }
        printf("\n");
    }

    // Free the symmetric matrix
    free_symmetric_matrix(matrix, size);

    return 0;
}
