char* read_line_from_stdin() {
    fd_set readfds;
    struct timeval timeout;
    int maxfd = 0, ret;
    char buffer[1024];
    size_t bufsize = sizeof(buffer) - 1;
    ssize_t bytesread;
    char* line = NULL;
    size_t linesize = 0;

    while (1) {
        FD_ZERO(&readfds);
        FD_SET(STDIN_FILENO, &readfds);
        maxfd = STDIN_FILENO + 1;

        timeout.tv_sec = 0;
        timeout.tv_usec = 0;

        ret = select(maxfd, &readfds, NULL, NULL, &timeout);
        if (ret < 0) {
            perror("select");
            free(line);
            return NULL;
        } else if (ret == 0) {
            break; // Timeout or no data available
        }

        bytesread = read(STDIN_FILENO, buffer, bufsize);
        if (bytesread < 0) {
            perror("read");
            free(line);
            return NULL;
        } else if (bytesread == 0) {
            break; // End of input
        }

        buffer[bytesread] = '\0';
        size_t newlinesize = linesize + bytesread;
        char* newline = realloc(line, newlinesize + 1);
        if (!newline) {
            free(line);
            return NULL;
        }
        line = newline;
        strncpy(line + linesize, buffer, bytesread);
        linesize = newlinesize;

        // Check for newline character
        char* nlpos = strchr(line, '\n');
        if (nlpos) {
            size_t linelen = nlpos - line + 1;
            memmove(line, line, linelen);
            line[linelen] = '\0';
            return line;
        }
    }

    // Return the collected line (null-terminated)
    if (linesize > 0 && line[linesize - 1] == '\n') {
        line[linesize - 1] = '\0';
    } else {
        line = realloc(line, linesize + 1);
        if (!line) {
            return NULL;
        }
        line[linesize] = '\0';
    }

    return line;
}
