#define BUFFER_SIZE 1024

typedef struct {
    FILE *fp;
    char buffer[BUFFER_SIZE];
    int buf_pos;
    int buf_len;
} LineBuffer;

void init_line_buffer(LineBuffer *lb, FILE *file) {
    lb->fp = file;
    lb->buf_pos = 0;
    lb->buf_len = 0;
}

char* read_line(LineBuffer *lb) {
    int pos = 0;
    char c;
    while ((c = fgetc(lb->fp)) != EOF) {
        if (pos < BUFFER_SIZE - 1) {
            lb->buffer[pos++] = c;
        }
        if (c == '\n') {
            break;
        }
    }
    if (pos == 0 && c == EOF) {
        return NULL;
    }
    lb->buffer[pos] = '\0';
    char *line = (char *)malloc(pos + 1);
    strcpy(line, lb->buffer);
    return line;
}

void push_back_line(LineBuffer *lb, const char *line) {
    int len = strlen(line);
    if (len >= BUFFER_SIZE) {
        fprintf(stderr, "Push back buffer overflow\n");
        return;
    }
    for (int i = 0; i < len; i++) {
        lb->buffer[i] = line[i];
    }
    lb->buf_pos = len;
}

char* get_next_line(LineBuffer *lb) {
    if (lb->buf_pos < lb->buf_len) {
        char *line = (char *)malloc(lb->buf_pos + 1);
        strncpy(line, lb->buffer, lb->buf_pos);
        line[lb->buf_pos] = '\0';
        return line;
    } else {
        return read_line(lb);
    }
}
