#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char** create_http_request(const char* verb, const char* path, const char* http_version) {
    // Calculate the length of each string and the total number of characters needed
    size_t verb_len = strlen(verb);
    size_t path_len = strlen(path);
    size_t version_len = strlen(http_version);
    size_t space_len = 2; // for two spaces between parts and one for the null terminator at the end of each string
    size_t total_len = verb_len + path_len + version_len + space_len * 3 + 1; // +1 for the final newline character

    // Allocate memory for the array of strings and the buffer to hold the combined request
    char* buffer = (char*)malloc(total_len);
    if (!buffer) {
        return NULL; // Allocation failed
    }

    // Combine the input strings with spaces in between
    snprintf(buffer, total_len, "%s %s HTTP/%s\n", verb, path, http_version);

    // Allocate memory for the array of string pointers
    char** request = (char**)malloc((total_len / sizeof(char)) * sizeof(char*));
    if (!request) {
        free(buffer);
        return NULL; // Allocation failed
    }

    // Set the first element to point to the buffer which contains the entire request string
    request[0] = buffer;

    return request;
}
