#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int type;
    char name[50];
} Card;

typedef struct Node {
    Card card;
    struct Node* next;
} Node;

Node* createNode(Card card) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->card = card;
    newNode->next = NULL;
    return newNode;
}

void addToLinkedList(Node** head, Card card) {
    Node* newNode = createNode(card);
    if (*head == NULL) {
        *head = newNode;
    } else {
        Node* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = newNode;
    }
}

void fisherYatesShuffle(Card deck[], int n, unsigned int (*hash)(const char*)) {
    srand((unsigned int)time(NULL));
    for (int i = n - 1; i > 0; i--) {
        int j = hash(deck[i].name) % (i + 1);
        Card temp = deck[i];
        deck[i] = deck[j];
        deck[j] = temp;
    }
}

unsigned int simpleHash(const char* str) {
    unsigned int hash = 0;
    while (*str) {
        hash = (hash << 5) - hash + *str++;
    }
    return hash;
}

Node* shuffleDeck(Card deck[], int n, unsigned int (*hash)(const char*)) {
    fisherYatesShuffle(deck, n, hash);
    Node* head = NULL;
    for (int i = 0; i < n; i++) {
        addToLinkedList(&head, deck[i]);
    }
    return head;
}
