// Function to initialize AES-256-CBC cipher with a given password
EVP_CIPHER_CTX* init_aes_256_cbc(const char* password) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        return NULL;
    }

    // Fixed IV length for AES-256-CBC
    unsigned int iv_length = 16;
    unsigned char iv[iv_length];
    memset(iv, 0, iv_length); // Initialize IV to zero (or use a secure random generator)

    // Derive the key from the password using SHA-1
    unsigned char key[SHA256_DIGEST_LENGTH];
    SHA1((unsigned char*)password, strlen(password), key);

    // Initialize the cipher context with AES-256-CBC and the derived key/IV
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

// Function to clean up and disable the cipher when it is no longer needed
void cleanup_cipher(EVP_CIPHER_CTX* ctx) {
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
