#include <dirent.h>
#include <stdlib.h>
#include <string.h>

struct DirEntry {
    char name[256]; // Assuming a maximum directory name length of 255 characters + null terminator
    int type; // File type (e.g., DT_DIR, DT_REG)
};

struct DirectoryTree {
    struct DirEntry entry;
    struct DirectoryTree *subdirectories[10]; // Assuming a maximum of 10 subdirectories for simplicity
    int subdirectoryCount;
};

struct PathTable {
    char **paths;
    int count;
};

void initPathTable(struct PathTable *table) {
    table->count = 0;
    table->paths = malloc(10 * sizeof(char*)); // Initial allocation for 10 paths
}

void addToPathTable(struct PathTable *table, const char *path) {
    if (table->count >= 10) { // Reallocate if needed
        table->paths = realloc(table->paths, (table->count + 10) * sizeof(char*));
    }
    table->paths[table->count++] = strdup(path);
}

struct DirectoryTree* findDirectoryByPath(const char *rootPath, const char *targetPath) {
    struct PathTable pathTable;
    initPathTable(&pathTable);
    addToPathTable(&pathTable, targetPath);

    DIR *dir = opendir(rootPath);
    if (!dir) {
        perror("opendir");
        return NULL;
    }

    struct DirectoryTree *currentDir = malloc(sizeof(struct DirectoryTree));
    strcpy(currentDir->entry.name, rootPath);
    currentDir->entry.type = DT_DIR;
    currentDir->subdirectoryCount = 0;

    for (int i = 0; i < pathTable.count; ++i) {
        struct dirent *ent;
        while ((ent = readdir(dir)) != NULL) {
            if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0) {
                continue;
            }
            if (DT_DIR == ent->d_type && strcmp(ent->d_name, pathTable.paths[i] + strlen(rootPath)) == 0) {
                // Found the directory, move to it and continue
                closedir(dir);
                dir = opendir(ent->d_name);
                if (!dir) {
                    perror("opendir");
                    return NULL;
                }
                strcpy(currentDir->entry.name, ent->d_name);
                break;
            }
        }
    }

    closedir(dir);
    // Free the path table as it's no longer needed
    for (int i = 0; i < pathTable.count; ++i) {
        free(pathTable.paths[i]);
    }
    free(pathTable.paths);

    return currentDir;
}
