#include <string.h>

char* remove_trailing_newlines(char* line) {
    // Find the length of the string
    int len = strlen(line);
    
    // Remove trailing newlines or carriage returns
    while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r')) {
        if (line[len - 1] == '\r' && len > 1 && line[len - 2] == '\n') {
            // If we have \r\n, remove both characters
            len -= 2;
        } else {
            // Otherwise, just remove the single character
            len--;
        }
    }
    
    // Append a newline character to the end of the string
    line[len] = '\n';
    line[len + 1] = '\0';
    
    return line;
}
