    // Copy the substring to be inserted
    memcpy(new_str + pos, substr, substr_len);
    // Copy the rest of the original string after the insertion point
    memcpy(new_str + pos + substr_len, str + pos, str_len - pos);

    // Null-terminate the new string and free the old one if necessary
    new_str[new_len] = '\0';
    free(str); // Free the original string memory

