Blob* create_blob(int max_x, int max_y) {
    Blob *new_blob = (Blob*)malloc(sizeof(Blob));
    new_blob->x = rand() % max_x;
    new_blob->y = rand() % max_y;
    new_blob->lifetime = rand() % 10 + 5; // Random lifetime between 5 and 14
    new_blob->next = NULL;
    return new_blob;
}

void update_blobs(Blob **head, int max_x, int max_y) {
    Blob *current = *head;
    while (current != NULL) {
        current->lifetime--;
        if (current->lifetime <= 0) {
            // Remove the blob from the list
            Blob *temp = current;
            current = current->next;
            free(temp);
        } else {
            // Update position randomly within bounds
            current->x = (current->x + rand() % 3 - 1) % max_x;
            current->y = (current->y + rand() % 3 - 1) % max_y;
            current = current->next;
        }
    }
}

void add_blob(Blob **head, int max_x, int max_y) {
    Blob *new_blob = create_blob(max_x, max_y);
    new_blob->next = *head;
    *head = new_blob;
}

void print_blobs(Blob *head) {
