typedef struct Edge {
    int dest;
    struct Edge* next;
} Edge;

typedef struct Vertex {
    Edge* head;
} Vertex;

typedef struct Graph {
    int numVertices;
    Vertex* vertices;
} Graph;

Graph* createGraph(int numVertices) {
    Graph* graph = (Graph*)malloc(sizeof(Graph));
    graph->numVertices = numVertices;
    graph->vertices = (Vertex*)malloc(numVertices * sizeof(Vertex));
    
    for (int i = 0; i < numVertices; ++i) {
        graph->vertices[i].head = NULL;
    }
    
    return graph;
}

void addEdge(Graph* graph, int src, int dest) {
    Edge* newEdge = (Edge*)malloc(sizeof(Edge));
    newEdge->dest = dest;
    newEdge->next = graph->vertices[src].head;
    graph->vertices[src].head = newEdge;
}

void displayGraph(Graph* graph) {
    for (int i = 0; i < graph->numVertices; ++i) {
        printf("Vertex %d: ", i);
        Edge* temp = graph->vertices[i].head;
        while (temp != NULL) {
            printf("%d -> ", temp->dest);
            temp = temp->next;
        }
        printf("NULL\n");
    }
}

void modifyVertex(Graph* graph, int vertex, int newDest) {
    Edge* temp = graph->vertices[vertex].head;
    while (temp != NULL) {
        temp->dest = newDest;
        temp = temp->next;
    }
}

void insertNewVertex(Graph* graph, int src, int dest) {
    addEdge(graph, src, dest);
}

int main() {
    int numVertices, numEdges;
    printf("Enter the number of vertices: ");
    scanf("%d", &numVertices);
    
