        printf("Enter edge %d (source destination): ", i + 1);
        scanf("%d %d", &src, &dest);
        addEdge(graph, src, dest);
    }
    
    displayGraph(graph);
    
    int vertexToModify, newDest;
    printf("Enter the vertex to modify: ");
    scanf("%d", &vertexToModify);
    printf("Enter the new destination for all edges of this vertex: ");
    scanf("%d", &newDest);
    
    modifyVertex(graph, vertexToModify, newDest);
    displayGraph(graph);
    
    int srcNewVertex, destNewVertex;
    printf("Enter the source and destination for the new vertex: ");
    scanf("%d %d", &srcNewVertex, &destNewVertex);
    
    insertNewVertex(graph, srcNewVertex, destNewVertex);
    displayGraph(graph);
    
    return 0;
}
