    char buffer[BUFSIZE];
    FILE *file;

    // Create socket
    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Socket creation error");
        return -1;
    }

    // Define server address
    memset(&server_addr, '0', sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80); // Assuming port 80 for HTTP (change if necessary)
    if (inet_pton(AF_INET, ip_address, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        return -1;
    }

    // Connect to server
    if (connect(sock, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection failed");
        return -1;
    }

    // Send request packet
    char request[256];
    snprintf(request, sizeof(request), "GET /%s HTTP/1.1\r\nHost: %s\r\nConnection: close\r\n\r\n", filename, ip_address);
    if (send(sock, request, strlen(request), 0) < 0) {
        perror("Send failed");
        return -1;
    }

    // Receive response packet
    int bytes_received = 0;
    char *response = malloc(BUFSIZE);
    if (!response) {
        perror("Memory allocation error");
        return -1;
    }
    memset(response, 0, BUFSIZE);

    while ((bytes_received = recv(sock, response + bytes_received, BUFSIZE - bytes_received, 0)) > 0) {
        // Write to file
        if (mode[0] == 'w') {
            file = fopen(filename, "wb");
            if (!file) {
                perror("File creation error");
                free(response);
                close(sock);
                return -1;
            }
            if (fwrite(response, 1, bytes_received, file) != bytes_received) {
                perror("File write error");
                fclose(file);
                free(response);
                close(sock);
                return -1;
            }
            fclose(file);
        } else if (mode[0] == 'r') {
            file = fopen(filename, "rb");
            if (!file) {
                perror("File opening error");
                free(response);
                close(sock);
                return -1;
            }
            while ((bytes_received = fread(buffer, 1, BUFSIZE, file)) > 0) {
                if (send(sock, buffer, bytes_received, 0) < 0) {
