#include <stdio.h>
#include <string.h>

typedef struct {
    char *key;
    void *value;
    int active;
} pair_t;

typedef struct {
    pair_t *pairs;
    size_t capacity;
    size_t count;
} bucket_t;

typedef struct {
    bucket_t *buckets;
    size_t order;
} hashtable_t;

size_t hash_str(const char *str) {
    size_t hash = 5381;
    int c;
    while ((c = *str++)) {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash;
}

size_t hashmask(size_t hm) {
    return (1UL << hm) - 1;
}

pair_t* hashtable_find_pair(hashtable_t *hashtable, bucket_t *bucket, const char *key, size_t hash) {
    for (size_t i = 0; i < bucket->count; ++i) {
        if (bucket->pairs[i].active && strcmp(bucket->pairs[i].key, key) == 0) {
            return &bucket->pairs[i];
        }
    }
    return NULL;
}

int hashtable_get(hashtable_t *hashtable, const char *key, void **value) {
    size_t hash = hash_str(key);
    bucket_t *bucket = &hashtable->buckets[hash & hashmask(hashtable->order)];
    pair_t *pair = hashtable_find_pair(hashtable, bucket, key, hash);
    
    if (!pair || !pair->active) {
        return -1; // Key not found or value is not active
    }

    *value = pair->value;
    return 0; // Success
}
