#define MAX_WORD_LENGTH 100

// Function to read all words from a file into an array
char** readWords(const char* filename, int* wordCount) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        exit(EXIT_FAILURE);
    }

    // Count the number of words in the file
    *wordCount = 0;
    char word[MAX_WORD_LENGTH];
    while (fscanf(file, "%s", word) != EOF) {
        (*wordCount)++;
    }

    // Allocate memory for the array of words
    char** words = malloc(*wordCount * sizeof(char*));
    if (!words) {
        perror("Error allocating memory");
        fclose(file);
        exit(EXIT_FAILURE);
    }

    // Reset file pointer to beginning and read words again
    rewind(file);
    int i = 0;
    while (fscanf(file, "%s", word) != EOF) {
        words[i] = malloc((strlen(word) + 1) * sizeof(char));
        strcpy(words[i], word);
        i++;
    }

    fclose(file);
    return words;
}

// Function to find all unique word pairs
void findUniqueWordPairs(char** words, int wordCount) {
    char lastFirstWord[MAX_WORD_LENGTH];
    for (int i = 0; i < wordCount - 1; i++) {
        if (i == 0 || strcmp(words[i], lastFirstWord) != 0) {
            for (int j = i + 1; j < wordCount; j++) {
                printf("%s %s\n", words[i], words[j]);
            }
            strcpy(lastFirstWord, words[i]);
        }
    }
}

// Function to free the allocated memory for words
void freeWords(char** words, int wordCount) {
    for (int i = 0; i < wordCount; i++) {
        free(words[i]);
    }
    free(words);
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <filename>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int wordCount;
    char** words = readWords(argv[1], &wordCount);
    findUniqueWordPairs(words, wordCount);
    freeWords(words, wordCount);

    return 0;
}
