JsonValueType determineType(const char *str) {
    int hasDot = 0;
    for (int i = 0; str[i] != '\0'; i++) {
        if (str[i] == '.') {
            hasDot = 1;
            break;
        }
    }
    return hasDot ? JSON_VALUE_TYPE_FLOATING_POINT : JSON_VALUE_TYPE_INTEGER;
}

double parseStringToNumber(const char *str) {
    double result = 0.0;
    int isNegative = 0;
    int i = 0;

    // Handle negative sign if present
    if (str[i] == '-') {
        isNegative = 1;
        i++;
    }

    // Parse integer part
    while (isdigit(str[i])) {
        result = result * 10 + (str[i] - '0');
        i++;
    }

    // Parse fractional part if present
    if (str[i] == '.') {
        double fractionFactor = 0.1;
        i++;
        while (isdigit(str[i])) {
            result += (str[i] - '0') * fractionFactor;
            fractionFactor *= 0.1;
            i++;
        }
    }

    // Apply negative sign if necessary
    return isNegative ? -result : result;
}

void parseString(const char *str, JsonValueType *type) {
    int len = strlen(str);
    for (int i = 0; i < len; i++) {
        if (!isspace((unsigned char)str[i])) {
            break;
        }
        if (i == len - 1) {
            *type = JSON_VALUE_TYPE_INTEGER; // Assuming integer is the default type for empty strings after trimming whitespace
