        free(offsets);
        exit(EXIT_FAILURE);
    }

    // Allocate memory for 'record' structures array
    record *records = (record *)malloc(num_records * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    // Initialize the arrays with random values within the given range
    for (int i = 0; i < num_records; i++) {
        offsets[i] = rand() % 1000 + 1; // Random long value between 1 and 1000
        keys[i] = rand() % (max_value - min_value + 1) + min_value; // Random int value within the range [min_value, max_value]
