        if (temp[strlen(temp) - 1] != '/') {
            strncat(temp, "/", PATH_MAX - strlen(temp) - 1);
        }
    }
    
    // Concatenate the given path to the temporary buffer
    if (path) {
        strncat(temp, path, PATH_MAX - strlen(temp) - 1);
