void insertLineAtCursor(HWND hwnd) {
    // Get the current cursor position in the edit control
    DWORD pos = SendMessage(hwnd, EM_GETSEL, 0, 0);
    int startPos = LOWORD(pos);
    int endPos = HIWORD(pos);

