        std::cerr << "Invalid image dimensions." << std::endl;
        return nullptr; // Return a reset image or handle the error as needed.
    }

    Image* img = new Image{nullptr, sx, sy};
    if (!img) {
        std::cerr << "Memory allocation failed for image structure." << std::endl;
        return nullptr; // Return a reset image or handle the error as needed.
