    // Allocate memory for the rows of the image
    img->data = new unsigned char*[sy];
    if (!img->data) {
        std::cerr << "Memory allocation failed for image data." << std::endl;
        delete img;
        return nullptr; // Return a reset image or handle the error as needed.
    }

    // Allocate memory for each row and initialize it to zero
    for (int i = 0; i < sy; ++i) {
        img->data[i] = new unsigned char[sx];
        if (!img->data[i]) {
            std::cerr << "Memory allocation failed for image row." << std::endl;
            // Free previously allocated memory
            for (int j = 0; j < i; ++j) {
                delete[] img->data[j];
            }
            delete[] img->data;
            delete img;
            return nullptr; // Return a reset image or handle the error as needed.
        }
        std::memset(img->data[i], 0, sx * sizeof(unsigned char)); // Zero out each row
    }

    return img;
}
