}

// Function to create a sorted vector set, populate it with random elements, check invariants, and then create a new sorted vector set by inserting the elements of the original set into a new set. Finally, check that the two sets are equal.
void testSortedVectorSet() {
    const int MIN = 1;
    const int MAX = 100;
    const int SIZE = getRandomNumber(MIN, MAX);

    std::vector<int> originalSet;
    for (int i = 0; i < SIZE; ++i) {
        originalSet.push_back(getRandomNumber(MIN, MAX));
    }

    // Sort the original set
    std::sort(originalSet.begin(), originalSet.end());

    // Create a new sorted vector set by inserting the elements of the original set into a new set
    std::set<int> sortedSet(originalSet.begin(), originalSet.end());

    // Check that the two sets are equal
    bool isEqual = (originalSet.size() == sortedSet.size());
    for (const auto& elem : originalSet) {
        if (sortedSet.find(elem) == sortedSet.end()) {
            isEqual = false;
            break;
        }
    }

    // Output the results
    std::cout << "Original Set: ";
    for (const auto& elem : originalSet) {
        std::cout << elem << " ";
    }
    std::cout << "\nSorted Set: ";
    for (const auto& elem : sortedSet) {
        std::cout << elem << " ";
    }
    std::cout << "\nSets are equal: " << (isEqual ? "Yes" : "No") << std::endl;
}

int main() {
    testSortedVectorSet();
    return 0;
}
