// Function to dynamically allocate memory for a copy of a given string
char* copy_string(const char* original) {
    if (original == NULL) return NULL;
    size_t length = strlen(original);
    char* copy = (char*)malloc((length + 1) * sizeof(char));
    if (copy == NULL) return NULL;
    strcpy(copy, original);
    return copy;
}

// Function to set environment variables using the copied string
void set_environment(const char* name, const char* value) {
    if (name != NULL && value != NULL) {
        setenv(name, value, 1); // Set env variable and overwrite if it exists
    }
}

// Function to insert the copied string into a collection of environment variables
void insert_into_collection(const char* name, const char* value) {
    if (name != NULL && value != NULL) {
        // Remove any existing environment variable with the same name
        unsetenv(name);
        // Set the new environment variable
        set_environment(name, value);
    }
}

int main() {
