    char* copy = copy_string(original);
    if (copy != NULL) {
        insert_into_collection("MY_ENV", copy);
        printf("Environment variable 'MY_ENV' set to '%s'\n", getenv("MY_ENV"));
        free(copy); // Free the allocated memory
    } else {
        printf("Failed to copy string.\n");
    }
    return 0;
}
