enum Tile {
    EMPTY, WALL, FLOOR, UNKNOWN
};

std::vector<std::vector<Tile>> loadMap(const std::string& mapString, char delimiter) {
    std::vector<std::vector<Tile>> map;
    std::istringstream stream(mapString);
    std::string row;

    while (std::getline(stream, row, '\n')) {
        std::vector<Tile> currentRow;
        std::istringstream rowStream(row);
        std::string tile;

        while (std::getline(rowStream, tile, delimiter)) {
            if (tile == "EMPTY") {
                currentRow.push_back(EMPTY);
            } else if (tile == "WALL") {
                currentRow.push_back(WALL);
            } else if (tile == "FLOOR") {
                currentRow.push_back(FLOOR);
            } else {
                currentRow.push_back(UNKNOWN);
            }
        }

        map.push_back(currentRow);
    }

    return map;
}
