template<typename Container>
std::vector<size_t> countUniqueElements(const std::vector<Container>& containers) {
    std::vector<size_t> uniqueCounts;
    for (const auto& container : containers) {
        std::set<typename Container::value_type> uniqueSet(container.begin(), container.end());
        uniqueCounts.push_back(uniqueSet.size());
    }
    return uniqueCounts;
}

int main() {
    std::vector<std::vector<int>> containers = {{1, 2, 3}, {4, 5, 6}, {1, 2}};
    auto result = countUniqueElements(containers);
    for (size_t count : result) {
        std::cout << count << " ";
    }
    return 0;
}
