void drawCurve(const std::vector<std::pair<double, double>>& controlPoints, float lineWidth = 1.0f, const GLfloat color[3] = {0.0f, 0.0f, 0.0f}, int numSegments = 100) {
    glLineWidth(lineWidth);
    glColor3fv(color);

    std::vector<std::pair<double, double>> points;
    for (int i = 0; i < controlPoints.size(); ++i) {
        points.push_back(controlPoints[i]);
    }
    if (!points.empty() && !(points.front() == points.back())) {
        points.push_back(points.front()); // Add the first point at the end to close the curve if necessary
    }

    glBegin(GL_LINE_STRIP);
    for (int i = 0; i <= numSegments; ++i) {
        double t = static_cast<double>(i) / numSegments;
        double x = 0, y = 0;
        for (size_t j = 0; j < points.size(); ++j) {
            double basis = binomialCoeff(points.size() - 1, j) * std::pow(1 - t, points.size() - 1 - j) * std::pow(t, j);
            x += points[j].first * basis;
            y += points[j].second * basis;
        }
        glVertex2d(x, y);
    }
    glEnd();
}

int binomialCoeff(int n, int k) {
    if (k > n - k) {
        k = n - k;
    }
    int res = 1;
    for (int i = 0; i < k; ++i) {
        res *= (n - i);
        res /= (i + 1);
    }
    return res;
}
