void readBinaryFile(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    uint16_t dimensions[2];
    fread(dimensions, sizeof(uint16_t), 2, file);
    int rows = dimensions[0];
    int cols = dimensions[1];

    size_t arraySize = rows * cols;
    float *array = (float *)malloc(arraySize * sizeof(float));
    if (!array) {
        perror("Failed to allocate memory");
        fclose(file);
        return;
    }

    fread(array, sizeof(float), arraySize, file);
    fclose(file);

    printf("Dimensions: %dx%d\n", rows, cols);
    for (int i = 0; i < rows; ++i) {
        for (int j = 0; j < cols; ++j) {
            printf("%f ", array[i * cols + j]);
        }
        printf("\n");
    }

    free(array);
}

int main() {
