char** discoverUPnPDevices(const char* multicastAddress, const char* miniupnpcPath) {
    int timeout = 2000; // milliseconds
    struct UPNPDev *devlist = upnpDiscover(timeout, multicastAddress, miniupnpcPath);
    
    if (devlist == NULL) {
        printf("UPnP discovery failed.\n");
        return NULL;
    }
    
    // Count the number of devices discovered
    int deviceCount = 0;
    struct UPNPDev *tempDev = devlist;
    while (tempDev != NULL) {
        tempDev = tempDev->pNext;
        deviceCount++;
    }
    
    // Allocate memory for the list of device URLs
    char** devices = (char**)malloc(deviceCount * sizeof(char*));
    if (devices == NULL) {
        printf("Memory allocation failed.\n");
        upnpFreeUPNPDevlist(devlist);
        return NULL;
    }
    
    // Populate the list with device URLs
    int index = 0;
    tempDev = devlist;
    while (tempDev != NULL) {
        devices[index++] = strdup(tempDev->descURL);
        tempDev = tempDev->pNext;
    }
    
    // Free the original device list
    upnpFreeUPNPDevlist(devlist);
    
    return devices;
}
