    vector<TreeNode*> nodes(n);
    for (int i = 0; i < n; ++i) {
        nodes[i] = new TreeNode(i + 1); // Assuming node values are 1-based
    }

    // Populate the tree using the adjacency list representation
    for (int i = 0; i < n; ++i) {
