import org.apache.pdfbox.rendering.PageRenderedEvent;
import org.apache.pdfbox.rendering.image.ImageType;
import org.apache.pdfbox.rendering.image.PDFImageWriter;

public class PDFToPPM {
    public static byte[] generatePPIImage(PDDocument document, int pageNumber, int displayWidth, int displayHeight) throws IOException {
        PDFRenderer renderer = new PDFRenderer(document);
        BufferedImage image = renderer.renderImageWithDPI(pageNumber, 300, ImageType.RGB);

        // Scale the image to fit the specified display size
        double scaleX = (double) displayWidth / image.getWidth();
        double scaleY = (double) displayHeight / image.getHeight();
        double scale = Math.min(scaleX, scaleY);

        int newWidth = (int) (image.getWidth() * scale);
        int newHeight = (int) (image.getHeight() * scale);

        BufferedImage scaledImage = new BufferedImage(newWidth, newHeight, BufferedImage.TYPE_INT_RGB);
        java.awt.Graphics2D graphics = scaledImage.createGraphics();
        graphics.drawImage(image, 0, 0, newWidth, newHeight, null);
        graphics.dispose();

        // Convert the scaled image to PPM format and write it to a byte array
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        ImageIO.write(scaledImage, "ppm", baos);
        return baos.toByteArray();
    }
}
