std::vector<double> measureAccessMethods(const std::vector<std::vector<int>>& image) {
    size_t height = image.size();
    size_t width = image[0].size();
    std::vector<double> times(3, 0.0);

    // Direct indexing
    auto start = std::chrono::high_resolution_clock::now();
    for (size_t y = 0; y < height; ++y) {
        for (size_t x = 0; x < width; ++x) {
            int pixel = image[y][x];
        }
    }
    auto end = std::chrono::high_resolution_clock::now();
    times[0] = std::chrono::duration<double>(end - start).count();

    // Boundary clamping
    start = std::chrono::high_resolution_clock::now();
    for (size_t y = 0; y < height; ++y) {
        for (size_t x = 0; x < width; ++x) {
            int pixel = image[std::min(y, height - 1)][std::min(x, width - 1)];
        }
    }
    end = std::chrono::high_resolution_clock::now();
    times[1] = std::chrono::duration<double>(end - start).count();

    // Scalar access
    start = std::chrono::high_resolution_clock::now();
    for (size_t y = 0; y < height; ++y) {
        const int* row = image[y].data();
        for (size_t x = 0; x < width; ++x) {
            int pixel = row[x];
        }
    }
    end = std::chrono::high_resolution_clock::now();
    times[2] = std::chrono::duration<double>(end - start).count();

    return times;
}

int main() {
    size_t width = 1024;
    size_t height = 768;
    auto image = generateRandomImage(width, height);
    auto times = measureAccessMethods(image);

    std::cout << "Direct indexing time: " << times[0] << " seconds" << std::endl;
    std::cout << "Boundary clamping time: " << times[1] << " seconds" << std::endl;
    std::cout << "Scalar access time: " << times[2] << " seconds" << std::endl;

    return 0;
}
