// Assuming a pixel format where each pixel is represented by an unsigned int
void verticalFlip(unsigned int** pixels, size_t width, size_t height) {
    if (!pixels || !*pixels || width == 0 || height == 0) return;

    // Allocate temporary memory for the flipped image
    unsigned int* temp = new unsigned int[width * height];

    // Copy data from input array to temporary array
    size_t index = 0;
    for (size_t y = 0; y < height; ++y) {
        for (size_t x = 0; x < width; ++x) {
            temp[index++] = pixels[y][x];
        }
    }

    // Copy data back to input array in the correct order
    index = 0;
    for (size_t y = height; y > 0; --y) {
        for (size_t x = 0; x < width; ++x) {
            pixels[y - 1][x] = temp[index++];
        }
    }

    // Free temporary memory
    delete[] temp;
}
