struct Message {
    int client_fd;
    std::string data;
};

class MessageQueue {
public:
    void push(const Message& msg) {
        std::unique_lock<std::mutex> lock(mtx);
        queue.push(msg);
        cond.notify_one();
    }

    Message pop() {
        std::unique_lock<std::mutex> lock(mtx);
        while (queue.empty()) {
            cond.wait(lock);
        }
        Message msg = queue.front();
        queue.pop();
        return msg;
    }

private:
    std::queue<Message> queue;
    std::mutex mtx;
    std::condition_variable cond;
};

void handle_client(int client_fd, MessageQueue& message_queue) {
    char buffer[1024];
    while (true) {
        ssize_t bytes = recv(client_fd, buffer, sizeof(buffer), 0);
        if (bytes <= 0) {
            close(client_fd);
            break;
        }
        Message msg{client_fd, std::string(buffer, bytes)};
        message_queue.push(msg);
    }
}

