    char *memory = (char *)malloc(memory_size);
    if (!memory) {
        perror("Failed to allocate memory");
        return 0;
    }

    // Set the memory to a known value
    memset(memory, 0xAA, memory_size);

    // Protect the page so that it cannot be read
    DWORD old_protect;
    if (!VirtualProtect((void *)memory, memory_size, PAGE_NOACCESS, &old_protect)) {
        perror("Failed to protect memory");
        free(memory);
        return 0;
    }

    // Attempt to compare the memory to a different value using memcmp
    char *compare_value = (char *)malloc(memory_size);
    if (!compare_value) {
        perror("Failed to allocate compare value");
        free(memory);
