char* calculate_discid(CDIO_CD_ROM *cdrom) {
    uint64_t sum = 0;
    int track_count = cdio_get_num_tracks(cdrom);
    
    for (int i = 0; i < track_count; i++) {
        CDIO_Track *track = cdio_get_track(cdrom, i);
        sum += track->lba;
    }
    
    uint32_t discid = (sum / 0xff) << 24;
    
    // Convert discid to string representation
    static char discid_str[9]; // 8 characters + null terminator for DISCID format
    snprintf(discid_str, sizeof(discid_str), "%08lx", (unsigned long)discid);
    
    printf("Computed DISCID: %s\n", discid_str);
    
    return discid_str;
}
