    if (pos == std::string::npos) return "";
    pos += 3;
    size_t endHost = url.find('/', pos);
    std::string host = url.substr(pos, endHost - pos);

    // Format the query string
    char query[256];
    snprintf(query, sizeof(query), "host=%s&depth=%d&non_cgi=1&has_filename=1&permalink=1&random_score=1", 
             host.c_str(), depth);

