#include <stdlib.h>
#include <string.h>

#define MAX_NODES 100

int find(int parent[], int i) {
    if (parent[i] == -1)
        return i;
    return find(parent, parent[i]);
}

void union_(int parent[], int x, int y) {
    int xset = find(parent, x);
    int yset = find(parent, y);
    if (xset != yset)
        parent[xset] = yset;
}

int isCycle(int V, int E, int* edges[][2]) {
    int *parent = (int*)malloc(V * sizeof(int));
    memset(parent, -1, sizeof(int) * V);

    for (int i = 0; i < E; ++i) {
        int x = find(parent, edges[i][0]);
        int y = find(parent, edges[i][1]);

        if (x == y)
            return 1;

        union_(parent, x, y);
    }
    free(parent);
    return 0;
}

int countComponents(int V, int E, int* edges[][2]) {
    int *parent = (int*)malloc(V * sizeof(int));
    memset(parent, -1, sizeof(int) * V);

    for (int i = 0; i < E; ++i) {
        int x = find(parent, edges[i][0]);
        int y = find(parent, edges[i][1]);
        if (x != y)
            union_(parent, x, y);
    }

    int count = 0;
    for (int i = 0; i < V; ++i) {
        if (parent[i] == -1)
            ++count;
    }
    free(parent);
    return count;
}

int main() {
    int V = 5, E = 5;
    int edges[5][2] = {{0, 1}, {1, 2}, {3, 4}, {2, 3}, {0, 4}};

    printf("Number of connected components: %d\n", countComponents(V, E, (int**)edges));

    return 0;
}
