void appendCIMValueToString(const CIMValue& cimValue, std::string& result) {
    if (cimValue.isNull()) {
        result += "null";
    } else if (cimValue.isArray()) {
        // Handle array case
        std::string value = cimValue.getValue();
        size_t start = 0;
        while (start < value.size()) {
            CIMValue element(value.substr(start));
            appendCIMValueToString(element, result);
            start += element.getValue().size() + 1; // Assuming elements are separated by a delimiter
        }
    } else {
        std::string value = cimValue.getValue();
        result += value;
    }
}
