    const std::string username = program.get<std::string>("--username");
    const std::string password = program.get<std::string>("--password");
    const std::string bucket = program.get<std::string>("--bucket");
    const std::string query = program.get<std::string>("--query");

    try {
        couchbase::cluster cluster(server, username, password);
        auto bucket_handle = cluster.bucket(bucket);
        auto collection_handle = bucket_handle.default_collection();

        // Execute the query
