int tokenize(const std::string &buffer, const std::string &delimiter, const std::string &specialValue, std::vector<std::string> &tokens) {
    tokens.clear();
    char *copy = strdup(buffer.c_str());
    if (!copy) return 0; // Return 0 on allocation failure

    char *token = strtok(copy, delimiter.c_str());
    while (token != NULL) {
        if (specialValue.find(token) == std::string::npos) {
            tokens.push_back(std::string(token));
        }
        token = strtok(NULL, delimiter.c_str());
    }

    free(copy);
    return tokens.size();
}
