// Function to create and execute a kernel with OpenCL
std::vector<float> run_opencl_kernel(const std::vector<float>& input, const size_t N) {
    // Platform and device selection
    std::vector<cl::Platform> platforms;
    cl::Platform::get(&platforms);
    auto platform = platforms.front();

    std::vector<cl::Device> devices;
    platform.getDevices(CL_DEVICE_TYPE_GPU, &devices);
    auto device = devices.front();

    // Context and command queue creation
    cl::Context context(device);
    cl::CommandQueue queue(context, device);

    // Kernel code (example: simple addition)
    const char* kernelSource = R"(
        __kernel void add(__global const float* input, 
                          __global float* output, 
                          __local float* temp, 
                          const unsigned int N) {
            size_t gid = get_global_id(0);
            if (gid < N) {
                output[gid] = input[gid] + temp[gid];
            }
        }
    )";

    // Program and kernel compilation/creation
    cl::Program program(context, kernelSource);
    try {
        program.build("-cl-std=CL1.2");
    } catch (const cl::Error& err) {
        std::cerr << "Build Error: " << err.what() << " code: " << err.err() << std::endl;
        std::cerr << program.getBuildInfo<CL_PROGRAM_BUILD_LOG>(device);
        throw;
    }
    cl::Kernel kernel(program, "add");

    // Memory allocation on device
    cl::Buffer inputBuffer(context, CL_MEM_READ_ONLY | CL_MEM_COPY_HOST_PTR, sizeof(float) * N, input.data());
    cl::Buffer outputBuffer(context, CL_MEM_WRITE_ONLY, sizeof(float) * N);
    cl::Buffer tempBuffer(context, CL_MEM_READ_WRITE, sizeof(float) * N);

    // Set kernel arguments
    kernel.setArg(0, inputBuffer);
    kernel.setArg(1, outputBuffer);
    kernel.setArg(2, tempBuffer);
    kernel.setArg(3, static_cast<unsigned int>(N));

    // Execute the kernel
    cl::NDRange global(N);
    queue.enqueueNDRangeKernel(kernel, cl::NullRange, global, cl::NullRange);
    queue.finish();

    // Copy data back to host memory
    std::vector<float> output(N);
    queue.enqueueReadBuffer(outputBuffer, CL_TRUE, 0, sizeof(float) * N, output.data());

    return output;
}
