struct HeightMap {
    int width;
    int height;
    std::vector<int> data;
};

HeightMap* readBitmapAsHeightMap(const char* filename) {
    std::ifstream file(filename, std::ios::binary);
    if (!file.is_open()) {
        std::cerr << "Error opening file: " << filename << std::endl;
        return nullptr;
    }

    // Read the BMP signature (2 bytes)
    char signature[2];
    file.read(signature, 2);
    if (signature[0] != 'B' || signature[1] != 'M') {
        std::cerr << "Not a valid bitmap file: " << filename << std::endl;
        file.close();
        return nullptr;
    }

    // Read the BMP file header (12 bytes)
    int fileSize, reserved, dataOffset;
    file.read(reinterpret_cast<char*>(&fileSize), 4);
    file.read(reinterpret_cast<char*>(&reserved), 4);
    file.read(reinterpret_cast<char*>(&dataOffset), 4);

    // Read the DIB header (bitmap info header, 12 bytes for BITMAPINFOHEADER)
    int dibHeaderSize;
    file.read(reinterpret_cast<char*>(&dibHeaderSize), 4);

    // Read the width and height of the image
    int width, height;
    file.read(reinterpret_cast<char*>(&width), 4);
    file.read(reinterpret_cast<char*>(&height), 4);

    // Create a HeightMap structure
    HeightMap* heightMap = new HeightMap{width, height, std::vector<int>(width * height)};

    // Skip the number of color planes (2 bytes) and bits per pixel (2 bytes)
    file.seekg(4, std::ios::cur);

    // Read the compression method (4 bytes)
    int compressionMethod;
    file.read(reinterpret_cast<char*>(&compressionMethod), 4);

    // Skip the image size (4 bytes), x pixels per meter (4 bytes), y pixels per meter (4 bytes),
    // number of colors in the palette (4 bytes), and important color count (4 bytes)
    file.seekg(20, std::ios::cur);

    // Read the bitmap data
    int rowSize = ((width * 3 + 3) / 4) * 4; // Each row in the BMP is padded to a multiple of 4 bytes
    char* buffer = new char[rowSize];
    for (int y = height - 1; y >= 0; --y) {
        file.read(buffer, rowSize);
        for (int x = 0; x < width; ++x) {
            // Assuming BGR format and ignoring the alpha channel for simplicity
            int b = static_cast<unsigned char>(buffer[x * 3]);
            int g = static_cast<unsigned char>(buffer[x * 3 + 1]);
            int r = static_cast<unsigned char>(buffer[x * 3 + 2]);
            heightMap->data[y * width + x] = (b + g + r) / 3; // Average of the three color channels as height value
        }
    }

    delete[] buffer;
    file.close();
    return heightMap;
}
