std::pair<int, bool> closestSubsetSum(const std::vector<int>& numbers, int target) {
    srand(time(0)); // Seed for random number generation
    const int maxIterations = 1000; // Maximum number of iterations to avoid infinite loops
    int bestSum = INT_MAX;
    bool reachedTarget = false;

    for (int iteration = 0; iteration < maxIterations; ++iteration) {
        std::vector<int> subset;
        int currentSum = 0;

        // Randomly select numbers to form a subset
        while (currentSum < target && !numbers.empty()) {
            int index = rand() % numbers.size();
            currentSum += numbers[index];
            subset.push_back(numbers[index]);
            numbers.erase(numbers.begin() + index);
        }

        // Check if the current sum is closer to the target than the best found so far
        if (std::abs(currentSum - target) < std::abs(bestSum - target)) {
            bestSum = currentSum;
            reachedTarget = (currentSum == target);
        }

        // Restore the numbers for the next iteration
        numbers.insert(numbers.end(), subset.begin(), subset.end());
    }

    return {bestSum, reachedTarget};
}
