typedef struct {
    void *data;
    int size;
} SoundData;

SoundData* load_sound_file(const char *directory, const char *filename) {
    char path[256];
    snprintf(path, sizeof(path), "%s/%s", directory, filename);

    FILE *file = fopen(path, "rb");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    int size = ftell(file);
    rewind(file);

    SoundData *sound_data = (SoundData *)malloc(sizeof(SoundData));
    if (!sound_data) {
        perror("Error allocating memory");
        fclose(file);
        return NULL;
    }

    sound_data->data = malloc(size);
    if (!sound_data->data) {
        perror("Error allocating memory for sound data");
        free(sound_data);
        fclose(file);
        return NULL;
    }

    size_t bytes_read = fread(sound_data->data, 1, size, file);
    if (bytes_read != size) {
        perror("Error reading sound data");
        free(sound_data->data);
        free(sound_data);
        fclose(file);
        return NULL;
    }

    sound_data->size = size;
    fclose(file);
    return sound_data;
}
