std::vector<std::wstring> listFilesInDirectory(const std::wstring& directoryPath, bool sorted = false) {
    std::vector<std::wstring> files;
    HANDLE hFind;
    WIN32_FIND_DATA data;

    // Find the first file in the directory
    hFind = FindFirstFile((directoryPath + L"\\*").c_str(), &data);
    if (hFind != INVALID_HANDLE_VALUE) {
        do {
            // Skip "." and ".." directories
            if (std::wstring(data.cFileName) == L"." || std::wstring(data.cFileName) == L"..") {
                continue;
            }
            files.push_back(data.cFileName);
        } while (FindNextFile(hFind, &data));
        FindClose(hFind);
    }

    // Optionally sort the list of files
    if (sorted) {
        std::sort(files.begin(), files.end());
    }

    return files;
}
