#include <string.h>
#include <openssl/hmac.h>
#include <openssl/evp.h>
#include <openssl/bio.h>
#include <openssl/buffer.h>

char* generate_signature(const char* message, const char* secret_key) {
    unsigned char digest[EVP_MAX_MD_SIZE];
    unsigned int digest_len;

    HMAC_CTX *ctx = HMAC_CTX_new();
    if (!ctx) {
        fprintf(stderr, "Unable to create HMAC context\n");
        return NULL;
    }

    HMAC_Init_ex(ctx, secret_key, strlen(secret_key), EVP_sha1(), NULL);
    HMAC_Update(ctx, (unsigned char*)message, strlen(message));
    HMAC_Final(ctx, digest, &digest_len);
    HMAC_CTX_free(ctx);

    BIO *bio = BIO_new(BIO_s_mem());
    if (!bio) {
        fprintf(stderr, "Unable to create memory buffer\n");
        return NULL;
    }

    BIO *b64 = BIO_new(BIO_f_base64());
    bio = BIO_push(b64, bio);

    BIO_write(bio, digest, digest_len);
    BIO_flush(bio);

    BUF_MEM *bufferPtr;
    BIO_get_mem_ptr(bio, &bufferPtr);

    char *base64_signature = (char *)malloc(bufferPtr->length + 1);
    if (!base64_signature) {
        fprintf(stderr, "Unable to allocate memory for base64 signature\n");
        BIO_free_all(bio);
        return NULL;
    }

    memcpy(base64_signature, bufferPtr->data, bufferPtr->length);
    base64_signature[bufferPtr->length] = '\0';

    BIO_free_all(bio);

    return base64_signature;
}
