#include <boost/python.hpp>
#include <openssl/evp.h>
#include <string>
#include <vector>

std::string kdf2_sha1(const std::string& password, const std::string& master_key, size_t output_length) {
    // Convert input strings to vectors of bytes
    std::vector<unsigned char> pw = std::vector<unsigned char>(password.begin(), password.end());
    std::vector<unsigned char> mk = std::vector<unsigned char>(master_key.begin(), master_key.end());

    // Create a context for the KDF2 algorithm with SHA-1 as the underlying hash function
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    if (!ctx) {
        throw std::runtime_error("Failed to create EVP context");
    }

    // Initialize the context for KDF2 with SHA-1
    if (EVP_DigestInit_ex(ctx, EVP_sha1(), nullptr) != 1) {
        EVP_MD_CTX_free(ctx);
        throw std::runtime_error("Failed to initialize digest context");
    }

    // Update the context with the master key
    if (EVP_DigestUpdate(ctx, mk.data(), mk.size()) != 1) {
        EVP_MD_CTX_free(ctx);
        throw std::runtime_error("Failed to update digest context with master key");
    }

    // Update the context with the password
    if (EVP_DigestUpdate(ctx, pw.data(), pw.size()) != 1) {
        EVP_MD_CTX_free(ctx);
        throw std::runtime_error("Failed to update digest context with password");
    }

    // Allocate memory for the output key
    std::vector<unsigned char> derived_key(output_length);

    // Finalize the hash and store the result in the derived_key vector
    unsigned int len;
    if (EVP_DigestFinal_ex(ctx, derived_key.data(), &len) != 1) {
        EVP_MD_CTX_free(ctx);
        throw std::runtime_error("Failed to finalize digest");
    }

    // Clean up the context
    EVP_MD_CTX_free(ctx);

    // Convert the derived key vector back to a string and return it
    return std::string(derived_key.begin(), derived_key.end());
}

BOOST_PYTHON_MODULE(kdf2) {
    using namespace boost::python;
    def("kdf2_sha1", kdf2_sha1);
}
