void* aligned_malloc(size_t size) {
    // Calculate expected alignment based on size and cache line size (assumed to be 64 bytes for simplicity)
    const size_t cache_line_size = 64;
    size_t align = ((size - 1) / cache_line_size + 1) * cache_line_size;

    void* ptr = malloc(size + align);
    if (!ptr) {
        return NULL; // Allocation failed
    }

    uintptr_t addr = (uintptr_t)ptr;
    if ((addr % align) == 0) {
        return ptr; // Memory is properly aligned
    } else {
        free(ptr);
        return NULL; // Memory is not properly aligned
    }
}
