    if (!f1 || !f2) {
        fclose(f1);
        fclose(f2);
        return false;
    }

    fseek(f1, 0, SEEK_END);
    long size1 = ftell(f1);
    rewind(f1);

    fseek(f2, 0, SEEK_END);
    long size2 = ftell(f2);
    rewind(f2);

    if (size1 != size2) {
        fclose(f1);
        fclose(f2);
        return false;
    }

    unsigned char *buffer1 = malloc(size1);
    unsigned char *buffer2 = malloc(size2);

    if (!buffer1 || !buffer2) {
        free(buffer1);
        free(buffer2);
        fclose(f1);
        fclose(f2);
        return false;
    }

    size_t bytesRead1 = fread(buffer1, 1, size1, f1);
    size_t bytesRead2 = fread(buffer2, 1, size2, f2);

    if (bytesRead1 != bytesRead2) {
        free(buffer1);
        free(buffer2);
        fclose(f1);
        fclose(f2);
        return false;
    }

    bool result = memcmp(buffer1, buffer2, size1) == 0;

    free(buffer1);
    free(buffer2);
    fclose(f1);
    fclose(f2);

    return result;
}
