#include <forward_list>
#include <string>

void insertAfter(std::forward_list<std::string>& list, const std::string& target, const std::string& toInsert) {
    auto current = list.begin();
    auto prev = list.before_begin();

    while (current != list.end()) {
        if (*current == target) {
            list.insert_after(current, toInsert);
            return;
        }
        prev = current++;
    }

    list.insert_after(prev, toInsert);
}
