// Function to read a file and return its contents as a Unicode string
wchar_t* read_file_as_unicode(const char* path) {
    // Set the locale to UTF-8 for wide character support
    if (!setlocale(LC_ALL, "en_US.UTF-8")) {
        perror("Failed to set locale");
        return NULL;
    }

    // Open the file in binary mode to read its contents as raw bytes
    FILE* file = fopen(path, "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    // Seek to the end of the file to get its size
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    if (file_size == -1) {
        perror("Failed to determine file size");
        fclose(file);
        return NULL;
    }

    // Seek back to the beginning of the file
    rewind(file);

    // Allocate memory for the wide character string (each wchar_t is 4 bytes)
    wchar_t* buffer = (wchar_t*)malloc((file_size / sizeof(char)) * sizeof(wchar_t));
    if (!buffer) {
        perror("Failed to allocate memory");
        fclose(file);
        return NULL;
    }

    // Read the file contents into the buffer
    size_t bytes_read = fread(buffer, sizeof(char), file_size, file);
    if (bytes_read != file_size) {
        perror("Failed to read file");
        free(buffer);
        fclose(file);
        return NULL;
    }

    // Null-terminate the wide character string
    buffer[file_size / sizeof(char)] = L'\0';

    // Close the file and return the buffer
    fclose(file);
    return buffer;
}
