int findBestCombination(const std::vector<Pair>& pairs, int targetValue) {
    std::srand(std::time(0)); // Seed for random number generation
    const int numIterations = 1000; // Number of iterations to run the algorithm

    int bestTotalValue = -1;

    for (int iteration = 0; iteration < numIterations; ++iteration) {
        std::vector<Pair> currentSelection(pairs.size(), {0, false});
        int currentTotalValue = 0;

        for (const auto& pair : pairs) {
            if (!pair.selected && ((std::rand() % 2) == 0)) { // Randomly select the pair with a 50% chance
                currentSelection[&pair - &pairs[0]].value = pair.value;
                currentTotalValue += pair.value;
                currentSelection[&pair - &pairs[0]].selected = true;
            }
        }

        if (currentTotalValue <= targetValue && currentTotalValue > bestTotalValue) {
            bestTotalValue = currentTotalValue;
        }
    }

    return bestTotalValue;
}
