    for (auto& row : image) {
        for (auto& pixel : row) {
            pixel = rand() % 256; // Random value between 0 and 255
        }
    }

    int filtHeight = 3;
    int filtWidth = 3;
    std::vector<std::vector<int>> filter(filtHeight, std::vector<int>(filtWidth));

    // Initialize filter with random values
