#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <string.h>

typedef struct {
    char **tokens;
    int count;
} TokenList;

void initTokenList(TokenList *list) {
    list->tokens = NULL;
    list->count = 0;
}

void addToken(TokenList *list, const char *token) {
    list->count++;
    list->tokens = (char **)realloc(list->tokens, list->count * sizeof(char *));
    list->tokens[list->count - 1] = strdup(token);
}

void freeTokenList(TokenList *list) {
    for (int i = 0; i < list->count; i++) {
        free(list->tokens[i]);
    }
    free(list->tokens);
}

char *trim(char *str) {
    char *end;

    // Trim leading space
    while (isspace((unsigned char)*str)) str++;

    if (*str == 0)  // All spaces?
        return strdup("");

    // Trim trailing space
    end = str + strlen(str) - 1;
    while (end > str && isspace((unsigned char)*end)) end--;

    // Write new null terminator
    *(end + 1) = 0;

    return strdup(str);
}

int is_valid_token(const char *token) {
    if (strlen(token) == 0) return 0;
    if (isdigit(token[0]) || token[0] == '-') return 1;
    if (token[0] == '"') return 2; // Quoted string
    return 0;
}

