void percolationStep(std::vector<int>* sites, double probability, int timeStep) {
    // Seed the random number generator with the current time
    std::srand(static_cast<unsigned int>(std::time(nullptr)));

    // Generate a random index within the range of the vector size
    int index = std::rand() % sites->size();

    // Apply the percolation rule based on the site's index and time step
    if (sites->at(index) == 0 && probability > 0.5) {
        sites->at(index) = timeStep;
    } else if (sites->at(index) != 0 && probability < 0.5) {
        sites->at(index) = -timeStep;
    }
}
