// Function to convert Haab date format 'dd. mm. yyyy' to days since a fixed point in time
int haab_to_days(const char *date_str) {
    int day, month, year;
    sscanf(date_str, "%d. %d. %d", &day, &month, &year);

    // Haab calendar has 18 months of 20 days each, plus 5 extra days (the "year" ends with a 5-day period)
    const int days_in_month = 20;
    const int num_months = 18;
    const int total_days_in_year = num_months * days_in_month + 5;

    // Calculate the number of days since a fixed point in time (e.g., year 0)
    int days_since_fixed_point = year * total_days_in_year + month * days_in_month + day - 1;

    return days_since_fixed_point;
}

