struct Data {
    char CURP[10];
    char celular[10];
    char partido[5];
};

int main() {
    int sock;
    struct sockaddr_in server;
    struct Data data = {"CURP12345", "1234567890", "PARTY"};
    char buffer[1024];
    
    // Create socket
    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Socket creation error");
        return EXIT_FAILURE;
    }
    
    server.sin_addr.s_addr = inet_addr("127.0.0.1"); // Server IP address
    server.sin_family = AF_INET;
    server.sin_port = htons(8080); // Server port number
    
    // Connect to the server
    if (connect(sock, (struct sockaddr *)&server, sizeof(server)) < 0) {
        perror("Connection failed");
        return EXIT_FAILURE;
    }
    
    // Send data struct as a packet
    if (send(sock, &data, sizeof(struct Data), 0) < 0) {
        perror("Send failed");
        close(sock);
        return EXIT_FAILURE;
    }
    
    // Receive response from the server
    int valread = recv(sock, buffer, sizeof(buffer), 0);
    if (valread < 0) {
        perror("Receive failed");
        close(sock);
        return EXIT_FAILURE;
    }
    
    // Print the response from the server
    buffer[valread] = '\0';
    printf("Server response: %s\n", buffer);
    
    // Close the socket and exit with status 0 if successful
    close(sock);
    return EXIT_SUCCESS;
}
