#include <cstdarg>
#include <cstdio>
#include <cstdlib>
#include <cstring>

char* my_vsnprintf(char* buf, size_t* length, const char* format, ...) {
    va_list args;
    va_start(args, format);
    int result = vsnprintf(buf, *length, format, args);
    va_end(args);

    if (result >= 0 && static_cast<size_t>(result) < *length) {
        return buf;
    } else {
        size_t new_length = result > 0 ? static_cast<size_t>(result) + 1 : 16;
        char* new_buf = reinterpret_cast<char*>(malloc(new_length));
        if (new_buf == nullptr) {
            return nullptr;
        }
        va_start(args, format);
        result = vsnprintf(new_buf, new_length, format, args);
        va_end(args);

        if (result >= 0 && static_cast<size_t>(result) < new_length) {
            *length = new_length;
            free(buf);
            return new_buf;
        } else {
            free(new_buf);
            return nullptr;
        }
    }
}
