std::string sha256_hmac(const std::string& message, const std::string& secret) {
    unsigned char digest[SHA256_DIGEST_LENGTH];
    HMAC(EVP_sha256(), secret.c_str(), secret.size(), reinterpret_cast<const unsigned char*>(message.c_str()), message.size(), digest, nullptr);

    std::stringstream ss;
    for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        ss << std::hex << std::setfill('0') << std::setw(2) << static_cast<int>(digest[i]);
    }
    return ss.str();
}
