            arr[i][j] = static_cast<float>(i * lLBytes + j);
        }
    }

    // Allocate memory for the differences array
    std::vector<std::vector<float>> diff(height, std::vector<float>(lLBytes));

    // Compute the differences between neighboring elements in all directions
    for (int i = 0; i < height; ++i) {
        for (int j = 0; j < lLBytes; ++j) {
            if (i > 0) diff[i][j] -= arr[i - 1][j]; // North
            if (i < height - 1) diff[i][j] += arr[i + 1][j]; // South
            if (j > 0) diff[i][j] -= arr[i][j - 1]; // West
            if (j < lLBytes - 1) diff[i][j] += arr[i][j + 1]; // East
            if (i > 0 && j > 0) diff[i][j] -= arr[i - 1][j - 1]; // North-West
            if (i > 0 && j < lLBytes - 1) diff[i][j] += arr[i - 1][j + 1]; // North-East
            if (i < height - 1 && j > 0) diff[i][j] -= arr[i + 1][j - 1]; // South-West
            if (i < height - 1 && j < lLBytes - 1) diff[i][j] += arr[i + 1][j + 1]; // South-East
        }
    }

    // Convert the differences array back to a flat float* array for return
    float* result = new float[size];
    int index = 0;
    for (int i = 0; i < height; ++i) {
        for (int j = 0; j < lLBytes; ++j) {
            result[index++] = diff[i][j];
        }
    }

    return result;
