struct DynamicString {
    char* data;
};

DynamicString* create_dynamic_string(const char* source) {
    size_t length = std::strlen(source);
    try {
        DynamicString* result = new (std::nothrow) DynamicString{new char[length + 1]};
        if (!result || !result->data) {
            delete[] result->data; // Clean up partially allocated memory
            delete result;
            return nullptr;
