// Function to convert Unicode string to ANSI string
char* unicodeToAnsi(const wchar_t* unicodeStr) {
    char* ansiStr = nullptr;
    if (unicodeStr == nullptr) {
        return nullptr;
    }

    int len = 0;
    while (unicodeStr[len] != L'\0') {
        len++;
    }

    ansiStr = static_cast<char*>(malloc(len * sizeof(wchar_t)));
    if (ansiStr == nullptr) {
        return nullptr; // Allocation failed
    }

    for (int i = 0; i < len; ++i) {
        ansiStr[i] = static_cast<char>(unicodeStr[i]);
    }

    return ansiStr;
}

