// Function to derive a key using PBKDF2 with SHA-1, empty password and salt
int derive_key_using_pbkdf2(const char *passphrase, const char *salt, uint8_t *derived_key, size_t derived_key_len) {
    // Initialize the OpenSSL context for PBKDF2
    EVP_PKEY_CTX *pctx = NULL;
    int ret = 0;

    if ((passphrase == NULL) || (salt == NULL) || (derived_key == NULL)) {
        return -1; // Invalid input parameters
    }

    pctx = EVP_PKEY_CTX_new_id(EVP_PKEY_PBKDF2, NULL);
    if (!pctx) {
        return -1; // Failed to create context
    }

    if (EVP_PKEY_derive_init(pctx) <= 0) {
        goto err;
    }

    if (EVP_PKEY_CTX_set_utf8_opt(pctx, 1) <= 0) { // Set passphrase as UTF-8 string
        goto err;
    }

    if (EVP_PKEY_CTX_set1_passwd(pctx, (unsigned char *)passphrase, strlen(passphrase)) <= 0) {
        goto err;
    }

    if (EVP_PKEY_CTX_set1_salt(pctx, (unsigned char *)salt, strlen(salt)) <= 0) {
        goto err;
    }

    if (EVP_PKEY_CTX_set_scrypt_hmac_sha256_dkenabled(pctx, 1) <= 0) { // Use HMAC-SHA256 for PBKDF2
        goto err;
    }

    if (EVP_PKEY_CTX_set_scrypt_hmac_sha256_dkbits(pctx, derived_key_len * 8) <= 0) { // Set the desired key length in bits
        goto err;
    }

    if (EVP_PKEY_CTX_set_scrypt_hmac_sha256_n(pctx, 16384) <= 0) { // Number of iterations (N parameter)
        goto err;
    }

    if (EVP_PKEY_CTX_set_scrypt_hmac_sha256_r(pctx, 8) <= 0) { // Block size (R parameter)
        goto err;
    }

    if (EVP_PKEY_derive(pctx, derived_key, &derived_key_len) <= 0) {
        goto err;
    }

    ret = 1; // Success

err:
    EVP_PKEY_CTX_free(pctx);
    return ret ? 0 : -1; // Return 0 for success, -1 for failure
}
