// Function to read a file specified by a given path and return its contents as a Unicode string
wchar_t *ReadFileAsUnicode(const wchar_t *filename) {
    FILE *finput;
    long filesize, num;
    wchar_t *buffer;

    if ((finput = _wfopen(filename, L"r")) == NULL) {
        fwprintf(stderr, L"%s: Cannot open file %s\n", filename);
        exit(1);
    }

    if (_fseeki64(finput, 0, SEEK_END) != 0 ||
        (filesize = _ftelli64(finput)) < 0 ||
        _fseeki64(finput, 0, SEEK_SET) != 0) {
        fwprintf(stderr, L"%s: File error in file %s\n", filename);
        exit(1);
    }

    if ((buffer = (wchar_t *)malloc((filesize + 1) * sizeof(wchar_t))) == NULL) {
        fwprintf(stderr, L"%s: Error allocating %ld bytes of memory\n", filename);
        exit(1);
    }

    num = fread(buffer, sizeof(wchar_t), filesize, finput);
    if (ferror(finput)) {
        fwprintf(stderr, L"%s: Error reading file %s\n", filename);
        exit(1);
    }

    buffer[num] = 0;
    fclose(finput);
    return buffer;
}
