#define MAX_NODES 100

int** createGraph(int nodes) {
    int** graph = (int**)malloc(nodes * sizeof(int*));
    for (int i = 0; i < nodes; i++) {
        graph[i] = (int*)calloc(nodes, sizeof(int));
    }
    return graph;
}

void addEdge(int** graph, int src, int dest) {
    graph[src][dest] = 1;
    graph[dest][src] = 1;
}

int* bfs(int** graph, int nodes, int start) {
    bool visited[MAX_NODES];
    for (int i = 0; i < nodes; i++) {
        visited[i] = false;
    }

    int* path = (int*)malloc(nodes * sizeof(int));
    for (int i = 0; i < nodes; i++) {
        path[i] = -1;
    }

    int queue[MAX_NODES];
    int front = 0, rear = 0;

    visited[start] = true;
    queue[rear++] = start;

    while (front < rear) {
        int current = queue[front++];
        for (int i = 0; i < nodes; i++) {
            if (graph[current][i] && !visited[i]) {
                visited[i] = true;
                path[i] = current;
                queue[rear++] = i;
            }
        }
    }

    return path;
}

int main() {
    int nodes, edges, src, dest, start;
    printf("Enter the number of nodes: ");
    scanf("%d", &nodes);
    printf("Enter the number of edges: ");
    scanf("%d", &edges);

    int** graph = createGraph(nodes);

    for (int i = 0; i < edges; i++) {
        printf("Enter edge %d (source destination): ", i + 1);
        scanf("%d %d", &src, &dest);
        addEdge(graph, src, dest);
    }

    printf("Enter the starting node: ");
    scanf("%d", &start);

    int* path = bfs(graph, nodes, start);

    for (int i = 0; i < nodes; i++) {
        if (i != start) {
            printf("Shortest path from %d to %d: ", start, i);
            int j = i;
            while (j != -1) {
                printf("%d ", j);
                j = path[j];
            }
            printf("\n");
        }
    }

    for (int i = 0; i < nodes; i++) {
        free(graph[i]);
    }
    free(graph);
    free(path);

    return 0;
}
