#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define ALPHABET_SIZE 256

typedef struct TrieNode {
    int count;
    struct TrieNode* children[ALPHABET_SIZE];
} TrieNode;

TrieNode* createNode() {
    TrieNode* node = (TrieNode*)malloc(sizeof(TrieNode));
    node->count = 0;
    for (int i = 0; i < ALPHABET_SIZE; i++) {
        node->children[i] = NULL;
    }
    return node;
}

void insert(TrieNode* root, const char* word) {
    TrieNode* current = root;
    for (const char* p = word; *p != '\0'; p++) {
        int index = (unsigned char)*p;
        if (!current->children[index]) {
            current->children[index] = createNode();
        }
        current = current->children[index];
    }
    current->count++;
}

void countOccurrences(TrieNode* root, int* result) {
    if (root == NULL) return;
    for (int i = 0; i < ALPHABET_SIZE; i++) {
        if (root->children[i] != NULL) {
            countOccurrences(root->children[i], result);
            result[i] += root->children[i]->count;
        }
    }
}

int* getCharacterCounts(const char* str) {
    TrieNode* root = createNode();
    for (const char* p = str; *p != '\0'; p++) {
        insert(root, p);
    }
    int* result = (int*)calloc(ALPHABET_SIZE, sizeof(int));
    countOccurrences(root, result);
    free(root);
    return result;
}

int main() {
    const char* str = "hello world";
    int* counts = getCharacterCounts(str);
    for (int i = 0; i < ALPHABET_SIZE; i++) {
        if (counts[i] > 0) {
            printf("'%c': %d\n", i, counts[i]);
        }
    }
    free(counts);
    return 0;
}
