int* unique_list_items(int* arr, int size, int* newSize) {
    // Allocate memory for a temporary array to hold unique values
    int* temp = (int*)malloc(size * sizeof(int));
    if (!temp) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }

    // Copy the input array to the temporary array
    for (int i = 0; i < size; i++) {
        temp[i] = arr[i];
    }

    // Sort the temporary array
    qsort(temp, size, sizeof(int), compare);

    // Remove duplicates by copying unique values to a new array
    int* uniqueArr = (int*)malloc((size + 1) * sizeof(int));
    if (!uniqueArr) {
        fprintf(stderr, "Memory allocation failed\n");
        free(temp);
        exit(1);
    }

    int j = 0;
    uniqueArr[j++] = temp[0];
    for (int i = 1; i < size; i++) {
        if (temp[i] != temp[i - 1]) {
            uniqueArr[j++] = temp[i];
        }
    }

    // Free the temporary array memory
    free(temp);

    // Set the newSize to the number of unique entries
    *newSize = j;

    return uniqueArr;
}

