typedef enum {
    PARSE_SUCCESS,
    PARSE_INVALID_FORMAT,
    PARSE_ERROR
} ParseResult;

ParseResult parse_endpoint_id(const char *str, char **parsed_host, int *parsed_port) {
    const char *colon = strchr(str, ':');
    
    if (colon == NULL || colon == str || *(colon + 1) == '\0') {
        return PARSE_INVALID_FORMAT;
    }
    
    char *endptr;
    int port = strtol(colon + 1, &endptr, 10);
    
    if (*endptr != '\0' || endptr == colon + 1) {
        return PARSE_INVALID_FORMAT;
    }
    
    *parsed_port = port;
    size_t host_len = colon - str;
    *parsed_host = (char *)malloc(host_len + 1);
    
    if (*parsed_host == NULL) {
        return PARSE_ERROR;
    }
    
    strncpy(*parsed_host, str, host_len);
    (*parsed_host)[host_len] = '\0';
    
    return PARSE_SUCCESS;
}
