#include <vector>
#include <thread>
#include <functional>

struct Color {
    int r, g, b;
};

class Camera {
public:
    virtual Color GetPixelColor(int x, int y) = 0;
};

class ThreadPool {
public:
    void EnqueueJob(std::function<void()> job) {
        jobs.push_back(job);
        if (jobs.size() == 1) {
            DispatchNextJob();
        }
    }

private:
    std::vector<std::function<void()>> jobs;

    void DispatchNextJob() {
        std::thread([this]() {
            while (!jobs.empty()) {
                auto job = jobs.front();
                jobs.erase(jobs.begin());
                job();
            }
        }).detach();
    }
};

class Renderer {
public:
    Renderer(Camera& camera, int width, int height) : camera(camera), image(height, std::vector<Color>(width)) {}

    void Render() {
        threadPool.EnqueueJob([this]() {
            for (int y = 0; y < image.size(); ++y) {
                for (int x = 0; x < image[0].size(); ++x) {
                    image[y][x] = camera.GetPixelColor(x, y);
                }
            }
        });
    }

    const std::vector<std::vector<Color>>& GetImage() const {
        return image;
    }

private:
    Camera& camera;
    ThreadPool threadPool;
    std::vector<std::vector<Color>> image;
};
