char* aggregate_integers(const char* key, int* integers, size_t count) {
    static const size_t buffer_size = 128; // Fixed-size buffer
    char buf[buffer_size];
    char temp[buffer_size];
    snprintf(temp, sizeof(temp), "AGGREGATED-OUTPUT[%s]:", key);

    if (count == 0) {
        return strdup(""); // Return an empty string if no integers are provided
    }

    size_t offset = strlen(temp);
    for (size_t i = 0; i < count; ++i) {
        int len = snprintf(buf + offset, buffer_size - offset, " %d", integers[i]);
        if (len >= buffer_size - offset) {
            return strdup("Error: List too large to fit in buffer"); // Handle case where list is too large
        }
        offset += len;
    }

    snprintf(buf, sizeof(buf), "%s%s", temp, buf + strlen(temp));
    char* result = (char*)malloc(buffer_size);
    strncpy(result, buf, buffer_size - 1);
    result[buffer_size - 1] = '\0';
    return result;
}
