#include <iostream>
#include <vector>
#include <random>
#include <cstdlib>
#include <ctime>

using namespace std;

enum class InputType {
    Dense,
    Sparse,
    Sequence
};

struct MatrixOptions {
    int rows;
    int cols;
    InputType type;
    double sparsity = 0.5; // Only applicable for sparse input type
};

vector<vector<double>> createRandomMatrix(const MatrixOptions& options) {
    vector<vector<double>> matrix(options.rows, vector<double>(options.cols));
    random_device rd;
    mt19937 gen(rd());

    switch (options.type) {
        case InputType::Dense:
            for (int i = 0; i < options.rows; ++i) {
                for (int j = 0; j < options.cols; ++j) {
                    matrix[i][j] = gen() % 100; // Random values between 0 and 99
                }
            }
            break;
        case InputType::Sparse:
            for (int i = 0; i < options.rows; ++i) {
                for (int j = 0; j < options.cols; ++j) {
                    if (gen() % 100 < options.sparsity * 100) {
                        matrix[i][j] = gen() % 100; // Random values between 0 and 99
                    } else {
                        matrix[i][j] = 0; // Sparse representation
                    }
                }
            }
            break;
        case InputType::Sequence:
            for (int i = 0; i < options.rows; ++i) {
                for (int j = 0; j < options.cols; ++j) {
                    matrix[i][j] = i * options.cols + j; // Sequential values
                }
            }
            break;
    }

    return matrix;
}

int main() {
    srand(time(0)); // Seed for random number generation

    MatrixOptions dense_options = {3, 4, InputType::Dense};
    vector<vector<double>> dense_matrix = createRandomMatrix(dense_options);

    cout << "Dense Matrix:" << endl;
    for (const auto& row : dense_matrix) {
        for (const auto& val : row) {
            cout << val << " ";
        }
        cout << endl;
    }

    MatrixOptions sparse_options = {3, 4, InputType::Sparse, 0.7};
    vector<vector<double>> sparse_matrix = createRandomMatrix(sparse_options);

    cout << "Sparse Matrix:" << endl;
    for (const auto& row : sparse_matrix) {
        for (const auto& val : row) {
            cout << val << " ";
        }
        cout << endl;
    }

    MatrixOptions sequence_options = {3, 4, InputType::Sequence};
    vector<vector<double>> sequence_matrix = createRandomMatrix(sequence_options);

    cout << "Sequence Matrix:" << endl;
    for (const auto& row : sequence_matrix) {
        for (const auto& val : row) {
            cout << val << " ";
        }
        cout << endl;
    }

    return 0;
}
