#include <librealsense2/rs.hpp>
#include <ros/ros.h>
#include <sensor_msgs/Image.h>
#include <sensor_msgs/PointCloud2.h>
#include <cv_bridge/cv_bridge.h>
#include <opencv2/opencv.hpp>

class RealSenseNode {
public:
    RealSenseNode(ros::NodeHandle& nh) : nh_(nh) {
        // Setup and initialize the RealSense camera
        rs2::context ctx;
        auto devices = ctx.query_devices();
        if (devices.size() == 0) {
            ROS_ERROR("No RealSense device connected.");
            return;
        }
        dev_ = devices[0];

        // Configure and start the pipeline
        cfg_.enable_stream(RS2_STREAM_DEPTH, 640, 480, RS2_FORMAT_Z16, 30);
        cfg_.enable_stream(RS2_STREAM_COLOR, 640, 480, RS2_FORMAT_BGR8, 30);
        pipe_.start(cfg_);

        // Allocate memory for frame buffers
        depth_frame_buffer_.create(480, 640, CV_16UC1);
        color_frame_buffer_.create(480, 640, CV_8UC3);

        // Advertise PointCloud2 and image topics for depth and RGB data
        pointcloud2_pub_ = nh_.advertise<sensor_msgs::PointCloud2>("pointcloud2", 10);
        depth_image_pub_ = nh_.advertise<sensor_msgs::Image>("depth_image", 10);
        color_image_pub_ = nh_.advertise<sensor_msgs::Image>("color_image", 10);
    }

    void publishFrames() {
        rs2::frameset frames = pipe_.wait_for_frames();
        rs2::frame depth_frame = frames.get_depth_frame();
        rs2::frame color_frame = frames.get_color_frame();

        // Convert RealSense frames to OpenCV format
        cv_bridge::CvImage cv_depth_image(std_msgs::Header(), "16UC1", depth_frame);
        cv_depth_image.toImageMsg(depth_frame_buffer_);

        cv_bridge::CvImage cv_color_image(std_msgs::Header(), "BGR8", color_frame);
        cv_color_image.toImageMsg(color_frame_buffer_);

        // Publish the frames
        depth_image_pub_.publish(depth_frame_buffer_);
        color_image_pub_.publish(color_frame_buffer_);
    }

private:
    ros::NodeHandle nh_;
    rs2::device dev_;
    rs2::pipeline pipe_;
    rs2::config cfg_;
    cv::Mat depth_frame_buffer_, color_frame_buffer_;
    ros::Publisher pointcloud2_pub_, depth_image_pub_, color_image_pub_;
};

int main(int argc, char** argv) {
    ros::init(argc, argv, "realsense_node");
    ros::NodeHandle nh;
    RealSenseNode realsense_node(nh);

    ros::Rate loop_rate(30); // 30 Hz
    while (ros::ok()) {
        realsense_node.publishFrames();
        ros::spinOnce();
        loop_rate.sleep();
    }

    return 0;
}
