void additiveBlitWithAntiAliasing(int width, int height, int x, int y, const std::vector<float>& alphaValues) {
    // Assuming frameBuffer is a 2D vector representing the image
    std::vector<std::vector<unsigned char>> frameBuffer(height, std::vector<unsigned char>(width * 4, 0));

    // Check if the input dimensions are valid
    if (x < 0 || y < 0 || x + width > frameBuffer[0].size() / 4 || y + height > frameBuffer.size()) {
        std::cerr << "Blit position out of bounds!" << std::endl;
        return;
    }

    // Apply additive blitting with anti-aliasing
    for (int i = 0; i < height; ++i) {
        for (int j = 0; j < width; ++j) {
            float alpha = alphaValues[i * width + j];
            if (alpha > 1.0f) alpha = 1.0f; // Clamp alpha to [0, 1]

            // Calculate the new color values with anti-aliasing
            unsigned char r = frameBuffer[y + i][(x + j) * 4];
            unsigned char g = frameBuffer[y + i][(x + j) * 4 + 1];
            unsigned char b = frameBuffer[y + i][(x + j) * 4 + 2];
            unsigned char a = frameBuffer[y + i][(x + j) * 4 + 3];

            r += static_cast<unsigned char>(alpha * 255);
            g += static_cast<unsigned char>(alpha * 255);
            b += static_cast<unsigned char>(alpha * 255);
            a = static_cast<unsigned char>(a + alpha * 255) > 255 ? 255 : static_cast<unsigned char>(a + alpha * 255);

            frameBuffer[y + i][(x + j) * 4] = r;
            frameBuffer[y + i][(x + j) * 4 + 1] = g;
            frameBuffer[y + i][(x + j) * 4 + 2] = b;
            frameBuffer[y + i][(x + j) * 4 + 3] = a;
        }
    }
}
