#include <vector>
#include <unordered_set>

class DisjointSetUnion {
public:
    void makeSet(int x) {
        parent[x] = x;
        rank[x] = 0;
    }

    int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]); // Path compression
        }
        return parent[x];
    }

    void unionSets(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

private:
    std::unordered_map<int, int> parent;
    std::unordered_map<int, int> rank;
};

bool arePairwiseConnected(const std::vector<int>& firstVector, const std::vector<int>& secondVector) {
    DisjointSetUnion dsu;
    for (int num : firstVector) {
        dsu.makeSet(num);
    }

    for (int i = 1; i < firstVector.size(); ++i) {
        dsu.unionSets(firstVector[0], firstVector[i]);
    }

    for (int num : secondVector) {
        if (dsu.find(num) != dsu.find(firstVector[0])) {
            return false;
        }
    }

    return true;
}
