struct MemoryBlock {
    uint64_t start;
    uint64_t size;
};

bool canAllocateMemory(const std::vector<MemoryBlock>& existingBlocks, uint64_t address, uint64_t size) {
    for (const auto& block : existingBlocks) {
        if (address >= block.start && address < block.start + block.size) {
            return false; // Overlaps with an existing block
        }
        if (address + size > block.start && address + size <= block.start + block.size) {
            return false; // Overlaps with an existing block
        }
        if (address < block.start && address + size > block.start + block.size) {
            return false; // Existing block is completely covered by the new allocation
        }
    }
    return true; // No overlaps found
}
