#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <string.h>

typedef void (*CallbackFunction)(const char*);

void formatMessageWithCallback(size_t bufferSize, CallbackFunction callback, const char *format, ...) {
    va_list ap;
    va_start(ap, format);

    // Allocate a buffer to hold the formatted message
    char* buffer = (char*)malloc(bufferSize);
    if (!buffer) {
        va_end(ap);
        return;
    }

    // Format the message using vsnprintf
    int result = vsnprintf(buffer, bufferSize, format, ap);
    va_end(ap);

    if (result >= 0 && (size_t)result < bufferSize) {
        // The formatted message fits in the buffer
        callback(buffer);
    } else {
        // The formatted message is too large, handle dynamically allocated memory
        char* dynamicBuffer = (char*)malloc(result + 1);
        if (!dynamicBuffer) {
            free(buffer);
            return;
        }

        va_start(ap, format);
        int actualResult = vsnprintf(dynamicBuffer, result + 1, format, ap);
        va_end(ap);

        if (actualResult >= 0 && (size_t)actualResult <= result) {
            callback(dynamicBuffer);
        } else {
            free(dynamicBuffer);
        }
    }

    free(buffer);
}
