void encrypt(const char *input, const char *key, char *output) {
    int len = strlen(input);
    for (int i = 0; i < len; i++) {
        char ch = input[i];
        if ('a' <= ch && ch <= 'z') {
            output[i] = key[(ch - 'a') % KEY_LENGTH];
