class Program
{
    static void Main()
    {
        Random random = new Random();
        int minElements = 1; // Minimum number of elements to generate
        int maxElements = 10; // Maximum number of elements to generate
        int numberOfElements = random.Next(minElements, maxElements + 1);

        List<int> originalList = GenerateRandomList(numberOfElements, random);
        List<int> shuffledList = new List<int>(originalList);
        Shuffle(shuffledList, random);

