        Console.WriteLine("Original List: " + string.Join(", ", originalList));
        Console.WriteLine("Shuffled List: " + string.Join(", ", shuffledList));
        Console.WriteLine("Sorted List: " + string.Join(", ", sortedList));

        // Test whether the sorted list is equal to the original list
        bool areEqual = AreListsEqual(originalList, sortedList);
        Console.WriteLine("Are the lists equal? " + areEqual);
    }

    static List<int> GenerateRandomList(int count, Random random)
    {
        List<int> list = new List<int>();
        for (int i = 0; i < count; i++)
        {
            list.Add(random.Next(1, 100)); // Generate random numbers between 1 and 100
        }
        return list;
    }

    static void Shuffle<T>(List<T> list, Random random)
    {
        int n = list.Count;
        while (n > 1)
        {
            n--;
            int k = random.Next(n + 1);
            T value = list[k];
            list[k] = list[n];
            list[n] = value;
        }
    }

    static List<int> CustomSort(List<int> list)
    {
        bool swapped;
        do
        {
            swapped = false;
            for (int i = 0; i < list.Count - 1; i++)
            {
                if (list[i] > list[i + 1])
                {
                    int temp = list[i];
                    list[i] = list[i + 1];
                    list[i + 1] = temp;
                    swapped = true;
                }
            }
        } while (swapped);
        return list;
    }

    static bool AreListsEqual(List<int> list1, List<int> list2)
    {
        if (list1.Count != list2.Count)
            return false;

        for (int i = 0; i < list1.Count; i++)
        {
            if (!list1[i].Equals(list2[i]))
                return false;
        }
        return true;
    }
}
