using System;

public class DisplacementFieldGenerator
{
    public double[,] GenerateDisplacementField(int width, int height, double stepSize)
    {
        double[,] displacementField = new double[width, height];
        Random random = new Random();

        for (int x = 0; x < width; x++)
        {
            for (int y = 0; y < height; y++)
            {
                // Generate Gaussian-distributed random displacement
                double mean = 0.0;
                double stdDev = stepSize / 3.0; // Standard deviation based on step size
                double displacement = mean + stdDev * Math.Sqrt(-2.0 * Math.Log(random.NextDouble())) * Math.Sin(2.0 * Math.PI * random.NextDouble());

                displacementField[x, y] = displacement;
            }
        }

        return displacementField;
    }
