public static class MatrixGenerator
{
    public static Array CreateMatrix<T>(int rows, int cols) where T : struct
    {
        // Get the type of the elements in the matrix
        Type elementType = typeof(T);
        
        // Create a multidimensional array with the specified dimensions
        Array result = Array.CreateInstance(elementType, new int[] { rows, cols });
        
        // Populate the matrix with random values within a given range (example: 0 to 100)
