        for (int i = 0; i < rows; i++)
        {
            for (int j = 0; j < cols; j++)
            {
                // Convert the random value to the appropriate type T
                object value = Convert.ChangeType(rand.Next(100), elementType);
                result.SetValue(value, i, j);
            }
        }
        
        return result;
    }
}
