using System;
using System.Collections.Generic;
using System.Linq;

public static class RandomElementGenerator
{
    public static IEnumerable<T> GetRandomElements<T>(this IList<T> list, int count)
    {
        if (list == null || list.Count == 0 || count <= 0)
            yield break;

        Random random = new Random();
        List<int> indices = Enumerable.Range(0, list.Count).ToList();
        while (count > 0 && indices.Count > 0)
        {
            int index = random.Next(indices.Count);
            yield return list[indices[index]];
            indices.RemoveAt(index);
            count--;
        }
    }
}
