using System;
using System.Security.Cryptography;
using System.Text;

public class TripleDESDecryption
{
    public static string Decrypt(string encryptedMessage, byte[] key, byte[] iv)
    {
        // Convert the Base64 encoded message to a byte array
        byte[] encryptedBytes = Convert.FromBase64String(encryptedMessage);

        // Create a TripleDES object with the specified key and IV
        using (TripleDESCryptoServiceProvider tripleDes = new TripleDESCryptoServiceProvider())
        {
            tripleDes.Key = key;
            tripleDes.IV = iv;

            // Create a decryptor from the TripleDES object
            ICryptoTransform decryptor = tripleDes.CreateDecryptor(tripleDes.Key, tripleDes.IV);

            // Decrypt the byte array
            using (var ms = new System.IO.MemoryStream())
            {
                using (var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Write))
                {
                    cs.Write(encryptedBytes, 0, encryptedBytes.Length);
                    cs.FlushFinalBlock();
                }

                // Convert the decrypted byte array to a string and return it
                return Encoding.UTF8.GetString(ms.ToArray());
            }
        }
    }
}
