using System;
using System.Diagnostics;
using System.IO;
using System.Threading.Tasks;

public class ExternalCommandExecutor
{
    public async Task ExecuteAsync(string commandFormat, string keyFilePath)
    {
        // Construct the command using the format string and key file path
        string commandLine = String.Format(commandFormat, keyFilePath);

        // Initialize a new process start info with the command line
        ProcessStartInfo startInfo = new ProcessStartInfo
        {
            FileName = "cmd.exe", // Assuming Windows for simplicity; adjust if needed
            Arguments = $"/c {commandLine}",
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            CreateNoWindow = true
        };

        // Start the process
        using (Process proc = new Process { StartInfo = startInfo })
        {
            proc.Start();

            // Read output and error streams asynchronously
            Task<string> outputTask = proc.StandardOutput.ReadToEndAsync();
            Task<string> errorTask = proc.StandardError.ReadToEndAsync();

            // Wait for both tasks to complete or timeout
            if (await Task.WhenAny(outputTask, errorTask) == outputTask)
            {
                string output = await outputTask;
                Console.WriteLine("Output: " + output);
            }
            else
            {
                string errors = await errorTask;
                Console.WriteLine("Error: " + errors);
            }

            // Wait for the process to exit with a timeout
            bool exited = proc.WaitForExit(60000); // 60 seconds timeout
            if (!exited)
            {
                Console.WriteLine("Process did not exit within the timeout period.");
                proc.Kill();
            }
        }
    }
}
