using System;
using System.Diagnostics;
using System.IO;
using System.Threading;

public class ProcessManager
{
    public void StartProcess(ProcessStartInfo startInfo, string trackingFolder, int timeout)
    {
        if (!Directory.Exists(trackingFolder))
        {
            throw new InvalidOperationException("Tracking folder does not exist.");
        }

        // Write the process ID to a tracking file
        string trackingFile = Path.Combine(trackingFolder, "process_id.txt");
        File.WriteAllText(trackingFile, Process.GetCurrentProcess().Id.ToString());

        // Start the sentinel process to monitor the original process
        var sentinelProcessStartInfo = new ProcessStartInfo("sentinel.exe")
        {
            Arguments = $"{startInfo.FileName} {startInfo.Arguments} {trackingFile}"
        };

        using (var sentinelProcess = new Process { StartInfo = sentinelProcessStartInfo })
        {
            sentinelProcess.Start();
            sentinelProcess.WaitForExit(timeout);

            if (!sentinelProcess.HasExited)
            {
                // If the original process does not complete within the timeout, clean up the tracking file and exit
                File.Delete(trackingFile);
                sentinelProcess.Kill();
            }
        }
    }
}
