using System.Text;

public class DESDecryptor
{
    public static string DecryptMessage(string encryptedMessage, string key)
    {
        // Convert the key and message to byte arrays
        byte[] keyBytes = Encoding.UTF8.GetBytes(key);
        byte[] encryptedBytes = Convert.FromBase64String(encryptedMessage);

        // Create a DES object with the provided key
        using (DES des = DES.Create())
        {
            // Set the key and mode for the DES algorithm
            des.Key = keyBytes;
            des.Mode = CipherMode.ECB;
            des.Padding = PaddingMode.PKCS7;

            // Create a decryptor from the DES object
            ICryptoTransform decryptor = des.CreateDecryptor();

            // Perform the decryption
            byte[] decryptedBytes = decryptor.TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);

            // Convert the decrypted bytes back to a string and return it
            return Encoding.UTF8.GetString(decryptedBytes);
        }
    }
}
