using System.Runtime.InteropServices;

public struct LabPixel
{
    public double L;
    public double A;
    public double B;
}

public class Matrix<T> where T : struct
{
    private IntPtr _dataPtr;
    private int _rows;
    private int _columns;

    public Matrix(int rows, int columns)
    {
        _rows = rows;
        _columns = columns;
        int sizeOfT = Marshal.SizeOf<T>();
        _dataPtr = Marshal.AllocHGlobal(sizeOfT * rows * columns);
    }

    ~Matrix()
    {
        Marshal.FreeHGlobal(_dataPtr);
    }

    public T this[int row, int column]
    {
        get
        {
            if (row < 0 || row >= _rows || column < 0 || column >= _columns)
                throw new IndexOutOfRangeException();
            IntPtr cellPtr = Marshal.ReadIntPtr(_dataPtr, ((row * _columns + column) * Marshal.SizeOf<T>()));
            return Marshal.PtrToStructure<T>(cellPtr);
        }
        set
        {
            if (row < 0 || row >= _rows || column < 0 || column >= _columns)
                throw new IndexOutOfRangeException();
            IntPtr cellPtr = Marshal.ReadIntPtr(_dataPtr, ((row * _columns + column) * Marshal.SizeOf<T>()));
            Marshal.StructureToPtr(value, cellPtr, false);
        }
    }
}

