using Microsoft.AspNetCore.Mvc;
using System.Collections.Concurrent;
using System.Threading.Tasks;

public class CacheService
{
    private ConcurrentDictionary<string, object> cache = new ConcurrentDictionary<string, object>();

    public async Task<IActionResult> ProcessRequestAsync(HttpRequest request)
    {
        string uri = request.Path;
        string method = request.Method;
        string body = await request.ReadAsStringAsync();
        var headers = request.Headers;

        // Perform the HTTP request and update cache based on the response
        (HttpResponseMessage response, string content) = await PerformHttpRequestAsync(uri, method, body, headers);

        // Update cache based on the response status code and data
        UpdateCache(uri, method, response.StatusCode.ToString(), content);

        // Return an ActionResult based on the response
        return new OkObjectResult(content);
    }

    private async Task<(HttpResponseMessage, string)> PerformHttpRequestAsync(string uri, string method, string body, IHeaderDictionary headers)
    {
        using (var client = new HttpClient())
        {
            var requestMessage = new HttpRequestMessage(new HttpMethod(method), uri);
            foreach (var header in headers)
            {
                requestMessage.Headers.TryAddWithoutValidation(header.Key, header.Value);
            }
            if (!string.IsNullOrEmpty(body))
            {
                requestMessage.Content = new StringContent(body);
            }

            HttpResponseMessage response = await client.SendAsync(requestMessage);
            string content = await response.Content.ReadAsStringAsync();
            return (response, content);
        }
    }

    private void UpdateCache(string uri, string method, string statusCode, string content)
    {
        // Implement cache update logic based on the request method and data
        string cacheKey = $"{uri}-{method}-{statusCode}";
        cache.AddOrUpdate(cacheKey, content, (key, oldValue) => content);
    }
}
