    public void AddSearcher(string xmlFilePath, string searcherName)
    {
        // Load the XML configuration file
        XDocument xdoc = XDocument.Load(xmlFilePath);

        // Define the namespace (if any)
        XNamespace ns = "your-namespace"; // Replace with actual namespace if needed

        // Select the list of searchers
        var searcherList = xdoc.Root?.Element(ns + "Searchers")?.Elements(ns + "Searcher").ToList();

        // Create a new searcher element
        XElement newSearcher = new XElement(ns + "Searcher",
            new XAttribute("Name", searcherName));

        // Add the new searcher to the list of searchers
        if (searcherList == null || !searcherList.Any())
        {
            // If the list is empty, create a new one
            xdoc.Root?.Element(ns + "Searchers")?.Add(newXElement);
        }
        else
        {
            // Otherwise, append to the existing list
            searcherList.Last().AddAfterSelf(newSearcher);
        }

        // Save the updated XML file
        xdoc.Save(xmlFilePath);
    }
}
