public class ProjectHelper
{
    public static string GetStartupFilePath(Project project)
    {
        // Check if the project has a startup file specified
        var startupFile = project.GetPropertyValue("StartupObject");
        if (!string.IsNullOrEmpty(startupFile))
        {
            return Path.Combine(Path.GetDirectoryName(project.FullPath), $"{startupFile}.cs");
        }

        // Generate a random available port number between 1200 and 60000, inclusive
        Random rand = new Random();
        int generatedPort;
        do
        {
            generatedPort = rand.Next(1200, 60001);
        } while (IsPortInUse(generatedPort));

        // Find the first available port that is not already in use and return its path
        for (int port = 1200; port <= 60000; port++)
        {
            if (!IsPortInUse(port))
            {
                generatedPort = port;
                break;
            }
        }

        // Return the path to the startup file with the generated port number appended to the end
        return Path.Combine(Path.GetDirectoryName(project.FullPath), $"Startup_{generatedPort}.cs");
    }

    private static bool IsPortInUse(int port)
    {
        IPAddress[] ipAddresses = Dns.GetHostEntry(Dns.GetHostName()).AddressList;
        foreach (var address in ipAddresses)
        {
            IPEndPoint endPoint = new IPEndPoint(address, port);
            using (Socket socket = new Socket(endPoint.AddressFamily, SocketType.Stream, ProtocolType.Tcp))
            {
                try
                {
                    socket.Bind(endPoint);
                    return false; // Port is not in use
                }
                catch (SocketException)
                {
                    continue; // Port is in use or unavailable, try the next address
                }
            }
        }
        return true; // No available port found
    }
}
