using System.Text;

public class DesEncryption
{
    public static string Decrypt(string input, string key)
    {
        using (DES des = DES.Create())
        {
            byte[] bytes = Encoding.UTF8.GetBytes(key);
            des.Key = new byte[8]; // DES uses a 56-bit key
            Array.Copy(bytes, des.Key, Math.Min(des.KeySize / 8, bytes.Length));
            des.IV = new byte[8]; // Use an IV for CBC mode or ECB mode if no real security is needed

            using (MemoryStream ms = new MemoryStream())
