public class XmlParser
{
    public static ParsedValue ParseXml(byte[] xmlBytes, string nodeName, string attributeName)
    {
        using (var memoryStream = new System.IO.MemoryStream(xmlBytes))
        using (var xmlReader = XmlReader.Create(memoryStream))
        {
            while (xmlReader.Read())
            {
                if (xmlReader.NodeType == XmlNodeType.Element && xmlReader.Name == nodeName)
                {
                    if (xmlReader.MoveToAttribute(attributeName))
                    {
                        string attributeValue = xmlReader.Value;
                        // Map the parsed value to an enumeration
                        return ParseAttributeValueToEnum(attributeValue);
                    }
                }
            }
        }
        throw new ArgumentException("Specified node or attribute not found in XML.");
    }

    private static ParsedValue ParseAttributeValueToEnum(string attributeValue)
    {
        // Implement the logic to map string values to enumeration values
        switch (attributeValue.ToLower())
        {
            case "value1":
                return ParsedValue.Value1;
            case "value2":
                return ParsedValue.Value2;
            case "value3":
                return ParsedValue.Value3;
            default:
                throw new ArgumentException("Invalid attribute value.");
        }
    }
}
