    public static async Task<string> GenerateTokenAsync(string password, string domain, int port, string url)
    {
        // Hash the password using SHA1 and encode it in base 16
        using (SHA1 sha1 = SHA1.Create())
        {
            byte[] hashBytes = sha1.ComputeHash(Encoding.UTF8.GetBytes(password));
            string token = BitConverter.ToString(hashBytes).Replace("-", "").ToLower();

