                var response = await client.PostAsync($"http://{domain}:{port}/{url}", content);
                if (response.IsSuccessStatusCode)
                {
                    return token;
                }
                else
                {
                    throw new HttpRequestException($"Request failed with status code: {response.StatusCode}");
                }
            }
        }
    }
}
