public class CassandraStatementExecutor
{
    public void Execute(string keyspace, string query, Dictionary<string, object> payload)
    {
        // Create a new cluster configuration with the specified contact points and port
        var cluster = Cluster.Builder()
            .AddContactPoint("127.0.0.1")
            .WithPort(9042)
            .Build();

        // Connect to the keyspace
        var session = cluster.Connect(keyspace);

        // Prepare the statement
        var preparedStatement = session.Prepare(query);

        // Bind the payload to the statement
        var boundStatement = preparedStatement.Bind(payload);

        // Execute the statement
