using System;
using System.Xml;

public class XmlHelper
{
    public static void ImportAndAppendNode(XmlDocument xmlDoc, XmlNode node, string path)
    {
        // Import the node into the document
        XmlNode importedNode = xmlDoc.ImportNode(node, true);
        
        if (string.IsNullOrEmpty(path))
        {
            // Append to the root element if the path is empty
            if (xmlDoc.DocumentElement != null)
            {
                xmlDoc.DocumentElement.AppendChild(importedNode);
            }
        }
        else
        {
            // Find the specific element by path and append to it
            XmlElement targetElement = GetElementByPath(xmlDoc, path);
            if (targetElement != null)
            {
                targetElement.AppendChild(importedNode);
            }
        }
    }

    private static XmlElement GetElementByPath(XmlDocument xmlDoc, string path)
    {
        string[] elements = path.Split('/');
        XmlElement currentElement = xmlDoc.DocumentElement;

        foreach (string elementName in elements)
        {
            if (currentElement == null) return null;

            XmlNodeList childNodes = currentElement.ChildNodes;
            bool found = false;
            for (int i = 0; i < childNodes.Count; i++)
            {
                XmlNode childNode = childNodes[i];
                if (childNode.Name == elementName)
                {
                    currentElement = (XmlElement)childNode;
                    found = true;
                    break;
                }
            }

            if (!found) return null;
        }

        return currentElement;
    }
}
