public class TypeParameterRetriever
{
    public XElement GetTypeParameterInfo(MethodInfo methodInfo, Type type)
    {
        // Assuming we have an XML document with the necessary information
        string xmlContent = @"<root>
            <method name='MyMethod'>
                <typeParameters>
                    <typeParam name='T1' />
                    <typeParam name='T2' />
                </typeParameters>
            </method>
        </root>";
        
        XDocument xmlDoc = XDocument.Parse(xmlContent);
        
        // Get the method node using reflection on MethodInfo
        var methodNode = xmlDoc.Root?.Element("method")?.Attribute("name")?.Value;
        if (methodNode != methodInfo.Name)
        {
            throw new ArgumentException("Method not found in XML document.");
        }
        
        // Use XPath to find the type parameter node with the specified name
        var typeParam = xmlDoc.Root?.Element("method")?.Element("typeParameters")?.Elements("typeParam")
            .FirstOrDefault(tp => tp.Attribute("name")?.Value == type.Name);
        
        if (typeParam == null)
        {
            throw new ArgumentException("Type parameter not found in XML document.");
        }
        
        // Return the XElement containing information about the type parameter
        return typeParam;
    }
}
