public class AutoClosingSqlCommand : IDisposable
{
    private SqlCommand _command;

    public AutoClosingSqlCommand(string query, SqlConnection connection)
    {
        _command = new SqlCommand(query, connection);
    }

    public DataTable ExecuteQuery()
    {
        using (var adapter = new SqlDataAdapter(_command))
        {
            var dataTable = new DataTable();
            adapter.Fill(dataTable);
            return dataTable;
        }
    }

    public void Dispose()
    {
        _command?.Dispose();
    }
}
