using System;
using System.Data;
using System.Data.Common;

public class SqlExecutor
{
    public static IDataReader ExecuteSQL(string connectionString, CommandType commandType, string commandText, params DbParameter[] parameters)
    {
        using (DbConnection connection = CreateConnection(connectionString))
        {
            try
            {
                connection.Open();
                using (DbCommand command = CreateCommand(commandType, commandText, connection, parameters))
                {
                    return command.ExecuteReader(CommandBehavior.CloseConnection);
                }
            }
            catch (Exception ex)
            {
                // Handle exception as needed
                Console.WriteLine($"An error occurred: {ex.Message}");
                throw;
            }
        }
    }

    private static DbConnection CreateConnection(string connectionString)
    {
        var factory = DbProviderFactories.GetFactory("System.Data.SqlClient");
        var connection = factory.CreateConnection();
        if (connection == null)
        {
            throw new InvalidOperationException("Unable to create a connection object.");
        }
        connection.ConnectionString = connectionString;
        return connection;
    }

    private static DbCommand CreateCommand(CommandType commandType, string commandText, DbConnection connection, params DbParameter[] parameters)
    {
        var factory = DbProviderFactories.GetFactory("System.Data.SqlClient");
        var command = factory.CreateCommand();
        if (command == null)
        {
            throw new InvalidOperationException("Unable to create a command object.");
        }
        command.Connection = connection;
        command.CommandType = commandType;
        command.CommandText = commandText;
        foreach (var parameter in parameters)
        {
            command.Parameters.Add(parameter);
        }
        return command;
    }
}
