using System;
using System.Xml.Linq;
using System.Linq;

public class XmlConfigUpdater
{
    public static void AddSectionAfter(string xmlFilePath, string existingSectionName, string newSectionName)
    {
        XDocument doc = XDocument.Load(xmlFilePath);
        var sections = doc.XPathSelectElements($"//section[@name='{existingSectionName}']");

        if (sections.Count() == 0)
        {
            Console.WriteLine($"Section '{existingSectionName}' not found in the XML file.");
            return;
        }

        foreach (var section in sections)
        {
            var newSection = new XElement("section", new XAttribute("name", newSectionName));
            section.AddAfterSelf(newSection);
        }

        doc.Save(xmlFilePath);
    }
}
