public void UpdateXmlFile(string filePath, string existingElementXPath, string newElementName, string newElementValue)
{
    XDocument xdoc = XDocument.Load(filePath);
    var existingElements = xdoc.XPathSelectElements(existingElementXpath);

    foreach (var element in existingElements)
