using System;
using System.Xml;
using System.Reflection;

public class XmlGenerator
{
    public static XmlDocument GenerateXmlFromType(Type type)
    {
        XmlDocument xmlDoc = new XmlDocument();
        XmlElement root = xmlDoc.CreateElement("root");
        xmlDoc.AppendChild(root);

        // Iterate through the custom attributes of the Type
        foreach (var attribute in type.GetCustomAttributes())
        {
            if (attribute is XmlizedClassAttribute)
            {
                ProcessXmlizedClassAttribute((dynamic)attribute, root);
            }
            else if (attribute is XmlizedSqlstringIDClassAttribute)
            {
                ProcessXmlizedSqlstringIDClassAttribute((dynamic)attribute, root);
            }
        }

        return xmlDoc;
    }

    private static void ProcessXmlizedClassAttribute(XmlizedClassAttribute attribute, XmlElement parentElement)
    {
        // Create the element based on the attributes of XmlizedClassAttribute
        XmlElement classElement = parentElement.OwnerDocument.CreateElement("class");
        classElement.SetAttribute("name", attribute.ClassName);
        classElement.SetAttribute("description", attribute.Description);
        parentElement.AppendChild(classElement);
    }

    private static void ProcessXmlizedSqlstringIDClassAttribute(XmlizedSqlstringIDClassAttribute attribute, XmlElement parentElement)
    {
        // Create the element based on the attributes of XmlizedSqlstringIDClassAttribute
        XmlElement sqlStringIdElement = parentElement.OwnerDocument.CreateElement("sqlStringId");
        sqlStringIdElement.SetAttribute("id", attribute.SqlStringId);
        sqlStringIdElement.SetAttribute("value", attribute.Value);
        parentElement.AppendChild(sqlStringIdElement);
    }
}
