using System.Threading;

class Program
{
    static int RunProcess(string executablePath, string arguments, int timeout)
    {
        Process process = new Process();
        process.StartInfo.FileName = executablePath;
        process.StartInfo.Arguments = arguments;
        process.StartInfo.UseShellExecute = false;
        process.StartInfo.RedirectStandardOutput = true;
        process.StartInfo.RedirectStandardError = true;

        try
        {
            process.Start();
            if (process.WaitForExit(timeout))
            {
                return process.ExitCode;
            }
            else
            {
                // Timeout occurred, kill the process
                process.Kill();
                process.WaitForExit(); // Wait for the process to exit after killing it
                Console.WriteLine($"Process '{executablePath} {arguments}' timed out and was killed.");
                return -1; // Indicate timeout with a specific error code
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
            return -1; // Indicate an error with a specific code
        }
