public class MobileDeviceTaskScheduler : IMobileDeviceTaskScheduler
{
    public void BeginInvokeOnMainThread(Action action)
    {
        NSRunLoop.Main.BeginInvokeOnMainThread(action);
    }

    public ITicker CreateTicker()
    {
