public class CADisplayLinkTicker : ITicker
{
    private readonly CADisplayLink _displayLink;

    public event Action Tick;

    public CADisplayLinkTicker()
    {
        _displayLink = CADisplayLink.Create(() => OnTick());
        _displayLink.AddToRunLoop(NSRunLoop.Main, NSRunLoopMode.Default);
    }

    private void OnTick()
    {
        Tick?.Invoke();
    }

    public void Dispose()
    {
        _displayLink.Dispose();
    }
}
