using System;
using System.Xml;
using System.Xml.XPath;

public static class XmlParser
{
    public static XmlElement GetFirstElement(XmlElement root, string xpath)
    {
        XPathNavigator navigator = root.CreateNavigator();
        XPathNodeIterator nodes = navigator.Select(xpath);

        if (nodes == null || !nodes.MoveNext())
        {
            throw new Exception("No element found matching the given name.");
        }

        XmlElement firstElement = (XmlElement)nodes.Current;

        // Check for multiple elements
        if (nodes.MoveNext())
        {
            throw new Exception("Multiple elements found matching the given name.");
        }

        return firstElement;
    }
}
