public class ConfigurationLoader
{
    public static List<KeyValuePair<string, string>> LoadSettings(string filePath)
    {
        List<KeyValuePair<string, string>> settings = new List<KeyValuePair<string, string>>();

        try
        {
            XmlDocument doc = new XmlDocument();
            doc.Load(filePath);

            XmlElement root = doc.DocumentElement;
            if (root.Name != "configuration")
                throw new Exception("Root element must be 'configuration'");

            foreach (XmlNode node in root.ChildNodes)
            {
                if (node.NodeType == XmlNodeType.Element)
                {
                    XmlElement elem = (XmlElement)node;
                    string key = elem.GetAttribute("key");
                    string value = elem.GetAttribute("value");
                    settings.Add(new KeyValuePair<string, string>(key, value));
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error loading configuration: {ex.Message}");
        }

        return settings;
    }
}
