using System;
using System.IO;

public class FileCopier
{
    public void CopyFiles(string sourceDirectory, string targetDirectory, string[] includeExtensions, string[] excludeExtensions)
    {
        // Ensure the target directory exists
        Directory.CreateDirectory(targetDirectory);

        // Get all files in the source directory
        var files = Directory.GetFiles(sourceDirectory);

        foreach (var file in files)
        {
            string fileName = Path.GetFileName(file);
            if (!ShouldCopyFile(fileName, includeExtensions, excludeExtensions))
                continue;

            string targetFilePath = Path.Combine(targetDirectory, fileName);
            File.Copy(file, targetFilePath, true);
        }
    }

    private bool ShouldCopyFile(string fileName, string[] includeExtensions, string[] excludeExtensions)
    {
        if (includeExtensions != null && includeExtensions.Length > 0)
        {
            string fileExtension = Path.GetExtension(fileName).ToLower();
            if (!Array.Exists(includeExtensions, ext => ext.Equals(fileExtension, StringComparison.OrdinalIgnoreCase)))
                return false;
        }

        if (excludeExtensions != null && excludeExtensions.Length > 0)
        {
            string fileExtension = Path.GetExtension(fileName).ToLower();
            if (Array.Exists(excludeExtensions, ext => ext.Equals(fileExtension, StringComparison.OrdinalIgnoreCase)))
                return false;
        }

        return true;
    }
}
