            }
            catch (Exception ex)
            {
                if (attempt == retryCount - 1) // Last attempt
                {
                    throw new Exception("All attempts failed", ex);
                }
                await Task.Delay(TimeSpan.FromSeconds(Math.Pow(2, attempt))); // Exponential backoff
