using System.Globalization;
using System.Security.Cryptography;
using System.Text;

public class DesEncryption
{
    private static readonly byte[] Key = { 0x01, 0x23, 0x45, 0x67, (byte)0x89, (byte)0xAB, (byte)0xCD, (byte)0xEF };

    public static string DecryptDes(string encryptedHexString)
    {
        if (!IsHexadecimal(encryptedHexString))
        {
            throw new ArgumentException("Input is not a valid hexadecimal representation.");
        }

        byte[] encryptedBytes = HexToByteArray(encryptedHexString);

        using (var des = new DESCryptoServiceProvider())
        {
            des.Key = Key;
            des.Mode = CipherMode.ECB;
            des.Padding = PaddingMode.PKCS7;

            byte[] decryptedBytes = des.CreateDecryptor().TransformFinalBlock(encryptedBytes, 0, encryptedBytes.Length);
            return Encoding.ASCII.GetString(decryptedBytes);
        }
    }

    private static bool IsHexadecimal(string value)
    {
        return !string.IsNullOrEmpty(value) && value.All(c => "0123456789ABCDEFabcdef".Contains(c));
    }

    private static byte[] HexToByteArray(string hex)
    {
        int numberChars = hex.Length;
        byte[] bytes = new byte[numberChars / 2];
        for (int i = 0; i < numberChars; i += 2)
        {
            bytes[i / 2] = Convert.ToByte(hex.Substring(i, 2), 16);
        }
        return bytes;
    }
}
