using System;
using System.Diagnostics;

public class VisualStudioLauncher
{
    public static void OpenProject(string projectFilePath)
    {
        try
        {
            // Check if the solution or project is already open in Visual Studio
            Process[] processes = Process.GetProcessesByName("devenv");
            bool isOpen = false;

            foreach (Process process in processes)
            {
                string fileName = process.MainModule?.FileName;
                if (fileName != null && fileName.EndsWith(projectFilePath, StringComparison.OrdinalIgnoreCase))
                {
                    isOpen = true;
                    break;
                }
            }

            // If not open, launch Visual Studio with the project file path
            if (!isOpen)
            {
                Process.Start("devenv", $"\"{projectFilePath}\"");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
