using System.Xml.Linq;
using System.Linq;

public class XmlConfigUpdater
{
    public void AddIndexProviderSection(string filePath, string existingSectionXPath, XDocument xdoc)
    {
        // Load the XML configuration file
        var configDoc = XDocument.Load(filePath);

        // Select all elements that match the specified XPath expression for the existing section
        var existingSections = configDoc.XPathSelectElements(existingSectionXPath);

        if (!existingSections.Any())
        {
            throw new ArgumentException("The specified existing section does not exist in the XML configuration file.");
        }

        // Add the new index provider section after the last matching existing section
        foreach (var existingSection in existingSections)
        {
            var nextSibling = existingSection.NextNode;
            if (nextSibling == null || !(nextSibling is XElement))
            {
                // If there's no sibling, append the new section at the end of its parent element
                existingSection.AddAfterSelf(xdoc.Root);
            }
            else
            {
                // Insert the new section after the current sibling
                existingSection.AddAfterSelf(xdoc.Root);
            }
        }

        // Save the updated XML configuration file
        configDoc.Save(filePath);
    }
}
