public class XmlUpdater
{
    public static string UpdateXmlFile(string filePath, string xpathToElement, string insertAfterXPath)
    {
        try
        {
            XDocument doc = XDocument.Load(filePath);
            var elementsToRemove = doc.XPathSelectElements(xpathToElement);

            foreach (var element in elementsToRemove.ToList())
            {
                if (element != null)
                {
                    var parent = element.Parent;
                    if (parent != null)
                    {
                        parent.Remove(element);
                    }
                }
            }

            // Assuming you want to insert the removed elements after a specific element found by insertAfterXPath
            var insertAfterElements = doc.XPathSelectElements(insertAfterXPath);

            foreach (var element in elementsToRemove)
            {
                if (insertAfterElements != null && insertAfterElements.Any())
                {
                    foreach (var insertAfterElement in insertAfterElements)
                    {
                        if (insertAfterElement != null)
                        {
                            insertAfterElement.AddBeforeSelf(element);
                        }
                    }
                }
            }

            return doc.ToString();
        }
        catch (Exception ex)
        {
            Console.WriteLine("An error occurred: " + ex.Message);
            return null;
        }
    }
