using System.Xml.XPath;

public class XmlUpdater
{
    public static string UpdateXml(string xmlFilePath, string existingElementXPath, XElement newElement, string insertAfterXPath)
    {
        // Load the XML file
        XDocument doc = XDocument.Load(xmlFilePath);

        // Find the element to insert after
        var targetElements = doc.XPathSelectElements(insertAfterXPath);

        if (targetElements == null || !targetElements.Any())
        {
            throw new ArgumentException("The specified element for insertion does not exist.");
        }

        // Find the existing element to insert after
        var existingElement = doc.XPathSelectElement(existingElementXPath);

        if (existingElement == null)
        {
            throw new ArgumentException("The specified existing element does not exist.");
        }

        // Insert the new element after the existing element
        existingElement.AddAfterSelf(newElement);

        // Save the updated XML file back to disk
        doc.Save(xmlFilePath);

        // Return the updated XML as a string
        return doc.ToString();
    }
}
