using System;
using System.IO;
using System.Xml;

public class SoapParser
{
    public static string GetHttpParameterDocumentation(Stream stream, string charEncoding)
    {
        try
        {
            XmlReaderSettings settings = new XmlReaderSettings();
            settings.IgnoreWhitespace = true;
            settings.IgnoreComments = true;
            using (XmlReader reader = XmlReader.Create(stream, settings))
            {
                reader.MoveToContent();
                if (reader.Name != "Envelope")
                {
                    throw new InvalidOperationException("Unexpected first tag of SOAP request: '" + reader.Name + "' (expected 'Envelope')");
                }

                while (reader.Read())
                {
                    if (reader.NodeType == XmlNodeType.Element && reader.Name == "Body")
                    {
                        break;
                    }
                }

                while (reader.Read())
                {
                    if (reader.NodeType == XmlNodeType.Element)
                    {
                        return reader.GetAttribute("documentation");
                    }
                }
            }
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine("Unable to parse SOAP request: " + ex.Message);
        }

        return null;
    }
}
