using System.Xml.Linq;
using System.Xml.XPath;

public class ConfigurationUpdater
{
    public XDocument UpdateConfiguration(string filePath, string xmlFragment, string xpathExpression)
    {
        // Load the configuration file
        XDocument config = XDocument.Load(filePath);

        // Parse the XML fragment to an XElement
        XElement newSection = XElement.Parse(xmlFragment);

        // Insert the new section after the specified XPath expression
        var targetNode = config.XPathSelectElement(xpathExpression);
        if (targetNode != null)
        {
            targetNode.AddAfterSelf(newSection);
        }
        else
        {
            throw new Exception("The specified XPath expression does not match any element in the configuration file.");
        }

        // Save the updated configuration back to the file
        config.Save(filePath);

        return config;
    }
}
