    public static void RemoveAndAddConfigurationNode(string xmlFilePath, string keyValue)
    {
        XmlDocument doc = new XmlDocument();
        doc.Load(xmlFilePath);

        // Remove the node with the specified key value
        XmlNode nodeToRemove = null;
        foreach (XmlNode node in doc.SelectNodes($"//*[@key='{keyValue}']"))
        {
            nodeToRemove = node;
            break;
        }

        if (nodeToRemove != null)
        {
            XmlNode parentNode = nodeToRemove.ParentNode;
            parentNode.RemoveChild(nodeToRemove);
