        // Add the new node to the document (assuming it's added under some specific parent node)
        XmlNode root = doc.SelectSingleNode("//root"); // Adjust this XPath based on your XML structure
        if (root != null)
        {
            root.AppendChild(newNode);
        }

        // Save the updated XML document
        doc.Save(xmlFilePath);
    }
