    private static object ConvertXmlToPropertyType(PropertyInfo property, XmlNode node)
    {
        Type propertyType = property.PropertyType;
        if (typeof(IExportToXmlable).IsAssignableFrom(propertyType))
        {
            IExportToXmlable exportable = Activator.CreateInstance(propertyType) as IExportToXmlable;
            exportable?.ImportFromXml(node.OuterXml);
            return exportable;
        }
        else if (propertyType == typeof(string))
        {
            return node.InnerText;
        }
        // Add more type conversions as needed
        else
        {
            throw new NotSupportedException($"Type conversion from Xml to {propertyType} is not supported.");
        }
    }
}
