public class SymmetricEncryptionTester
{
    public void TestEncryptionDecryption(SymmetricAlgorithm algorithm, byte[] key, string plaintext)
    {
        // Check if the key size is correct for the selected algorithm
        if (key.Length * 8 != algorithm.KeySize)
        {
            throw new ArgumentException("Invalid key size.");
        }

        // Initialize the encryption and decryption ciphers with ECB mode and zero padding
        ICryptoTransform encryptor = algorithm.CreateEncryptor(key, null);
        ICryptoTransform decryptor = algorithm.CreateDecryptor(key, null);

        // Convert plaintext to byte array
        byte[] plainTextBytes = Encoding.UTF8.GetBytes(plaintext);

        // Encrypt the plaintext message
        byte[] encryptedMessage = encryptor.TransformFinalBlock(plainTextBytes, 0, plainTextBytes.Length);

        // Decrypt the encrypted message
        byte[] decryptedMessage = decryptor.TransformFinalBlock(encryptedMessage, 0, encryptedMessage.Length);

        // Convert decrypted message back to string for comparison
        string decryptedPlaintext = Encoding.UTF8.GetString(decryptedMessage);

        // Check if the decryption is correct and matches the original plaintext
        if (plaintext != decryptedPlaintext)
        {
            throw new Exception("Decryption failed or resulted in incorrect data.");
        }
    }
