import java.util.Random;

public class GaussianMutator {
    public static double mutateValue(Random random, double value, double stdDevFactor) {
        // Generate a random number from a normal (Gaussian) distribution with mean 0 and standard deviation stdDevFactor * value
        double mutation = random.nextGaussian() * stdDevFactor * value;
        return value + mutation;
    }

    public static List<Integer> generateDiscreteValues(Random random, int rangeStart, int rangeEnd, int numValues) {
        List<Integer> values = new ArrayList<>();
        for (int i = 0; i < numValues; i++) {
            // Generate a value within the specified range using a Gaussian distribution
            double mutatedValue = mutateValue(random, (rangeStart + rangeEnd) / 2.0, (rangeEnd - rangeStart) / 6.0);
            int discreteValue = (int) Math.round(mutatedValue);
            // Ensure the value is within the specified range
            if (discreteValue >= rangeStart && discreteValue <= rangeEnd) {
                values.add(discreteValue);
            }
        }
        return values;
    }
}
