import java.util.*;

public class PairMover {
    public static void movePairs(List<Pair> pairs, double percentage) {
        Random rand = new Random();
        int totalPairs = pairs.size();
        int targetProcessed = (int) (totalPairs * percentage);
        int processedCount = 0;

        while (processedCount < targetProcessed) {
            for (int i = 0; i < pairs.size() && processedCount < targetProcessed; i++) {
                Pair currentPair = pairs.get(i);
                boolean isLastPair = (i == pairs.size() - 1);

                System.out.println("Processing pair " + i + ": Is last pair? " + isLastPair);

                if (!isLastPair) {
                    int previousIndex = rand.nextInt(i);
                    Pair previousPair = pairs.get(previousIndex);
                    pairs.set(previousIndex, currentPair);
                    pairs.set(i, previousPair);
                    processedCount++;
                }
            }
        }
    }

    static class Pair {
        int randomInt;
        boolean boolValue;

        Pair(int randomInt, boolean boolValue) {
            this.randomInt = randomInt;
            this.boolValue = boolValue;
        }
    }

