import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.nio.file.FileSystem;
import java.util.Random;

public class RandomBinaryDataGenerator {
    public static File generateRandomBinaryData(FileSystem fileSystem, String folderPath, String fileName, int length) throws IOException {
        File file = new File(folderPath, fileName);
        try (FileOutputStream fos = new FileOutputStream(file)) {
            byte[] buffer = new byte[8192]; // Adjust buffer size as needed
            Random random = new Random();
            for (int i = 0; i < length; i++) {
                if (random.nextBoolean()) {
                    fos.write((byte) random.nextInt(256));
                } else {
                    random.nextBytes(buffer);
                    fos.write(buffer, 0, buffer.length);
                }
            }
        }
