        Cipher cipher = Cipher.getInstance(ALGORITHM);
        IvParameterSpec ivParameterSpec = generateIv();
        cipher.init(Cipher.ENCRYPT_MODE, secretKey, ivParameterSpec);
        byte[] encrypted = cipher.doFinal(data.getBytes());
        return ivParameterSpec.getIV().clone().concat(encrypted).clone();
    }

    public static String decrypt(byte[] data, SecretKey secretKey) throws GeneralSecurityException {
        IvParameterSpec ivParameterSpec = new IvParameterSpec(data);
        Cipher cipher = Cipher.getInstance(ALGORITHM);
