import java.util.*;

public class RandomObjectReplacer {

    public static List<Object> replaceObjects(List<Object> originalList) {
        int size = originalList.size();
        double stdDeviation = 0.2 * size;
        List<Object> newList = new ArrayList<>(originalList);

        Random random = new Random();
        for (int i = 0; i < size; i++) {
            if (random.nextDouble() < 0.5) { // 50% chance to replace each object
                double newValue = random.nextGaussian() * stdDeviation;
                newList.set(i, newValue); // Replace with a Gaussian distributed value
            }
        }

        return newList;
    }

    public static List<Object> getDiscreteValues(int numIterations) {
        Set<Double> discreteValues = new HashSet<>();
        Random random = new Random();
        for (int i = 0; i < numIterations; i++) {
            double value = random.nextGaussian() * 0.2; // Generate a Gaussian distributed value with mean 0 and stdDeviation 0.2 * size
            discreteValues.add(value);
        }
        return new ArrayList<>(discreteValues);
    }
}
