private synchronized void manageThemeCache() {
    // Check if theme bitmap is recycled and recycle it if not
    if (themeBitmap != null && !themeBitmap.isRecycled()) {
        themeBitmap.recycle();
        themeBitmap = null;
    }

    // Check if default theme directory is set, and set it to a specified default value if not
    if (defaultThemeDir == null) {
        defaultThemeDir = new File(Platform.getPlatform().getCacheRoot(), "themes");
    }

    // Parse a PNG file from the cache root directory and put it in theme cache
    File themeFile = new File(defaultThemeDir, "theme.png");
    if (themeFile.exists() && !themeFile.isDirectory()) {
        try {
            BitmapFactory.Options options = new BitmapFactory.Options();
            options.inJustDecodeBounds = true;
            BitmapFactory.decodeStream(new FileInputStream(themeFile), null, options);

            // Calculate inSampleSize
            options.inSampleSize = calculateInSampleSize(options, reqWidth, reqHeight);

            // Decode bitmap with inSampleSize set
            options.inJustDecodeBounds = false;
            themeBitmap = BitmapFactory.decodeStream(new FileInputStream(themeFile), null, options);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

private int calculateInSampleSize(BitmapFactory.Options options, int reqWidth, int reqHeight) {
    // Raw height and width of image
    final int height = options.outHeight;
    final int width = options.outWidth;
    int inSampleSize = 1;

    if (height > reqHeight || width > reqWidth) {
        final int halfHeight = height / 2;
        final int halfWidth = width / 2;

        // Calculate the largest inSampleSize value that is a power of 2 and keeps both
        // height and width larger than the requested height and width.
        while ((halfHeight / inSampleSize) >= reqHeight && (halfWidth / inSampleSize) >= reqWidth) {
            inSampleSize *= 2;
        }
    }

    return inSampleSize;
}
