import java.io.*;
import java.util.concurrent.*;

public class CommandExecutor {

    public ProcessReturnInfo executeCommand(String command) throws IOException, InterruptedException {
        String[] cmdArray = command.split(" ");
        Process proc = Runtime.getRuntime().exec(cmdArray);

        StringBuilder stdout = new StringBuilder();
        StringBuilder stderr = new StringBuilder();

        // Read stdout and stderr in separate threads to avoid deadlock
        Thread stdoutThread = new Thread(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(proc.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    stdout.append(line).append("\n");
                }
            } catch (IOException e) {
                System.err.println("Error reading stdout: " + e.getMessage());
            }
        });

        Thread stderrThread = new Thread(() -> {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(proc.getErrorStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    stderr.append(line).append("\n");
                }
            } catch (IOException e) {
                System.err.println("Error reading stderr: " + e.getMessage());
            }
        });

        stdoutThread.start();
        stderrThread.start();

        // Wait for the process to complete
        int exitCode = proc.waitFor();

        // Join threads and wait for them to finish
        stdoutThread.join();
        stderrThread.join();

        return new ProcessReturnInfo(exitCode, stdout.toString(), stderr.toString());
    }
}

class ProcessReturnInfo {
    private final int exitCode;
    private final String stdout;
    private final String stderr;

    public ProcessReturnInfo(int exitCode, String stdout, String stderr) {
        this.exitCode = exitCode;
        this.stdout = stdout;
        this.stderr = stderr;
    }

    public int getExitCode() {
        return exitCode;
    }

    public String getStdout() {
        return stdout;
    }

    public String getStderr() {
        return stderr;
    }
}
