import java.util.*;
import java.util.function.Function;

public class WeightedItem<T> {
    private T item;
    private double weight;

    public WeightedItem(T item, double weight) {
        this.item = item;
        this.weight = weight;
    }

    public T getItem() {
        return item;
    }

    public double getWeight() {
        return weight;
    }
}

public class WeightedMapGenerator<T> {
    public Map<T, Double> generateNormalizedWeights(List<WeightedItem<T>> items, Function<WeightedItem<T>, Double> weightFunction) {
        Map<T, Double> normalizedWeights = new HashMap<>();
        double totalWeight = 0.0;

        // Calculate the total weight of all items
        for (WeightedItem<T> item : items) {
            totalWeight += weightFunction.apply(item);
        }

        // Calculate and store the normalized weights
        for (WeightedItem<T> item : items) {
            double normalizedWeight = weightFunction.apply(item) / totalWeight;
            normalizedWeights.put(item.getItem(), normalizedWeight);
        }

        return normalizedWeights;
    }
}
