import java.util.*;

public class DisjointPairs {
    static class UnionFind {
        int[] parent;
        int[] rank;

        public UnionFind(int size) {
            parent = new int[size];
            rank = new int[size];
            for (int i = 0; i < size; i++) {
                parent[i] = i;
            }
        }

        public int find(int p) {
            if (parent[p] != p) {
                parent[p] = find(parent[p]); // Path compression
            }
            return parent[p];
        }

        public void union(int p, int q) {
            int rootP = find(p);
            int rootQ = find(q);
            if (rootP != rootQ) {
                if (rank[rootP] > rank[rootQ]) {
                    parent[rootQ] = rootP;
                } else if (rank[rootP] < rank[rootQ]) {
                    parent[rootP] = rootQ;
                } else {
                    parent[rootQ] = rootP;
                    rank[rootP]++;
                }
            }
        }
    }

    public static int countDisjointPairs(int[] arr) {
        int n = arr.length;
        UnionFind uf = new UnionFind(n);
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (uf.find(i) != uf.find(j)) {
                    System.out.println("Pair (" + arr[i] + ", " + arr[j] + ") is disjoint.");
                } else {
                    System.out.println("Pair (" + arr[i] + ", " + arr[j] + ") is not disjoint.");
                }
            }
        }
        return n * (n - 1) / 2; // Total number of pairs in the array
    }

    public static void main(String[] args) {
        int[] arr = {1, 2, 3, 4};
        long startTime = System.currentTimeMillis();
        int result = countDisjointPairs(arr);
        long endTime = System.currentTimeMillis();
        System.out.println("Total number of disjoint pairs: " + result);
        System.out.println("Time taken: " + (endTime - startTime) + " milliseconds");
    }
}
