public class RemoteConnectionHandler {
    private SocketChannel channel;

    public void establishConnection(String host, int port) throws IOException {
        InetSocketAddress remoteAddress = new InetSocketAddress(host, port);
        channel = SocketChannel.open();
        channel.connect(remoteAddress);
        System.out.println("Connected to " + host + ":" + port);
    }

    public void handleConnectionStateChanges() {
        while (true) {
            try {
                if (!channel.isOpen()) {
                    System.out.println("Channel is closed.");
                    break;
                } else {
                    System.out.println("Channel is open.");
                }
                Thread.sleep(1000); // Check state periodically
            } catch (IOException | InterruptedException e) {
                e.printStackTrace();
                break;
            }
        }
    }

    public static void main(String[] args) {
        RemoteConnectionHandler handler = new RemoteConnectionHandler();
        try {
            handler.establishConnection("example.com", 1234);
            handler.handleConnectionStateChanges();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
