import java.util.*;

public class GeoPointComparator {

    public static void compareGeographicalPoints(List<Set<Double>> set1, List<Set<Double>> set2, double tolerance) throws Exception {
        if (set1.size() != set2.size()) {
            throw new Exception("The number of sets is not equal.");
        }

        for (int i = 0; i < set1.size(); i++) {
            Set<Double> points1 = set1.get(i);
            Set<Double> points2 = set2.get(i);

            if (points1.size() != points2.size()) {
                throw new Exception("The number of values in the sets at index " + i + " is not equal.");
            }

            List<Double> list1 = new ArrayList<>(points1);
            List<Double> list2 = new ArrayList<>(points2);

            Collections.sort(list1);
            Collections.sort(list2);

            for (int j = 0; j < list1.size(); j++) {
                if (!isWithinTolerance(list1.get(j), list2.get(j), tolerance)) {
                    throw new Exception("The values at index " + j + " in set " + i + " are not within the specified tolerance.");
                }
            }
        }
    }

    private static boolean isWithinTolerance(double value1, double value2, double tolerance) {
        return Math.abs(value1 - value2) <= tolerance;
    }
}
