import java.util.concurrent.ExecutorService;
import org.sqlg.SQLgGraph;
import org.apache.tinkerpop.gremlin.process.traversal.dsl.graph.GraphTraversalSource;
import org.apache.tinkerpop.gremlin.structure.Vertex;
import java.util.Random;
import java.util.concurrent.CompletableFuture;

public class GraphDatabasePopulator {
    private final ExecutorService executorService;
    private final SQLgGraph<GraphTraversalSource> sqlgGraph;

    public GraphDatabasePopulator(ExecutorService executorService, SQLgGraph<GraphTraversalSource> sqlgGraph) {
        this.executorService = executorService;
        this.sqlgGraph = sqlgGraph;
    }

    public void populateGraphDatabase(int numberOfIterations) {
        Random random = new Random();
        for (int i = 0; i < numberOfIterations; i++) {
            CompletableFuture<Void>[] futures = new CompletableFuture[2];
            for (int j = 0; j < 2; j++) {
                futures[j] = CompletableFuture.runAsync(() -> {
                    Vertex vertex = sqlgGraph.addVertex(null, "name", "RandomVertex" + random.nextInt());
                    if (vertex != null) {
                        System.out.println("Created vertex: " + vertex.value("name"));
                    }
                }, executorService);
            }
            CompletableFuture<Void> edgeFuture = CompletableFuture.runAsync(() -> {
                Vertex v1 = sqlgGraph.traversal().V().next();
                Vertex v2 = sqlgGraph.traversal().V().toList().get(random.nextInt(sqlgGraph.traversal().V().count().next()));
                if (v1 != null && v2 != null) {
                    sqlgGraph.addEdge(null, v1, "CONNECTED_TO", v2, "weight", random.nextDouble());
                    System.out.println("Created edge between: " + v1.value("name") + " and " + v2.value("name"));
                }
            }, executorService);

            CompletableFuture.allOf(futures).thenRun(() -> {
                try {
                    Thread.sleep(100); // Simulate transaction commit delay
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
                System.out.println("Committed transaction after iteration: " + i);
            }).join();
            edgeFuture.join();
        }
    }
}
