import java.util.ArrayList;
import java.util.List;
import java.util.Random;

class LocationTime {
    double latitude;
    double longitude;
    long timestamp;

    LocationTime(double latitude, double longitude, long timestamp) {
        this.latitude = latitude;
        this.longitude = longitude;
        this.timestamp = timestamp;
    }
}

class SensorData {
    long timestamp;
    String type;
    double[] data;

    SensorData(long timestamp, String type, double[] data) {
        this.timestamp = timestamp;
        this.type = type;
        this.data = data;
    }
}

public class SensorDataGenerator {
    public static List<SensorData> generateSensorData(List<LocationTime> locations, double[][] standardDeviations, double stepsPerSecond) {
        List<SensorData> sensorDataList = new ArrayList<>();
        Random random = new Random();

        for (int i = 0; i < locations.size(); i++) {
            LocationTime location = locations.get(i);
            double[] stdDev = standardDeviations[i];

            // Generate accelerometer readings with Gaussian noise based on standard deviations
            double accX = random.nextGaussian() * stdDev[0];
            double accY = random.nextGaussian() * stdDev[1];
            double accZ = random.nextGaussian() * stdDev[2];

            // Create SensorData object and add to the list
            sensorDataList.add(new SensorData(location.timestamp, "ACC", new double[]{accX, accY, accZ}));
        }

        return sensorDataList;
    }
}
