import java.io.*;

class CustomObject implements Serializable {
    int d;
    double x;
    float y;
    boolean z;

    public CustomObject(int d, double x, float y, boolean z) {
        this.d = d;
        this.x = x;
        this.y = y;
        this.z = z;
    }
}

public class SerializationExample {
    public static void main(String[] args) {
        CustomObject obj = new CustomObject(10, 20.5, 30.0f, true);
        String filename = "custom_object.ser";

        // Serialize the object to a file
        try (FileOutputStream fos = new FileOutputStream(filename);
             ObjectOutputStream oos = new ObjectOutputStream(fos)) {
            oos.writeObject(obj);
            System.out.println("Object has been serialized");
        } catch (IOException e) {
            e.printStackTrace();
        }

        // Deserialize the object from the file
        CustomObject deserializedObj = null;
        try (FileInputStream fis = new FileInputStream(filename);
             ObjectInputStream ois = new ObjectInputStream(fis)) {
            deserializedObj = (CustomObject) ois.readObject();
            System.out.println("Object has been deserialized");
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        }

        // Print the deserialized object to verify
        System.out.println("d: " + deserializedObj.d);
        System.out.println("x: " + deserializedObj.x);
        System.out.println("y: " + deserializedObj.y);
        System.out.println("z: " + deserializedObj.z);
    }
}
