import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class HashConcatenator {
    public static byte[] concatenateMD5AndMD2Hashes(byte[] input) {
        try {
            // Compute MD5 hash
            MessageDigest md5 = MessageDigest.getInstance("MD5");
            byte[] md5Hash = md5.digest(input);

            // Compute MD2 hash
            MessageDigest md2 = MessageDigest.getInstance("MD2");
            byte[] md2Hash = md2.digest(input);

            // Concatenate the two hashes
            byte[] result = new byte[32];
            System.arraycopy(md5Hash, 0, result, 0, 16);
            System.arraycopy(md2Hash, 0, result, 16, 16);

            return result;
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD2 algorithm not available.", e);
        }
    }
}
