import java.io.*;
import java.util.Hashtable;

public class FileFilter {
    public static void main(String[] args) {
        String directoryPath = "path/to/directory"; // Specify the directory path
        Hashtable<String, Object> dataTable = new Hashtable<>();

        try (FileInputStream fis = new FileInputStream(new File(directoryPath))) {
            processDirectory(dataTable, directoryPath);
        } catch (FileNotFoundException e) {
            System.err.println("Directory not found: " + directoryPath);
        } catch (IOException e) {
            e.printStackTrace();
        } catch (ClassNotFoundException e) {
            System.err.println("Class not found");
        }

        // Output the files that contain the specified type of data
        for (String key : dataTable.keySet()) {
            System.out.println(key);
        }
    }

    private static void processDirectory(Hashtable<String, Object> dataTable, String directoryPath) throws IOException, ClassNotFoundException {
        File directory = new File(directoryPath);
        File[] files = directory.listFiles();

        if (files == null) {
            return;
        }

        for (File file : files) {
            if (file.isDirectory()) {
                processDirectory(dataTable, file.getAbsolutePath());
            } else if (file.getName().endsWith(".dat")) { // Specify the file extension to filter by
                try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
                    Object data = ois.readObject();
                    dataTable.put(file.getAbsolutePath(), data);
                } catch (FileNotFoundException e) {
                    System.err.println("File not found: " + file.getAbsolutePath());
                }
            }
        }
    }
}
