public class POS_Tagger {
    private static final String MODEL_FILE = "hmm_model.txt";

    public static void main(String[] args) throws IOException {
        // Load the HMM model from a file
        Map<String, Map<String, Double>> transitionProbabilities = readModelFromFile();
        System.out.println("Model loaded successfully.");

        // Example input text
        String inputText = "The quick brown fox jumps over the lazy dog";

        // Perform POS tagging on the input text
        List<String> taggedWords = tagPOS(inputText, transitionProbabilities);

        // Print the tagged words
        for (String word : taggedWords) {
            System.out.println(word);
        }
    }

    private static Map<String, Map<String, Double>> readModelFromFile() throws IOException {
        Map<String, Map<String, Double>> model = new HashMap<>();
        BufferedReader reader = new BufferedReader(new FileReader(MODEL_FILE));
        String line;
        while ((line = reader.readLine()) != null) {
            String[] parts = line.split(" ");
            if (parts.length == 3) {
                String previousTag = parts[0];
                String currentTag = parts[1];
                double probability = Double.parseDouble(parts[2]);

                model.putIfAbsent(previousTag, new HashMap<>());
                model.get(previousTag).put(currentTag, probability);
            }
        }
        reader.close();
        return model;
    }

    private static List<String> tagPOS(String inputText, Map<String, Map<String, Double>> transitionProbabilities) {
        List<String> taggedWords = new ArrayList<>();
        String[] words = inputText.split(" ");
        for (int i = 0; i < words.length; i++) {
            String word = words[i];
            if (i == 0) {
                // For the first word, assume a start tag
                taggedWords.add(word + "_START");
            } else {
                String previousTag = taggedWords.get(i - 1).split("_")[1];
                Map<String, Double> transitionProbability = transitionProbabilities.get(previousTag);
                if (transitionProbability != null) {
                    // Find the tag with the highest probability for the current word
                    String bestTag = "";
                    double maxProbability = -Double.MAX_VALUE;
                    for (Map.Entry<String, Double> entry : transitionProbability.entrySet()) {
                        if (entry.getValue() > maxProbability) {
                            maxProbability = entry.getValue();
                            bestTag = entry.getKey();
                        }
                    }
                    taggedWords.add(word + "_" + bestTag);
                } else {
                    // If no transition probability is available, use a default tag (e.g., "NN")
                    taggedWords.add(word + "_NN");
                }
            }
        }
        return taggedWords;
    }
}
