import java.io.FileInputStream;
import java.io.IOException;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.Properties;

public class SocketBinder {
    public static void main(String[] args) {
        int port = getPortFromProperties();
        if (port == -1) {
            System.out.println("Failed to read port from properties file.");
            return;
        }
        bindSocketToPort(port);
    }

    private static int getPortFromProperties() {
        Properties props = new Properties();
        try (FileInputStream fis = new FileInputStream("config.properties")) {
            props.load(fis);
            return Integer.parseInt(props.getProperty("server.port"));
        } catch (IOException e) {
            e.printStackTrace();
            return -1;
        }
    }

    private static void bindSocketToPort(int port) {
        ServerSocket serverSocket = null;
        try {
            serverSocket = new ServerSocket(port);
            System.out.println("Server started on port " + port);
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            if (serverSocket != null && !serverSocket.isClosed()) {
                try {
                    serverSocket.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }
    }
}
