public class HttpUtils {
    public static String sendPostRequest(String uri, String requestBody, @Nullable String tokenHeader, 
                                         @Nullable Integer maxRate) throws IOException {
        HttpClient httpClient = new HttpClient();
        PostMethod postMethod = new PostMethod(uri);

        if (tokenHeader != null) {
            postMethod.addRequestHeader("Authorization", "Bearer " + tokenHeader);
        }

        if (requestBody != null && requestBody.endsWith(".gz")) {
            // Decompress the GZIP body
            try (GZIPInputStream gzipInputStream = new GZIPInputStream(new ByteArrayInputStream(requestBody.getBytes()))) {
                byte[] buffer = new byte[1024];
                int bytesRead;
                StringBuilder decompressedBodyBuilder = new StringBuilder();
                while ((bytesRead = gzipInputStream.read(buffer)) != -1) {
                    decompressedBodyBuilder.append(new String(buffer, 0, bytesRead, StandardCharsets.UTF_8));
                }
                requestBody = decompressedBodyBuilder.toString();
            }
        }

        RequestEntity entity = new StringRequestEntity(requestBody, "application/json", "UTF-8");
        postMethod.setRequestEntity(entity);

