public class MD5HashGenerator {

    public static void generateMD5Hash(String filePath) {
        try (FileInputStream fis = new FileInputStream(filePath);
             FileOutputStream fos = new FileOutputStream(filePath + ".md5")) {

            // Create MD5 Hash
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
            byte[] hashBytes = md.digest();

            // Write the MD5 Hash to a new file
            fos.write(hashBytes);
            System.out.println("MD5 hash generated and saved to " + filePath + ".md5");
        } catch (IOException | NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        String filePath = "/path/to/your/file"; // Replace with your file path
        generateMD5Hash(filePath);
    }
}
