            revisionIds.append(revision.getId());
        }

        // Create a string to be hashed, including the last updated timestamp, row version, account ID, and revision IDs
        String dataToHash = Long.toString(lastUpdatedTimestamp) + "." + Long.toString(rowVersion) + "." + accountId + "." + revisionIds.toString();

        // Calculate the MD5 hash of the string
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(dataToHash.getBytes());

            // Convert the hash to a Base64 encoded string
            String base64EncodedHash = Base64.getEncoder().encodeToString(digest);

            // Return the ETag value as a string
            return "\"" + base64EncodedHash + "\"";
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not found", e);
        }
    }
}
