import java.nio.channels.DatagramChannel;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class DatagramConnector {
    public static DatagramConnector setupConnection(String uri) throws IllegalArgumentException {
        if (uri == null || uri.isEmpty()) {
            throw new IllegalArgumentException("URI cannot be null or empty");
        }

        // Parse the URI to extract necessary information
        String[] parts = uri.split(":");
        if (parts.length != 2) {
            throw new IllegalArgumentException("Invalid URI format. Expected format: host:port");
        }

        String host = parts[0];
        int port;
        try {
            port = Integer.parseInt(parts[1]);
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("Invalid port number in URI");
        }

        // Create and configure the DatagramChannel
        DatagramChannel channel = null;
        try {
            channel = DatagramChannel.open();
            InetSocketAddress address = new InetSocketAddress(host, port);
            channel.bind(address);

            // Configure processor count and thread pool executor
            int processorCount = Runtime.getRuntime().availableProcessors();
            ExecutorService executor = Executors.newFixedThreadPool(processorCount);
            channel.configureBlocking(false);
            channel.setOption(StandardSocketOptions.SO_REUSEADDR, true);

            // Return the DatagramConnector object
            return new DatagramConnector(channel, address, executor);
        } catch (Exception e) {
            if (channel != null) {
                try {
                    channel.close();
                } catch (Exception closeException) {
                    // Ignore close exception
                }
            }
            throw new IllegalArgumentException("Failed to setup connection", e);
        }
    }

    private DatagramChannel channel;
    private InetSocketAddress address;
    private ExecutorService executor;

    private DatagramConnector(DatagramChannel channel, InetSocketAddress address, ExecutorService executor) {
        this.channel = channel;
        this.address = address;
        this.executor = executor;
    }

