import java.io.*;
import java.util.concurrent.*;
import org.apache.logging.log4j.*;

public class ProcessExecutor {
    private static final Logger logger = LogManager.getLogger(ProcessExecutor.class);
    private Runtime rt = Runtime.getRuntime();

    public boolean executeProcess(String command, List<String> args) {
        if (command == null || command.isEmpty()) {
            logger.error("Command is empty or null.");
            return false;
        }

        String[] cmdArray = new String[args.size() + 1];
        cmdArray[0] = command;
        for (int i = 0; i < args.size(); i++) {
            cmdArray[i + 1] = args.get(i);
        }

        logger.info("Executing process with command: {}", String.join(" ", cmdArray));

        Process proc;
        try {
            proc = rt.exec(cmdArray);
        } catch (IOException e) {
            logger.error("Failed to execute process: {}", e.getMessage());
            return false;
        }

        Watchdog watchdog = new Watchdog(60000, proc);
        watchdog.start();

        try {
            int exitCode = proc.waitFor();
            watchdog.interrupt();
            logger.info("Process exited with code: {}", exitCode);
            return true;
        } catch (InterruptedException e) {
            logger.error("Process execution interrupted: {}", e.getMessage());
            Thread.currentThread().interrupt();
            proc.destroyForcibly();
            return false;
        }
    }

    private static class Watchdog extends Thread {
        private final int timeout;
        private final Process process;

        public Watchdog(int timeout, Process process) {
            this.timeout = timeout;
            this.process = process;
        }

        @Override
        public void run() {
            try {
                if (process.waitFor(timeout, TimeUnit.MILLISECONDS)) {
                    return; // Process completed within the timeout
                }
            } catch (InterruptedException e) {
                logger.error("Watchdog interrupted: {}", e.getMessage());
                Thread.currentThread().interrupt();
            }
            process.destroyForcibly();
            logger.warn("Process timed out and was forcibly terminated.");
        }
    }
}
