import java.io.*;

public class SerializationBenchmark {
    public static void main(String[] args) {
        // Define a sample object to serialize and deserialize
        MyObject obj = new MyObject("test", 42);

        long totalSerializationTime = 0;
        long totalDeserializationTime = 0;
        int dataSizeSum = 0;

        for (int i = 0; i < 500; i++) {
            // Measure serialization time and size
            long startTime = System.nanoTime();
            byte[] serializedData = serialize(obj);
            long endTime = System.nanoTime();
            long serializationTime = endTime - startTime;
            int dataSize = serializedData.length;

            totalSerializationTime += serializationTime;
            dataSizeSum += dataSize;

            // Measure deserialization time
            startTime = System.nanoTime();
            MyObject deserializedObj = deserialize(serializedData);
            endTime = System.nanoTime();
            long deserializationTime = endTime - startTime;

            totalDeserializationTime += deserializationTime;

            // Verify the deserialized object matches the original
            if (!obj.equals(deserializedObj)) {
                throw new RuntimeException("Deserialized object does not match the original.");
            }
        }

        double averageSerializationTime = (double) totalSerializationTime / 500;
        double averageDeserializationTime = (double) totalDeserializationTime / 500;
        int averageDataSize = dataSizeSum / 500;

        System.out.println("Average Serialization Time: " + averageSerializationTime + " ns");
        System.out.println("Average Deserialization Time: " + averageDeserializationTime + " ns");
        System.out.println("Average Data Size: " + averageDataSize + " bytes");
    }

    public static byte[] serialize(Object obj) {
        try (ByteArrayOutputStream bos = new ByteArrayOutputStream();
             ObjectOutputStream out = new ObjectOutputStream(bos)) {
            out.writeObject(obj);
            return bos.toByteArray();
        } catch (IOException e) {
            throw new RuntimeException("Serialization failed", e);
        }
    }

