import java.io.*;
import java.util.*;

public class MapMerger {
    public static Map<String, Byte> mergeMaps(Map<String, String> stringMap, InputStream binaryStream) throws IOException {
        // Deserialize the binary data stream into a map of string keys to byte values
        Map<String, Byte> binaryMap = new HashMap<>();
        DataInputStream dis = new DataInputStream(binaryStream);
        while (dis.available() > 0) {
            String key = dis.readUTF();
            byte value = dis.readByte();
            binaryMap.put(key, value);
        }
        dis.close();

        // Merge the two maps into a single map of string keys to byte values
        Map<String, Byte> mergedMap = new HashMap<>(stringMap);
        mergedMap.putAll(binaryMap);

        return mergedMap;
    }
}
