public class HashFunction {
    public static int hashString(String str) {
        return str.hashCode();
    }

    public static long customHashFunction(String str, String hashType) {
        switch (hashType.toLowerCase()) {
            case "java":
                return javaHashFunction(str);
            case "custom1":
                return customHash1(str);
            default:
                throw new IllegalArgumentException("Unknown hash type");
        }
    }

    private static long javaHashFunction(String str) {
        int h = 0;
        for (char c : str.toCharArray()) {
            h = 31 * h + c;
        }
        return (long) h;
    }

    private static long customHash1(String str) {
        long hash = 5381;
        for (char c : str.toCharArray()) {
            hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
        }
        return hash & Long.MAX_VALUE;
    }

    public static void main(String[] args) {
        String testStr = "example";
        System.out.println("Java's default hashCode: " + hashString(testStr));
        System.out.println("Custom Java Hash Function: " + customHashFunction(testStr, "java"));
        System.out.println("Custom Hash Function 1: " + customHashFunction(testStr, "custom1"));
