            @SuppressWarnings("unchecked")
            T[] array = (T[]) Array.newInstance(clazz.getComponentType(), size);

            // Read the objects into the array
            for (int i = 0; i < size; i++) {
                array[i] = clazz.cast(objIn.readObject());
            }

            return array;
        }
    }
