public class PathHasher {
    public static String generateHashCode(Map<String, String> paths, String moduleName, boolean createSymlinks, boolean createHeaderMap) {
        StringBuilder combinedData = new StringBuilder();

        // Append module name
        combinedData.append(moduleName);

        // Append symlink state
        combinedData.append(createSymlinks ? "true" : "false");

        // Append header map state
        combinedData.append(createHeaderMap ? "true" : "false");

        // Append paths and linked paths
        for (String path : paths.keySet()) {
            combinedData.append(path).append(paths.get(path));
        }

        try {
            // Create SHA-1 hash object
            MessageDigest sha1 = MessageDigest.getInstance("SHA-1");

            // Compute the hash code
            byte[] hashBytes = sha1.digest(combinedData.toString().getBytes());

            // Convert to hexadecimal string
            StringBuilder hexString = new StringBuilder();
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }

            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("SHA-1 algorithm not found", e);
        }
    }
