import java.io.*;

public class SingletonLoader<T> {
    private static final String FILE_NAME = "singletonInstance.ser";

    public T getSingletonInstance(Class<T> clazz, Supplier<T> supplier) {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(FILE_NAME))) {
            return clazz.cast(ois.readObject());
        } catch (IOException | ClassNotFoundException e) {
            // Log the exception or handle it as needed
            T instance = supplier.get();
            saveSingletonInstance(instance);
            return instance;
        }
    }

    private void saveSingletonInstance(T instance) {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(FILE_NAME))) {
            oos.writeObject(instance);
        } catch (IOException e) {
            // Log the exception or handle it as needed
            e.printStackTrace();
        }
    }
}
