import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;

public class TokenGenerator {
    public String generateToken() {
        try {
            SecureRandom random = new SecureRandom();
            byte[] bytes = new byte[4]; // 16 bits (2 hex digits) * 8 characters = 128 bits / 8 = 16 bytes
            random.nextBytes(bytes);

            MessageDigest md = MessageDigest.getInstance("SHA-1");
            byte[] hashBytes = md.digest(bytes);

            StringBuilder tokenBuilder = new StringBuilder();
            for (byte b : hashBytes) {
                String hex = Integer.toHexString((b & 0xFF) | 0x100).substring(1, 3);
                tokenBuilder.append(hex);
            }

            return tokenBuilder.toString().substring(0, 8); // Ensure the token is exactly 8 characters long
        } catch (NoSuchAlgorithmException e) {
            e.printStackTrace();
            return null;
        }
    }
}
