import java.io.InputStream;
import java.io.OutputStream;
import java.util.OptionalLong;

public class CommandExecutor {
    public int executeCommand(String[] command, InputStream inputStream, OutputStream outputStream, OptionalLong timeout) {
        try {
            Process process = Runtime.getRuntime().exec(command);

            if (inputStream != null) {
                copyInputStreamToOutputStream(process.getErrorStream(), outputStream);
            }

            int exitCode = process.waitFor();
            return exitCode;
        } catch (Exception e) {
            throw new RuntimeException("Failed to execute command", e);
        }
    }

    private void copyInputStreamToOutputStream(InputStream inputStream, OutputStream outputStream) throws IOException {
        byte[] buffer = new byte[1024];
        int bytesRead;
        while ((bytesRead = inputStream.read(buffer)) != -1) {
            outputStream.write(buffer, 0, bytesRead);
        }
    }
}
