public class XMLParser {
    public static String evaluateXPath(String responseValue, String xpathExpression) throws Exception {
        // Parse the input string as XML
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        DocumentBuilder builder = factory.newDocumentBuilder();
        Document document = builder.parse(new InputSource(new java.io.StringReader(responseValue)));

        // Create XPath factory and evaluate the expression
        XPathFactory xpathFactory = XPathFactory.newInstance();
        XPath xpath = xpathFactory.newXPath();
        boolean result = (Boolean) xpath.evaluate(xpathExpression, document, XPathConstants.BOOLEAN);

        // Return null if the expression evaluates to true, otherwise return a failure detail message
        if (result) {
            return null;
        } else {
            return "XPath expression returned false";
        }
    }
}
