import java.util.Random;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

public class ServiceStarter {
    private static final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
    private static final Random random = new Random();
    private static boolean serviceRunning = false;

    public static void main(String[] args) {
        startServiceWithRandomDelay();
    }

    private static void startServiceWithRandomDelay() {
        scheduler.scheduleAtFixedRate(() -> {
            if (!serviceRunning) {
                startService();
            } else {
                stopService();
            }
        }, 0, getRandomDelay(), TimeUnit.SECONDS);
    }

    private static void startService() {
        serviceRunning = true;
        System.out.println("Service started.");
    }

    private static void stopService() {
        serviceRunning = false;
        sendMessageToMessagingSystem();
        System.out.println("Service stopped.");
    }

    private static long getRandomDelay() {
        return random.nextInt(10) + 1; // Random delay between 1 and 10 seconds
    }

    private static void sendMessageToMessagingSystem() {
        System.out.println("Sending message to messaging system.");
    }
}
