import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class Encryptor {
    public static String encryptMessage(String message, String encodingScheme, boolean toUpperCase) {
        try {
            // Create MessageDigest instance for MD5
            MessageDigest md = MessageDigest.getInstance("MD5");

            // Perform the hash computation
            byte[] digest = md.digest(message.getBytes());

            // Convert the byte array into a signum representation
            StringBuilder sb = new StringBuilder();
            for (byte b : digest) {
                sb.append(Integer.toString((b & 0xff) + 0x100, 16).substring(1));
            }

            // Convert the result to uppercase if specified
            String encryptedMessage = sb.toString();
            if (toUpperCase) {
                encryptedMessage = encryptedMessage.toUpperCase();
            }

            return encryptedMessage;
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("MD5 algorithm not found", e);
        }
    }
}
