    public void executeExternalTool(String templateFilePath, String outputFilePath) throws IOException, InterruptedException {
        // Read the template file content
        String templateContent = readFile(templateFilePath);

        // Prepare the command to invoke the external tool
        List<String> command = new ArrayList<>();
        command.add("tool_executable"); // Assuming the executable is named "tool_executable"
        command.add("--output");
        command.add(outputFilePath);

