        ProcessBuilder processBuilder = new ProcessBuilder(command);
        processBuilder.redirectErrorStream(true);
        Process process = processBuilder.start();

        // Write the template content to the standard input of the external tool
        try (OutputStream os = process.getOutputStream()) {
            os.write(templateContent.getBytes());
            os.flush();
        }

        // Wait for the external tool to terminate
        int exitCode = process.waitFor();
        System.out.println("External tool exited with code: " + exitCode);

        // Read and print the output from the external tool
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }
        }
    }

    private String readFile(String filePath) throws IOException {
        StringBuilder contentBuilder = new StringBuilder();
        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                contentBuilder.append(line).append("\n");
            }
        }
        return contentBuilder.toString();
    }
