import java.io.*;
import java.net.HttpURLConnection;
import java.net.URL;

public class FileUploader {
    private static final int MAX_RETRIES = 3;

    public static boolean uploadFile(String fileToUpload, String remoteServerUrl) throws IOException {
        int retryCount = 0;
        while (retryCount < MAX_RETRIES) {
            try {
                URL url = new URL(remoteServerUrl);
                HttpURLConnection connection = (HttpURLConnection) url.openConnection();
                connection.setDoOutput(true);
                connection.setRequestMethod("POST");
                connection.setRequestProperty("Content-Type", "multipart/form-data");

                // Write the file to the request
                FileInputStream fis = new FileInputStream(fileToUpload);
                OutputStream os = connection.getOutputStream();
                byte[] buffer = new byte[4096];
                int bytesRead;
                while ((bytesRead = fis.read(buffer)) != -1) {
                    os.write(buffer, 0, bytesRead);
                }
                os.close();
                fis.close();

                // Get the response code
                int responseCode = connection.getResponseCode();
                if (responseCode == HttpURLConnection.HTTP_OK) {
                    return true; // Upload successful
                } else {
                    System.out.println("Upload failed with response code: " + responseCode);
                }
            } catch (IOException e) {
                retryCount++;
                System.out.println("Retry attempt: " + retryCount);
                if (retryCount >= MAX_RETRIES) {
                    throw new IOException("Failed to upload file after " + MAX_RETRIES + " attempts", e);
                }
            }
        }
        return false; // Upload failed after all retries
    }
}
