public class Graph {
    private Map<String, Set<String>> adjacencyList;
    private Set<String> cachedEdges;

    public Graph() {
        adjacencyList = new HashMap<>();
        cachedEdges = new HashSet<>();
    }

    public void addVertex(String vertex) {
        adjacencyList.putIfAbsent(vertex, new HashSet<>());
    }

    public void addEdge(String source, String destination) {
        if (!cachedEdges.contains(hashEdge(source, destination))) {
            adjacencyList.get(source).add(destination);
            cachedEdges.add(hashEdge(source, destination));
        }
    }

    private String hashEdge(String source, String destination) {
        return source + "-" + destination;
    }
}
