import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;

public class ExecuteCommand {
    public static String executeRootCommand(String command, String user) throws IOException, InterruptedException {
        if (user.equals("root")) {
            return runCommand(command);
        } else {
            return runCommandWithSu("-c " + command, user);
        }
    }

    private static String runCommand(String command) throws IOException, InterruptedException {
        Process process = Runtime.getRuntime().exec(command);
        StringBuilder output = new StringBuilder();
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            output.append(line).append("\n");
        }
        process.waitFor();
        return output.toString();
    }

    private static String runCommandWithSu(String command, String user) throws IOException, InterruptedException {
        ProcessBuilder pb = new ProcessBuilder("su", "-c", command, user);
        Process process = pb.start();
        StringBuilder output = new StringBuilder();
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line;
        while ((line = reader.readLine()) != null) {
            output.append(line).append("\n");
        }
        process.waitFor();
        return output.toString();
    }
}
