import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.*;

public class IntervalMerger {
    public static String mergeIntervals(List<Interval> intervals) {
        if (intervals == null || intervals.isEmpty()) {
            return "";
        }

        // Sort intervals by start time
        Collections.sort(intervals, Comparator.comparing(Interval::getStart));

        List<Interval> mergedIntervals = new ArrayList<>();
        Interval currentInterval = intervals.get(0);

        for (int i = 1; i < intervals.size(); i++) {
            Interval nextInterval = intervals.get(i);
            if (currentInterval.getEnd().isAfter(nextInterval.getStart())) {
                // Overlapping intervals, merge them
                currentInterval = new Interval(currentInterval.getStart(), max(currentInterval.getEnd(), nextInterval.getEnd()));
            } else {
                // Non-overlapping intervals, add the current interval to the list and move to the next one
                mergedIntervals.add(currentInterval);
                currentInterval = nextInterval;
            }
        }

        // Add the last remaining interval
        mergedIntervals.add(currentInterval);

        // Format the result as 'start-end'
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");
        StringBuilder result = new StringBuilder();
        for (Interval interval : mergedIntervals) {
            result.append(interval.getStart().format(formatter)).append("-").append(interval.getEnd().format(formatter)).append(", ");
        }

        // Remove the trailing comma and space
        if (result.length() > 0) {
            result.setLength(result.length() - 2);
        }

        return result.toString();
    }

    private static LocalDateTime max(LocalDateTime a, LocalDateTime b) {
        return a.isAfter(b) ? a : b;
    }

    public static class Interval {
        private final LocalDateTime start;
        private final LocalDateTime end;

        public Interval(LocalDateTime start, LocalDateTime end) {
            this.start = start;
            this.end = end;
        }

        public LocalDateTime getStart() {
            return start;
        }

        public LocalDateTime getEnd() {
            return end;
        }
    }
}
