import java.net.InetAddress;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class NodeIdentifierGenerator {
    public static long generateNodeId() {
        try {
            String hostAddress = InetAddress.getLocalHost().getHostAddress();
            MessageDigest md5 = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md5.digest(hostAddress.getBytes());

            // Ignore the upper 8 bits and set the upper 8 bits of the result to 0
            long nodeId = ((long) (hashBytes[0] & 0xFF)) << 56;
            for (int i = 1; i < 8; i++) {
                nodeId |= ((long) (hashBytes[i] & 0xFF)) << (56 - 8 * i);
            }

            return nodeId;
        } catch (Exception e) {
            throw new RuntimeException("Failed to generate node ID", e);
        }
    }
}
