function reduceAsync(arr, initialValue, callback) {
    return new Promise((resolve, reject) => {
        let accumulatedValue = initialValue;
        const processNextItem = (index) => {
            if (index >= arr.length) {
                resolve(accumulatedValue);
                return;
            }
            const currentNumber = arr[index];
            callback(accumulatedValue, currentNumber).then((result) => {
                accumulatedValue = result;
                processNextItem(index + 1);
            }).catch((error) => {
                reject(error);
            });
        };
        processNextItem(0);
    });
}

