const stylus = require('stylus');
const fs = require('fs');
const path = require('path');

function generateCSS(filePath, destinationDir) {
    // Read the Stylus files and concatenate their contents
    let stylusContent = '';
    const stylusFiles = [filePath]; // Assuming filePath is a directory containing multiple Stylus files

    stylusFiles.forEach(file => {
        const content = fs.readFileSync(file, 'utf-8');
        stylusContent += content + '\n';
    });

    // Compile the concatenated Stylus content to CSS
    stylus.render(stylusContent, (err, css) => {
        if (err) {
            console.error('Error compiling Stylus:', err);
            return;
        }

        // Define the destination file path
        const destFilePath = path.join(destinationDir, 'output.css');

        // Write the compiled CSS to the destination file
        fs.writeFileSync(destFilePath, css);
        console.log('CSS file generated successfully:', destFilePath);
    });
}

