ParsedResult parseAction(uint8_t *buffer, uint32_t offset) {
    ParsedResult result = {0};
    ErrorResult error = {0};

    if (offset + sizeof(ActionType) > msg_size) {
        strcpy(error.message, "Invalid action length");
        error.code = ERROR_CODE_INVALID_LENGTH;
        return (ParsedResult){ .error = error };
    }

    ActionType type = *(ActionType *)(buffer + offset);
    result.offset = offset + sizeof(ActionType);

    switch (type) {
        case ACTION_TYPE_OUTPUT:
