                strcpy(error.message, "Invalid output action length");
                error.code = ERROR_CODE_INVALID_LENGTH;
                return (ParsedResult){ .error = error };
            }
            memcpy(&result.action.output, buffer + result.offset, sizeof(OutputAction));
            result.action.type = ACTION_TYPE_OUTPUT;
            result.offset += sizeof(OutputAction);
