function getValueFromConfig(config, key) {
    let value = config[key];

    if (value !== undefined) {
        return value;
    }

    // Check if the file exists in the current directory or a parent directory
    const path = require('path');
    const fs = require('fs');
    const util = require('util');
    const readFile = util.promisify(fs.readFile);

    async function checkDirectoryForFile(dir) {
        const filePath = path.join(dir, 'config.json');
        if (fs.existsSync(filePath)) {
            const fileContent = await readFile(filePath, 'utf8');
            const configFromFile = JSON.parse(fileContent);
            return configFromFile;
        }
        const parentDir = path.dirname(dir);
        if (parentDir === dir) {
            return null; // Reached the root directory without finding the file
        }
        return checkDirectoryForFile(parentDir);
    }

    async function getConfigFromFile() {
        const currentDir = process.cwd();
        const configFromDir = await checkDirectoryForFile(currentDir);
        if (configFromDir && configFromDir[key] !== undefined) {
            return configFromDir;
        }
        return null;
    }

    getConfigFromFile().then(config => {
        if (config) {
            value = config[key];
        }
    });

    // Check if the key is a package name and retrieve the value from package.json
    const pkgDir = require('pkg-dir').sync;
    const rootDir = pkgDir(process.cwd());
    if (rootDir) {
        const packageJsonPath = path.join(rootDir, 'package.json');
        if (fs.existsSync(packageJsonPath)) {
            const packageJsonContent = fs.readFileSync(packageJsonPath, 'utf8');
            const packageConfig = JSON.parse(packageJsonContent);
            value = packageConfig[key];
        }
    }

    // Set the value in the configuration object for future reference
    config[key] = value;

    return value;
}
