function calculateBufferLength(buffer, repeat, options) {
    const { groupSeparator, radixPoint } = options;

    // Escape special characters in options
    const escapedGroupSeparator = escapeRegex(groupSeparator);
    const escapedRadixPoint = escapeRegex(radixPoint);

    // Calculate the length of the buffer considering repeat and options
    let totalLength = 0;
    let groupOffset = 0;

    for (let i = 0; i < repeat; i++) {
        const segment = buffer.slice(totalLength, totalLength + buffer.length - groupOffset);
        const escapedSegment = segment.toString().replace(new RegExp(`\\${escapedGroupSeparator}`, 'g'), '');
        const lengthWithoutGroups = escapedSegment.length;

        // Calculate the number of digits after the radix point
        const digitsAfterRadixPoint = (escapedSegment.match(new RegExp(`\\${escapedRadixPoint}(\\d+)`)) || [])[1]?.length || 0;

        totalLength += lengthWithoutGroups + digitsAfterRadixPoint;
    }

    return { calculatedLength: totalLength, groupOffset };
}

function escapeRegex(str) {
    return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); // $& means the whole matched string
}
