const fs = require('fs');
const path = require('path');
const less = require('less');

function compileLessFile(filePath) {
  const fileContent = fs.readFileSync(filePath, 'utf-8');
  return new Promise((resolve, reject) => {
    less.render(fileContent, (err, output) => {
      if (err) {
        reject(err);
      } else {
        resolve(output.css);
      }
    });
  });
}

function searchDirectoryForLessFiles(dirPath) {
  const compiledCss = {};

  function recursiveSearch(currentDir) {
    const files = fs.readdirSync(currentDir);
    files.forEach((file) => {
      const filePath = path.join(currentDir, file);
      if (fs.lstatSync(filePath).isDirectory()) {
        // Skip directories
        return;
      }
      if (path.extname(file) === '.less') {
        compileLessFile(filePath).then((cssContent) => {
          compiledCss[`${path.basename(filePath, '.less')}.css`] = filePath;
        }).catch((err) => {
          console.error(`Error compiling ${filePath}:`, err);
        });
      }
    });
  }

  recursiveSearch(dirPath);
  return compiledCss;
}

