// Function to delete a file
function deleteFile(filePath) {
  try {
    fs.unlinkSync(filePath);
    console.log(`Deleted file: ${filePath}`);
  } catch (err) {
    console.error(`Error deleting file: ${filePath}`, err);
  }
}

// Function to insert text into a file
function insertTextIntoFile(filePath, searchText, replaceText) {
  try {
    let data = fs.readFileSync(filePath, 'utf8');
    const updatedData = data.replace(searchText, replaceText);
    fs.writeFileSync(filePath, updatedData, 'utf8');
    console.log(`Updated file: ${filePath}`);
  } catch (err) {
    console.error(`Error updating file: ${filePath}`, err);
  }
}

// Function to compile Sass to CSS
function compileSassToCss(inputPath, outputPath) {
  try {
    const result = sass.compileFile(inputPath);
    fs.writeFileSync(outputPath, result.css, 'utf8');
    console.log(`Compiled Sass to CSS: ${outputPath}`);
  } catch (err) {
    console.error(`Error compiling Sass to CSS: ${outputPath}`, err);
  }
}

// Function to compile TypeScript to JavaScript
function compileTypeScriptToJs(inputPath, outputPath) {
  try {
    const tsResult = typescript.transpileModule(fs.readFileSync(inputPath, 'utf8'), {
      compilerOptions: { module: typescript.ModuleKind.CommonJS }
    });
    fs.writeFileSync(outputPath, tsResult.outputText, 'utf8');
    console.log(`Compiled TypeScript to JavaScript: ${outputPath}`);
  } catch (err) {
    console.error(`Error compiling TypeScript to JavaScript: ${outputPath}`, err);
  }
}

// Function to concatenate files
function concatenateFiles(files, outputFile) {
  try {
    const content = files.map(file => fs.readFileSync(file, 'utf8')).join('');
    fs.writeFileSync(outputFile, content, 'utf8');
    console.log(`Concatenated files into: ${outputFile}`);
  } catch (err) {
    console.error(`Error concatenating files: ${outputFile}`, err);
  }
}

