function generateRandomStar(canvas) {
  const ctx = canvas.getContext('2d');

  // Generate random position and radius
  const posX = Math.random() * canvas.width;
  const posY = Math.random() * canvas.height;
  const radius = Math.random() * 50 + 10; // Radius between 10 and 60

  // Generate random velocity (for movement)
  const velX = (Math.random() - 0.5) * 2; // Velocity between -1 and 1 in both directions
  const velY = (Math.random() - 0.5) * 2;

  function drawStar() {
    ctx.beginPath();
    for (let i = 0; i < 5; i++) {
      const angle = Math.PI / 2 + i * Math.PI / 2.5;
      const x = posX + radius * Math.cos(angle);
      const y = posY + radius * Math.sin(angle);
      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    }
    ctx.closePath();
    ctx.fillStyle = 'yellow'; // Random color would be better here
    ctx.fill();
  }

  function updatePosition() {
    posX += velX;
    posY += velY;

    if (posX < 0 || posX > canvas.width) {
      velX = -velX;
    }
    if (posY < 0 || posY > canvas.height) {
      velY = -velY;
    }
  }

  function animate() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawStar();
    updatePosition();
    requestAnimationFrame(animate);
  }

  animate();
}
