function loadDataFromFile(filePath) {
  return new Promise((resolve, reject) => {
    fs.readFile(filePath, 'utf8', (err, data) => {
      if (err) {
        reject(`Error reading file ${filePath}: ${err}`);
      } else {
        resolve(data);
      }
    });
  });
}

function loadDataFromMultipleFiles(filePaths) {
  const promises = filePaths.map(filePath => loadDataFromFile(filePath));
  return Promise.all(promises)
    .then(dataArray => {
      const result = {};
      filePaths.forEach((filePath, index) => {
        result[filePath] = dataArray[index];
      });
      return result;
    })
    .catch(err => {
      console.error(`Error loading data from files: ${err}`);
      throw err;
    });
}

