function reformatString(str, separator) {
    let result = '';
    let period = false;
    for (let i = 0; i < str.length; i++) {
        let char = str[i];
        if (char === '.') {
            period = true;
            result += char;
        } else if (/\d/.test(char)) {
            result += char;
        } else if (period) {
            // Remove trailing zeros after the decimal point
            while (result.length > 0 && result[result.length - 1] === '0') {
                result = result.slice(0, -1);
            }
            if (result.length > 0 && result[result.length - 1] === '.') {
                result = result.slice(0, -1); // Handle case that number is .000
                if (!/\d/.test(result[result.length - 1])) {
                    result += '0';
                }
            }
            period = false;
            result += char;
        } else {
            period = false;
            result += char;
        }
    }
    // Insert the separator every three digits from the end
    let parts = result.split('.');
    if (parts.length > 1) {
        let integerPart = parts[0];
        let decimalPart = parts[1];
        integerPart = integerPart.replace(/\B(?=(\d{3})+(?!\d))/g, separator);
        result = integerPart + '.' + decimalPart;
    } else {
        result = result.replace(/\B(?=(\d{3})+(?!\d))/g, separator);
    }
    return result;
}
