function generateUUIDv4() {
    const hexDigits = '0123456789abcdef';

    function randomHex() {
        return Math.floor(Math.random() * 16).toString(16);
    }

    let uuid = '';
    for (let i = 0; i < 36; i++) {
        if ([8, 13, 18, 23].includes(i)) {
            uuid += '-';
        } else if (i === 14) {
            uuid += '4'; // Version 4
        } else if ([19, 24, 29, 34].includes(i)) {
            uuid += hexDigits[Math.floor(Math.random() * 4)]; // Variant bits (8, 9, A, B)
        } else {
            uuid += randomHex();
        }
    }

    return uuid;
}
