const tls = require('tls');
const fs = require('fs');

const port = 12345;
const serverOptions = {
    key: fs.readFileSync('path/to/server-key.pem'),
    cert: fs.readFileSync('path/to/server-cert.pem')
};

const server = tls.createServer(serverOptions, (socket) => {
    socket.setEncoding('utf8');

    // Verify client certificate
    socket.on('secure', () => {
        const peerCert = socket.getPeerCertificate();
        if (!peerCert || !peerCert.subject) {
            return socket.emit('error', new Error('Invalid client certificate'), 'CERTIFICATE_VERIFY_FAILED');
        }
    });

    // Handle data from the client
    socket.on('data', (data) => {
        console.log(`Received data: ${data}`);
    });

    // Handle connection close
    socket.on('close', () => {
        console.log('Client disconnected');
    });
});

server.listen(port, () => {
    console.log(`Server listening on port ${port}`);
});

// Emit an error event with a specific error code if the certificate verification fails
server.on('error', (err) => {
    if (err.code === 'CERTIFICATE_VERIFY_FAILED') {
        console.error(err);
    } else {
        console.error(`Server error: ${err}`);
    }
});
