def escape_characters(text, character_map):
    import re
    pattern = re.compile(r'[' + ''.join(re.escape(key) for key in character_map.keys()) + r']')
    return pattern.sub(lambda match: character_map[match.group()], text)

def unescape_characters(text, character_map):
