function evaluateFunctions(functions) {
  const results = [];
  const memoizedResults = {};

  function memoizeResult(funcName, args, result) {
    memoizedResults[`${funcName}-${JSON.stringify(args)}`] = result;
  }

  for (const [func, args] of functions) {
    const funcName = func.name || 'anonymous';
    const key = `${funcName}-${JSON.stringify(args)}`;

    if (memoizedResults[key]) {
      results.push(memoizedResults[key]);
    } else {
      try {
        const result = func(...args);
        memoizeResult(funcName, args, result);
        results.push(result);
      } catch (error) {
        console.error(`Error evaluating function ${funcName}:`, error);
        results.push(undefined);
      }
    }
  }

  return results;
}
