const Logger = require('logger');

function uploadFile(url) {
    return new Promise((resolve, reject) => {
        try {
            const fileUploader = new FileUploader({ url });

            fileUploader.on('success', (uploadedFileUrl) => {
                Logger.info(`File uploaded successfully: ${uploadedFileUrl}`);
                resolve(uploadedFileUrl);
            });

            fileUploader.on('error', (err) => {
                Logger.error(`Failed to upload file: ${err.message}`);
                reject(err);
            });

            fileUploader.upload();
        } catch (error) {
            Logger.error(`An error occurred: ${error.message}`);
            reject(error);
        }
    });
}
