function checkElementVisibilityAndExecuteFunction(element, executeFunction) {
    // Check if the element is visible
    if (element.offsetWidth > 0 && element.offsetHeight > 0) {
        // If the element is an iframe, update its src and send a message to mute the volume
        if (element.tagName === 'IFRAME') {
            const updatedSrc = new URL(element.src);
            updatedSrc.searchParams.set('enableApi', 'true');
            element.src = updatedSrc.toString();

            // Send a message to the contentWindow of the iframe to mute the volume
            element.contentWindow.postMessage('muteVolume', '*');

            // Set the width and height of the iframe to empty strings
            element.width = '';
            element.height = '';

            // Retrieve the dimensions of the iframe
            const { width, height } = element;

            // Add a load event listener to the iframe
            element.addEventListener('load', () => {
                executeFunction();
            });
        } else {
            // If not an iframe, just execute the function
            executeFunction();
        }
    }
