function parseCSSSelector(selector) {
    // Remove leading and trailing whitespace
    selector = selector.trim();
    
    // Regular expression to match combinators, simple selectors, and attribute tests
    const regex = /([\s>+~]+)?((?:[^\s>+~]+(?:\([^)]*\))?)*)/g;
    let matches = [];
    let match;
    
    while ((match = regex.exec(selector)) !== null) {
        if (match[1]) {
            // Combinator found, add to matches array
            matches.push({ type: 'combinator', value: match[1] });
        }
        if (match[2]) {
            // Simple selector or attribute test found, add to matches array
            let simpleSelectors = [];
            let attrTestRegex = /(?:[^\s>+~]+)(?:\([^)]*\))?/g;
            let attrMatch;
            
            while ((attrMatch = attrTestRegex.exec(match[2])) !== null) {
                simpleSelectors.push({ type: 'simpleSelector', value: attrMatch[0] });
            }
            
            matches = matches.concat(simpleSelectors);
        }
    }
    
    return matches;
}
