function processStringWithRegex(input, regexHandlers) {
    for (let [regex, handler] of regexHandlers) {
        let match = input.match(regex);
        if (match) {
            if (typeof handler === 'function') {
                return handler(match);
            } else if (typeof handler === 'string') {
                try {
                    return eval(handler);
                } catch (e) {
                    console.error("Error executing handler:", e);
                    return input;
                }
            }
        }
    }
    return input;
}
