function traverseDOM(node, selectorRegex) {
    let matches = [];
    
    function recurse(currentNode) {
        if (currentNode.nodeType === Node.ELEMENT_NODE) {
            const classNameMatch = currentNode.className.match(selectorRegex);
            const idMatch = currentNode.id && currentNode.id.match(selectorRegex);
            
            if (classNameMatch || idMatch) {
                matches.push(currentNode);
            }
        }
        
        for (let child of currentNode.childNodes) {
            recurse(child);
        }
    }
    
    recurse(node);
    return matches;
}
