 * @returns {Promise<Buffer[]>} - A promise that resolves with an array of converted video frame buffers.
 */
function convertVideoFrames(frames, outputFormat) {
  return new Promise((resolve, reject) => {
    const convertedFrames = [];
    ffmpeg()
      .input(frames[0].toString('base64')) // Convert buffer to base64 string for ffmpeg input
      .outputOptions(['-f', outputFormat])
      .on('error', (err) => {
        reject(`Error converting video frames: ${err}`);
      })
      .on('end', () => {
        resolve(convertedFrames);
      })
      .pipe((stream, chunk) => {
        convertedFrames.push(Buffer.from(chunk, 'base64')); // Convert base64 string back to buffer
      });
  });
}

