def hash_value(item):
    import hashlib
    import json

    # Counter for new objects encountered
    object_counter = {}

    def get_hash(obj):
        if isinstance(obj, dict):
            obj_str = json.dumps(obj, sort_keys=True)
        elif hasattr(obj, '__dict__'):
            obj_str = json.dumps(obj.__dict__, sort_keys=True)
        else:
            obj_str = str(obj)

        # Increment the counter for new objects
        if obj not in object_counter:
            object_counter[obj] = 0
        object_counter[obj] += 1

        # Create a hash of the string representation
        return hashlib.sha256(obj_str.encode()).hexdigest()

    return get_hash(item)
