function createCachedFunction(code) {
  const cache = new Map();
  
  return function executeInScope(s, k) {
    const key = JSON.stringify([s, k]);
    
    if (cache.has(key)) {
      return cache.get(key);
    }
    
    // Create a new function with the given scope and locals
    const func = Function('scope', 'locals', `with (scope) { ${code} };`);
    
    try {
      const result = func.call(s, k);
      
      if (result && typeof result.then === 'function') {
        return cache.set(key, result).get(key);
      } else {
        return result;
      }
    } catch (error) {
      console.error('Error executing code:', error);
      throw error;
    }
  };
}
