def co_routine_system(coroutines, token):
    while coroutines:
        current_coroutine = coroutines.pop(0)
        try:
            result = next(current_coroutine)
            if result is not None:
                return result
        except StopIteration as e:
            continue
        except Exception as e:
            # Handle any other exceptions that might occur during execution
            print(f"An error occurred: {e}")
            break
        finally:
            if token in coroutines:
                coroutines.append(current_coroutine)
    return "done"
