function listenForIframeEvent() {
    window.addEventListener('message', function(event) {
        const iframe = document.querySelector('iframe[src]');
        if (!iframe) return;

        const src = iframe.getAttribute('src');
        const autoplay = iframe.getAttribute('data-autoplay');
        let messageToSend;

        if (src && autoplay) {
            if (src.includes('video') && autoplay === 'true') {
                messageToSend = src.includes('playVideo') || src.includes('play') ? 'playVideo' : 'play';
            } else if (src.includes('slide')) {
                messageToSend = 'slide:start';
            }
        }

        if (messageToSend) {
            iframe.contentWindow.postMessage(messageToSend, '*');
        }
    });
}
