            content = content.replace(new RegExp(version, 'g'), process.env.npm_package_version || 'unknown');
        }

        if (content.includes(archPlaceholder)) {
            content = content.replace(new RegExp(archPlaceholder, 'g'), arch);
        }

        // Write the modified contents to destFilename
