def parse_midi_meta_events(data):
    import struct

    def read_bytes(stream, length):
        data = stream.read(length)
        if len(data) != length:
            raise ValueError("Expected {} bytes but got {}".format(length, len(data)))
        return data

    def parse_time_signature(stream):
        numerator = read_bytes(stream, 1)[0]
        denominator = 2 ** (read_bytes(stream, 1)[0] - 6)
        metronome = read_bytes(stream, 1)[0]
        thirtyseconds = read_bytes(stream, 1)[0]
        return {
            "subtype": "timeSignature",
            "numerator": numerator,
            "denominator": denominator,
            "metronome": metronome,
            "thirtyseconds": thirtyseconds
        }

    def parse_key_signature(stream):
        key = read_bytes(stream, 1)[0]
        scale = read_bytes(stream, 1)[0]
        return {
            "subtype": "keySignature",
            "key": key,
            "scale": scale
        }

    def parse_sequencer_specific(stream):
        data = bytearray(read_bytes(stream, len(data)))
        return {
            "subtype": "sequencerSpecific",
            "data": data
        }

    stream = io.BytesIO(data)
    meta_events = []

    while True:
        try:
            event_type = read_bytes(stream, 1)[0]
            if event_type == 0xFF:
                raise ValueError("Invalid MIDI data")

            length = read_bytes(stream, 1)[0]
            if event_type == 0x58:  # timeSignature
                meta_events.append(parse_time_signature(stream))
            elif event_type == 0x59:  # keySignature
                meta_events.append(parse_key_signature(stream))
            elif event_type == 0x7F:  # sequencerSpecific
                meta_events.append(parse_sequencer_specific(stream))
            else:
                logging.error("Unknown meta event type: {}".format(event_type))
                meta_events.append({"subtype": "unknown"})

            stream.seek(length, io.SEEK_CUR)
        except EOFError:
            break

    return meta_events
