function uniqueTokens(str1, str2) {
    const tokens1 = str1.split(' ');
    const tokens2 = str2.split(' ');
    let result = [];

    for (let token of tokens1) {
        let isUnique = true;
        for (let t of tokens2) {
            if (token === t) {
                isUnique = false;
                break;
            }
        }
        if (isUnique) {
            result.push(token);
        }
    }

    return result.join(' ');
}
