function encryptAndUploadBinaryFile($filePath, $password) {
    // Read the binary file content
    $fileContent = file_get_contents($filePath);

    // Encrypt the file content using the given password
    $encryptedContent = openssl_encrypt($fileContent, 'AES-256-CBC', $password, OPENSSL_RAW_DATA);

