    $conn = new mysqli("localhost", "username", "password", "database_name");

    if ($conn->connect_error) {
        die("Connection failed: " . $conn->connect_error);
    }

    // Prepare and execute a query to check the old password
    $stmt = $conn->prepare("SELECT * FROM users WHERE username = ?");
    $stmt->bind_param("s", $username);
    $stmt->execute();
    $result = $stmt->get_result();

    if ($result->num_rows > 0) {
        $row = $result->fetch_assoc();
        $storedPasswordHash = $row["password"];
        $storedSalt = $row["salt"];

        // Verify the old password
        if (hash('sha256', $oldPassword . $storedSalt) === $storedPasswordHash) {
            // Check if new passwords match
            if ($newPassword === $newPasswordConfirmation) {
                // Generate a new salt and hash the new password using PBKDF2
                $newSalt = bin2hex(random_bytes(16));
                $newPasswordHash = hash('sha256', $newPassword . $newSalt);

                // Prepare and execute a query to update the user's password, salt, and username in the database
