<?php
function validate_signature($token, $timestamp, $nonce, $provided_signature) {
    // Sort the array of strings using the SORT_STRING rule
    $array = [$token, $timestamp, $nonce];
    sort($array, SORT_STRING);

    // Implode the array into a single string
    $joined_string = implode('', $array);

    // Hash the resulting string using sha1
    $hashed_string = sha1($joined_string);

    // Compare the resulting hash with the provided signature
    return $hashed_string === $provided_signature;
}
