function sanitizeAndQueryLDAP($input) {
    // Sanitize user input
    $sanitizedInput = filter_var($input, FILTER_SANITIZE_STRING);

    // Connect to LDAP server
    $ldapServer = "ldaps://your-ldap-server.com";
    $ldapPort = 636;
    $ldapConnection = ldap_connect($ldapServer, $ldapPort);

    if (!$ldapConnection) {
        die("Could not connect to LDAP server");
    }

    // Bind to the LDAP server
    $ldapBind = @ldap_bind($ldapConnection);

    if (!$ldapBind) {
        die("Could not bind to LDAP server");
    }

    // Construct and execute the query
    $baseDn = "dc=example,dc=com";
    $filter = "(cn=$sanitizedInput)";
    $attributes = array("*");

    $searchResult = ldap_search($ldapConnection, $baseDn, $filter, $attributes);

    if (!$searchResult) {
        die("Query failed");
    }

    // Get the entries from the search result
    $entries = ldap_get_entries($ldapConnection, $searchResult);

    // Close the LDAP connection
    ldap_close($ldapConnection);

    return $entries;
}
