function generate_request_signature(Request $request) {
    // Check if user is authenticated
    if ($request->user() && $request->user()->isAuthenticated()) {
        $authIdentifier = $request->user()->getAuthIdentifier();
        return hash('sha1', $authIdentifier);
    }

    // Check if route is available
    if ($request->route()) {
        $domain = $request->getHost();
        $ipAddress = $request->getClientIp();
        $signatureData = $domain . $ipAddress;
        return hash('sha1', $signatureData);
