CREATE FUNCTION create_user(username VARCHAR(255), password VARCHAR(255), email VARCHAR(255)) RETURNS BOOLEAN
BEGIN
    DECLARE escaped_username VARCHAR(255);
    DECLARE escaped_password VARCHAR(255);
    DECLARE escaped_email VARCHAR(255);

    -- Escape bad characters in the username, password, and email
    SET escaped_username = REPLACE(username, "'", "''");
    SET escaped_password = REPLACE(password, "'", "''");
    SET escaped_email = REPLACE(email, "'", "''");

    -- Create a new user in the 'users' table
    INSERT INTO users (username, password, email) VALUES (escaped_username, escaped_password, escaped_email);

    -- Create a new table for the user in the 'kin' database
    SET @user_table_name = CONCAT('kin.', escaped_username, '_table');
    SET @create_table_query = CONCAT('CREATE TABLE ', @user_table_name, ' (id INT AUTO_INCREMENT PRIMARY KEY, data VARCHAR(255));');
    PREPARE create_table FROM @create_table_query;
    EXECUTE create_table;
    DEALLOCATE PREPARE create_table;

    RETURN TRUE;
END //

DELIMITER ;
