use Doctrine\DBAL\DriverManager;
use Symfony\Component\Console\Command\Command;
use Symfony\Component\Console\Input\InputInterface;
use Symfony\Component\Console\Output\OutputInterface;

class CreateDatabaseCommand extends Command
{
    protected function configure()
    {
        $this->setName('database:create')
             ->setDescription('Drop the current database and create a new one based on schema.php');
    }

    protected function execute(InputInterface $input, OutputInterface $output)
    {
        // Load the schema from schema.php
        $schema = include 'path/to/schema.php';

        // Configure Doctrine DBAL connection
        $connectionParams = [
            'dbname' => 'your_database_name',
            'user' => 'your_db_username',
            'password' => 'your_db_password',
            'host' => 'localhost',
            'driver' => 'pdo_mysql',
        ];

        $conn = DriverManager::getConnection($connectionParams);

        // Drop the current database
        try {
            $schemaManager = $conn->getSchemaManager();
            $databaseName = $conn->getDatabase();
            if ($schemaManager->tablesExist($databaseName)) {
                foreach ($schemaManager->listTables() as $table) {
                    $schemaManager->dropTable($table->getName());
                }
            }
        } catch (Exception $e) {
            $output->writeln('Error dropping the current database: ' . $e->getMessage());
            return Command::FAILURE;
        }

        // Create a new database based on the schema
        try {
            foreach ($schema as $table => $columns) {
                $createTable = $conn->getSchemaManager()->createTable($table);
                foreach ($columns as $column => $type) {
                    $createTable->addColumn($column, $type);
                }
                $conn->getSchemaManager()->dropAndCreateTable($createTable);
            }
        } catch (Exception $e) {
            $output->writeln('Error creating the new database: ' . $e->getMessage());
            return Command::FAILURE;
        }

        $output->writeln('Database dropped and created successfully.');
        return Command::SUCCESS;
    }
}
