class MemcachedInitializer {
    private $savePath;
    private $ipAddressMatching;
    private $memcached;

    public function __construct(array $config) {
        $this->savePath = $config['save_path'] ?? null;
        $this->ipAddressMatching = $config['ip_address_matching'] ?? false;

        if ($this->savePath === null) {
            error_log("Save path is not configured.");
            return;
        }

        // Initialize Memcached object
        $this->memcached = new Memcached();

        // Add servers based on the save path
        $servers = explode(',', $this->savePath);
        foreach ($servers as $server) {
            list($ip, $port) = explode(':', trim($server));
            $this->memcached->addServer($ip, $port);
        }

        // Enable IP address matching if enabled
        if ($this->ipAddressMatching) {
            $remoteIp = $_SERVER['REMOTE_ADDR'] ?? '127.0.0.1';
            $this->memcached->setOption(Memcached::OPT_PREFIX_KEY, $remoteIp . ':');
        }
    }
}
