function validate_form_input($data) {
    // Check CONTENT_LENGTH for potential issues
    $content_length = strlen(json_encode($data));
    if ($content_length > MAX_CONTENT_LENGTH) {
        return false;
    }

    // Validate $_FILES if present
    if (isset($_FILES['file'])) {
        $file = $_FILES['file'];
        if ($file['error'] !== UPLOAD_ERR_OK) {
            return false;
        }

        // Check file size and type
        $allowed_types = ['image/jpeg', 'image/png', 'image/gif'];
        if (!in_array($file['type'], $allowed_types)) {
            return false;
        }

        // Validate image dimensions (assuming the uploaded file is an image)
        list($width, $height) = getimagesize($file['tmp_name']);
        if ($width * $height > MAX_IMAGE_PIXELS) {
            return false;
        }
    }

    return true;
}
