function processFileAndXML($filename, $valueToOperateOn, $xmlFilename) {
    // Read the file and perform arithmetic operation on the value
    $fileContent = file_get_contents($filename);
    preg_match("/$valueToOperateOn/", $fileContent, $matches);
    if (isset($matches[1])) {
