function getClientIp() {
    $ip = null;

    // Check for proxy headers
    if (isset($_SERVER['HTTP_CLIENT_IP']) && !empty($_SERVER['HTTP_CLIENT_IP'])) {
        $ip = $_SERVER['HTTP_CLIENT_IP'];
    } elseif (isset($_SERVER['HTTP_X_FORWARDED_FOR']) && !empty($_SERVER['HTTP_X_FORWARDED_FOR'])) {
        $ip = $_SERVER['HTTP_X_FORWARDED_FOR'];
    } elseif (isset($_SERVER['HTTP_X_REAL_IP']) && !empty($_SERVER['HTTP_X_REAL_IP'])) {
        $ip = $_SERVER['HTTP_X_REAL_IP'];
    } elseif (isset($_SERVER['HTTP_PROXY_CLIENT_IP']) && !empty($_SERVER['HTTP_PROXY_CLIENT_IP'])) {
        $ip = $_SERVER['HTTP_PROXY_CLIENT_IP'];
    } elseif (isset($_SERVER['HTTP_WL_PROXY_CLIENT_IP']) && !empty($_SERVER['HTTP_WL_PROXY_CLIENT_IP'])) {
        $ip = $_SERVER['HTTP_WL_PROXY_CLIENT_IP'];
    } else {
        $ip = isset($_SERVER['REMOTE_ADDR']) ? $_SERVER['REMOTE_ADDR'] : null;
    }

    // Validate the IP address
    if ($ip && (filter_var($ip, FILTER_VALIDATE_IP) || preg_match('/^[0-9a-fA-F]{1,4}(:[0-9a-fA-F]{1,4}){7}$/', $ip))) {
        return $ip;
    } else {
        throw new Exception($ip . " is not a valid IP address");
    }
}
