function createRecord($url, $trackId, $userId, $createTime, $createDate, $hour, $site, $shortUrl, $httpClientIp, $httpXForwardedFor, $remoteAddr) {
    try {
        // Connect to the database
        $db = new PDO('mysql:host=localhost;dbname=your_database', 'username', 'password');
        $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

        // Prepare the SQL statement
        $stmt = $db->prepare("SELECT * FROM your_table WHERE url = :url");
        $stmt->execute([':url' => $url]);
        $record = $stmt->fetch(PDO::FETCH_ASSOC);

        if ($record) {
            // Update the existing record
            $views = $record['views'] + 1;
            $updateStmt = $db->prepare("UPDATE your_table SET views = :views WHERE url = :url");
            $updateStmt->execute([':views' => $views, ':url' => $url]);
        } else {
            // Insert a new record
            $insertStmt = $db->prepare(
                "INSERT INTO your_table (url, track_id, user_id, create_time, create_date, hour, site, short_url, http_client_ip, http_x_forwarded_for, remote_addr) 
                 VALUES (:url, :trackId, :userId, :createTime, :createDate, :hour, :site, :shortUrl, :httpClientIp, :httpXForwardedFor, :remoteAddr)"
            );
