                ':shortUrl' => $shortUrl,
                ':httpClientIp' => $httpClientIp,
                ':httpXForwardedFor' => $httpXForwardedFor,
                ':remoteAddr' => $remoteAddr
            ]);
        }

        // Close the database connection
        $db = null;
    } catch (PDOException $e) {
