<?php
function pingback($url) {
    // Check if URL is valid
    if (!filter_var($url, FILTER_VALIDATE_URL)) {
        return "Invalid URL.";
    }

    // Sleep for 1 second
    sleep(1);

    // Get the IP address and user agent of the remote server
    $parsedUrl = parse_url($url);
    $host = $parsedUrl['host'];
    $ip = gethostbyname($host);
    $userAgent = $_SERVER['HTTP_USER_AGENT'] ?? 'PHP-Pingback';

    // Check if the IP address is valid and not a loopback or private address
    if (!filter_var($ip, FILTER_VALIDATE_IP) || ip2long($ip) === false) {
        return "Invalid IP address.";
    }

    // Additional checks for private IPs can be added here if needed

    // Create a new cURL session
    $ch = curl_init();

    // Set the URL and other options
    curl_setopt($ch, CURLOPT_URL, $url);
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_USERAGENT, $userAgent);

    // Execute the request
    $response = curl_exec($ch);

    // Check for cURL errors
    if (curl_errno($ch)) {
        return "cURL error: " . curl_error($ch);
    }

    // Close the cURL session
    curl_close($ch);

    // Additional checks can be added here to ensure the URL is pingback-enabled and hasn't been pinged

    return "Pingback successful.";
}
