      zoom: 8
    });

    locations.forEach(location => {
      const marker = new MarkerWithLabel({
        position: location.address,
        map: map,
        labelContent: location.name,
        labelAnchor: new google.maps.Point(15, -20),
        labelClass: "custom-label", // CSS class for the label
        title: location.description
      });
    });

    // Initialize Masonry layout
    const masonry = new Masonry('#map', {
      itemSelector: '.marker',
      columnWidth: 200,
      gutter: 10
    });
  }
