function processLeaseRecords($leaseRecords, $sortField, $filename) {
    // Sort the lease records based on the specified field
    usort($leaseRecords, function($a, $b) use ($sortField) {
        if (!isset($a[$sortField]) && !isset($b[$sortField])) {
            return 0;
        } elseif (!isset($a[$sortField])) {
            return -1;
        } elseif (!isset($b[$sortField])) {
            return 1;
        } else {
            return strcmp($a[$sortField], $b[$sortField]);
        }
    });

    // Write the sorted list to a file
    $file = fopen($filename, 'w');
    foreach ($leaseRecords as $record) {
        fwrite($file, json_encode($record) . "\n");
    }
    fclose($file);

    // Restart a service (example: assuming restartService is a function that restarts the service)
    restartService();
}

