// Function to update user password in MySQL database
function updateUserPassword($userId, $newPassword) {
    // Connect to the database (replace with your own credentials)
    $connection = mysqli_connect("localhost", "username", "password", "database");

    if (!$connection) {
        die("Connection failed: " . mysqli_connect_error());
    }

    // Hash the new password using password_hash() function
    $hashedPassword = password_hash($newPassword, PASSWORD_DEFAULT);

    // Prepare and execute the SQL query to update the user's password
    $query = "UPDATE users SET password_digest = ? WHERE user_id = ?";
    $stmt = mysqli_prepare($connection, $query);
    mysqli_stmt_bind_param($stmt, "si", $hashedPassword, $userId);
    mysqli_stmt_execute($stmt);

    // Check if the query was successful and output appropriate message
    if (mysqli_stmt_affected_rows($stmt) > 0) {
        echo "Password updated successfully!";
    } else {
        echo "Failed to update password.";
    }

    // Close the statement and connection
    mysqli_stmt_close($stmt);
    mysqli_close($connection);
}

