function processFormSubmission($formData, $url) {
    // Assuming you have an API endpoint to create a new comment
    $apiUrl = "https://your-api-endpoint.com/create-comment";

    // Prepare the data to be sent to the API
    $data = [
        'name' => $formData['name'],
        'email' => $formData['email'],
        'comment' => $formData['comment']
    ];

    // Initialize cURL session
    $ch = curl_init($apiUrl);

    // Set the options for the cURL session
    curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
    curl_setopt($ch, CURLOPT_POST, true);
    curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($data));

    // Execute the cURL session and get the response
    $response = curl_exec($ch);

    // Check for any errors in the cURL execution
    if (curl_errno($ch)) {
        $errorMessage = "cURL Error: " . curl_error($ch);
        $_SESSION['error'] = $errorMessage;
    } else {
        // Parse the JSON response from the API
        $responseData = json_decode($response, true);

        if (json_last_error() === JSON_ERROR_NONE) {
            // Store the result and any error message in session variables
            $_SESSION['result'] = $responseData;
            $_SESSION['error'] = null;
        } else {
            $errorMessage = "JSON Error: " . json_last_error_msg();
            $_SESSION['error'] = $errorMessage;
        }
    }

    // Close the cURL session
    curl_close($ch);

    // Redirect to the specified URL
    header("Location: $url");
    exit();
}
