class JSONParser:
    _factories: Dict[str, Callable[[], 'JSONParser']] = {}

    @classmethod
    def from_json(cls, json_str: str) -> 'JSONParser':
        data = json.loads(json_str)
        factory_id = data.get('_factory_id')
        if not factory_id or factory_id not in cls._factories:
