import sys

def sample_population(population, num_samples=1, with_replacement=False, max_stddev=2):
    if num_samples < 0:
        raise ValueError("Number of samples must be non-negative")
    if not population:
        return []

    # Calculate the maximum number of samples allowed based on population size and standard deviations
    max_samples = min(len(population), int(sys.maxsize ** 0.5 * max_stddev))
    num_samples = min(num_samples, max_samples)

    if num_samples == 0:
        return []

    # Shuffle the population
    random.shuffle(population)

    # Draw samples with or without replacement
    if with_replacement:
        return [random.choice(population) for _ in range(num_samples)]
    else:
        return random.sample(population, num_samples)
