import feedparser
import random
import time
from urllib.parse import urlparse

def check_feed(url):
    retries = 3
    while retries > 0:
        try:
            parsed_url = urlparse(url)
            if not parsed_url.scheme:
                raise ValueError("URL scheme is missing")
            
            feed = feedparser.parse(url)
            if feed.bozo == 0 and 'title' in feed.feed:
                print(f"Valid feed found for URL: {url}")
                print(f"Feed title: {feed.feed.title}")
                return True
            else:
                raise ValueError("Invalid feed data")
        except Exception as e:
            retries -= 1
            if retries == 0:
                print(f"Failed to parse URL after multiple attempts: {url}. Error: {e}")
                return False
            wait_time = random.uniform(1, 10)
            time.sleep(wait_time)
            continue

def main():
    urls = [
