import json

class Quantity:
    def __init__(self, amount, unit, lower_bound=None, upper_bound=None):
        self.amount = amount
        self.unit = unit
        self.lower_bound = lower_bound
        self.upper_bound = upper_bound

    @staticmethod
    def from_json(json_data):
        data = json.loads(json_data)
        return Quantity(data['amount'], data['unit'], data.get('lower_bound'), data.get('upper_bound'))

    def to_json(self):
        return json.dumps({
            'amount': self.amount,
            'unit': self.unit,
            'lower_bound': self.lower_bound,
            'upper_bound': self.upper_bound
        })

    def __str__(self):
        if self.lower_bound is None and self.upper_bound is None:
            return f"{self.amount} {self.unit}"
        elif self.lower_bound == self.upper_bound:
            return f"{self.amount} ± {self.lower_bound} {self.unit}"
