import gzip
import re

def gff3_to_gtf(gff3_file, dialect='default'):
    def parse_line(line):
        fields = line.strip().split('\t')
        return {
            'seqname': fields[0],
            'source': fields[1],
            'feature': fields[2],
            'start': int(fields[3]),
            'end': int(fields[4]),
            'score': fields[5] if len(fields) > 5 else '.',
            'strand': fields[6] if len(fields) > 6 else '.',
            'frame': fields[7] if len(fields) > 7 else '.',
            'attributes': fields[8]
        }

    def parse_attributes(attr_str):
        attributes = {}
        for attr in re.split('; | ', attr_str):
            if '=' in attr:
                key, value = attr.split('=')
                attributes[key] = value
        return attributes

    def format_attributes(attr_dict):
        items = []
        for key, value in attr_dict.items():
            items.append(f'{key} "{value}";')
        return ' '.join(items)

    gtf_lines = []
    with gzip.open(gff3_file, 'rt') if gff3_file.endswith('.gz') else open(gff3_file, 'r') as f:
        for line in f:
            if not line.startswith('#'):
                record = parse_line(line)
                attributes = parse_attributes(record['attributes'])
                gtf_line = (f"{record['seqname']}\t{dialect}\t{record['feature']}"
                            f"\t{record['start']}\t{record['end']}\t{record['score']}"
                            f"\t{record['strand']}\t{record['frame']}\t"
                            f"{format_attributes(attributes)}")
                gtf_lines.append(gtf_line)
    return '\n'.join(gtf_lines)

