import os
import signal
import time

def terminate_process(pid, initial_sleep=1, max_sleep=30, sleep_factor=2):
    if not os.path.exists(f"/proc/{pid}"):
        return -1  # Process is not running

    attempt = 0
    while True:
        try:
            os.kill(pid, signal.SIGTERM)
            start_time = time.time()
            while time.time() - start_time < max_sleep:
                if not os.path.exists(f"/proc/{pid}"):
                    return 0  # Process terminated gracefully
                time.sleep(min(initial_sleep * (sleep_factor ** attempt), max_sleep))
            break
        except OSError as e:
            if e.errno == os.errno.ESRCH:
                return 0  # Process has already terminated
            raise
        except Exception as ex:
            print(f"An error occurred: {ex}")
            break
        attempt += 1

    return -1  # Failed to terminate process gracefully

# Example usage:
# result = terminate_process(1234)
# print(result)
