import numpy as np
from scipy import stats

def percentile_function(distribution_name, values, **kwargs):
    try:
        distribution = getattr(stats, distribution_name)
    except AttributeError:
        raise ValueError(f"Distribution '{distribution_name}' not found.")

    if not hasattr(distribution, 'ppf'):
        raise NotImplementedError(f"Percentile function (ppf) is not implemented for the {distribution_name} distribution.")

    # Default parameters for ppf calculation
    default_parameters = {'loc': 0, 'scale': 1}
    params = {**default_parameters, **kwargs}

    try:
        return distribution.ppf(np.array(values) / 100, **params)
    except Exception as e:
        raise ValueError(f"Error calculating percentile function for {distribution_name}: {e}")

# Example usage:
# ppfs = percentile_function('norm', [25, 50, 75], loc=0, scale=1)
