import subprocess
import re
from collections import Counter

def extract_text_from_pdf(pdf_file):
    try:
        result = subprocess.run(['pdftotext', pdf_file, '-'], check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        return result.stdout.decode('utf-8')
    except subprocess.CalledProcessError as e:
        print(f"Error extracting text from PDF: {e.stderr.decode('utf-8')}")
        return None

def tokenize_text(text):
    tokens = re.findall(r'\b\w+\b', text)
    return tokens

def create_bag_of_words(tokens):
    bag_of_words = Counter(tokens)
    return dict(bag_of_words)

def write_bag_of_words_to_file(bag_of_words, output_file):
    with open(output_file, 'w') as f:
        for word, count in bag_of_words.items():
            f.write(f"{word} {count}\n")

def main(pdf_file, output_file):
    text = extract_text_from_pdf(pdf_file)
    if text is None:
        return

    tokens = tokenize_text(text)
    bag_of_words = create_bag_of_words(tokens)
    write_bag_of_words_to_file(bag_of_words, output_file)

if __name__ == "__main__":
    import sys
    if len(sys.argv) != 3:
        print("Usage: python script.py <input_pdf> <output_txt>")
        sys.exit(1)

    pdf_file = sys.argv[1]
    output_file = sys.argv[2]
    main(pdf_file, output_file)
