import shelve

class DataFilter:
    def __init__(self, filename):
        self.filename = filename
        self.data_store = None

    def record(self, data, data_type):
        if not self.data_store:
            self.data_store = shelve.open(self.filename)

        key = f"_{len(self.data_store)}"
        self.data_store[key] = (data, data_type)

    def playback(self):
        if not self.data_store:
            self.data_store = shelve.open(self.filename)

        for key in self.data_store:
            data, data_type = self.data_store[key]
            yield (data, data_type)

    def close(self):
        if self.data_store:
            self.data_store.close()
