import warnings
from functools import wraps

def deprecate_attribute(new_name):
    def decorator(cls):
        original_get = cls.__dict__.get(new_name)
        if original_get is None or not callable(original_get):
            raise ValueError(f"The attribute {new_name} must be a callable.")

        @wraps(original_get)
        def getter(self):
            warnings.warn(f"'{cls.__name__}.{new_name}' is deprecated, use '{cls.__name__}.{new_name}' instead", DeprecationWarning, stacklevel=2)
            return original_get(self)

        @wraps(original_get)
        def setter(self, value):
            warnings.warn(f"'{cls.__name__}.{new_name}' is deprecated, use '{cls.__name__}.{new_name}' instead", DeprecationWarning, stacklevel=2)
            return original_get(self, value)

        setattr(cls, new_name, property(getter, setter))
        return cls
    return decorator
