CREATE FUNCTION create_and_insert() RETURNS INT
BEGIN
    DECLARE table_name VARCHAR(255) DEFAULT 'my_table';
    DECLARE lock_name VARCHAR(255) DEFAULT 'my_lock';

    -- Create a table with an auto-incrementing primary key
    CREATE TABLE my_table (
        id INT AUTO_INCREMENT PRIMARY KEY,
        name VARCHAR(255) UNIQUE
    );

    -- Insert two rows with unique names
    INSERT INTO my_table (name) VALUES ('Alice');
    INSERT INTO my_table (name) VALUES ('Bob');

    -- Acquire a write lock on the table using the given lock name
    LOCK TABLES my_table WRITE;

    -- Insert a third row with a name that is not unique
    BEGIN;
    SAVEPOINT before_insert;
    INSERT INTO my_table (name) VALUES ('Bob');
    RELEASE SAVEPOINT before_insert;
    COMMIT;

    -- Release the lock
    UNLOCK TABLES;

    -- Return the number of rows affected by the insert operations
    RETURN ROW_COUNT();
END;
