def modify_attributes(obj):
    import inspect

    # Get all methods of the object
    methods = [getattr(obj, name) for name in dir(obj) if callable(getattr(obj, name))]

    for method in methods:
        if method.__name__.startswith('Get'):
            prefix_length = len('Get')
            attr_name = method.__name__[prefix_length:]

            # Check if there is a corresponding 'Set' method
            set_method_name = 'Set' + attr_name
            if hasattr(obj, set_method_name):
                set_method = getattr(obj, set_method_name)

                def new_set_method(self, value):
                    self.__dict__[attr_name] = value
                    return set_method(self, value)

                # Replace the 'Set' method with the new one
                setattr(obj, set_method_name, new_set_method)
