    def search_images_in_bundle(self, bundle_name, image_types):
        cache_file_path = '/path/to/cache/file.json'  # Update this path as needed

        if not os.path.exists(cache_file_path):
            # Create a new dictionary with all possible image types
            cache_data = {bundle_name: image_types}
            with open(cache_file_path, 'w') as file:
                json.dump(cache_data, file)
        else:
            # Read the existing cache file
            with open(cache_file_path, 'r') as file:
                cache_data = json.load(file)

            if bundle_name not in cache_data:
                cache_data[bundle_name] = image_types
                with open(cache_file_path, 'w') as file:
                    json.dump(cache_data, file)

        # Use BundleContext to find entries in the bundle's root directory that match the given image types
        images_found = []
        for img_type in image_types:
            search_path = os.path.join('/path/to/bundle', bundle_name, f'*{img_type}')
            for file in glob.glob(search_path):
                if os.path.isfile(file):
                    images_found.append(file)

        return images_found
