import subprocess

def checkout_package(repository_url):
    """Check out a package from a Subversion repository and return the revision number."""
    try:
        result = subprocess.run(['svn', 'checkout', repository_url], capture_output=True, text=True)
        if result.returncode != 0:
            raise Exception(f"Failed to checkout package: {result.stderr}")

        # Assuming the working copy is created in the current directory after checkout
        revision = subprocess.run(['svn', 'info'], capture_output=True, text=True).stdout
        for line in revision.split('\n'):
            if line.startswith('Revision:'):
                return int(line.split(':')[1].strip())
    except Exception as e:
        print(f"Error occurred: {e}")
        raise

