def retrieve_value_from_remote_server():
    command = "ssh user@remote-server 'some_command'"

    try:
        result = subprocess.run(command, shell=True, check=True, capture_output=True, text=True)
        output = result.stdout

        # Define a regular expression to extract the desired value
        pattern = r'desired_value_pattern'
        match = re.search(pattern, output)

        if match:
            extracted_value = match.group(1)

            # Check that the extracted value matches the expected format
            if re.match(r'expected_format', extracted_value):
                return extracted_value
            else:
                raise ValueError("Extracted value does not match the expected format")
