import subprocess
from io import TextIOWrapper

def execute_command(command: str, mode: str = 'r') -> TextIOWrapper:
    """
    Execute a command and return its output as a TextIOWrapper object.

    :param command: The command to execute.
    :param mode: The mode in which the file should be opened ('r' for read, 'w' for write). Default is 'r'.
    :return: A TextIOWrapper object containing the output of the command.
    """
    result = subprocess.run(command, shell=True, capture_output=True, text=True)

    if mode == 'r':
        return TextIOWrapper(result.stdout, encoding='utf-8')
    elif mode == 'w':
        return TextIOWrapper(result.stderr, encoding='utf-8')
    else:
        raise ValueError("Invalid mode specified. Use 'r' for read or 'w' for write.")
