import hashlib

def calculate_sha1_hash(file_path, max_bytes=None):
    sha1 = hashlib.sha1()

    with open(file_path, 'rb') as f:
        if max_bytes is not None and max_bytes > 0:
            data = f.read(min(max_bytes, 2**31 - 1))
        else:
            data = f.read()

        sha1.update(data)

