import pickle
import os

def load_and_save_state(file_path):
    try:
        # Load state data from file path if it exists
        if os.path.exists(file_path):
            with open(file_path, 'rb') as f:
                state = pickle.load(f)
        else:
            # Start with a clean slate if the file does not exist
            state = {}
    except Exception as e:
        print(f"Error loading state data: {e}")
        state = {}

    try:
        # Save state data to file path when finished
        with open(file_path, 'wb') as f:
            pickle.dump(state, f)
    except Exception as e:
        print(f"Error saving state data: {e}")

    return state
