import tarfile
import os

def extract_tarball(tarball_path, directory_path):
    if not os.path.isfile(tarball_path):
        raise FileNotFoundError(f"The file {tarball_path} does not exist.")

    if not os.path.isdir(directory_path):
        raise NotADirectoryError(f"{directory_path} is not a valid directory.")

    with tarfile.open(tarball_path, "r") as tar:
        tar.extractall(path=directory_path)
        for member in tar.getmembers():
            if member.isreg():  # Check if the file is regular (not a directory or symlink)
                info = tar.getinfo(member)
                os.chmod(os.path.join(directory_path, member.name), info.mode)
