CREATE OR REPLACE FUNCTION rename_column(table_name TEXT, old_column_name TEXT, new_column_name TEXT, field_object JSONB) RETURNS VOID AS $$
DECLARE
    column_definition TEXT;
BEGIN
    -- Check if the table exists
    IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = table_name) THEN
        RAISE EXCEPTION 'Table % does not exist', table_name;
    END IF;

    -- Get the column definition
    SELECT string_agg(column_definition, ', ') INTO column_definition
    FROM information_schema.columns
    WHERE table_name = rename_column.table_name AND column_name = rename_column.old_column_name;

    IF column_definition IS NULL THEN
        RAISE EXCEPTION 'Column % does not exist in table %', old_column_name, table_name;
    END IF;

    -- Drop the old column if it exists
    EXECUTE format('ALTER TABLE %I DROP COLUMN IF EXISTS %I', table_name, old_column_name);

    -- Add the new column with the specified data type and constraints
    EXECUTE format(
        'ALTER TABLE %I ADD COLUMN %s',
        table_name,
        replace(replace(field_object::TEXT, '"type"', ''), '"', '''') || ' ' || new_column_name
    );

    -- Recreate the old column with its original definition
    EXECUTE format('ALTER TABLE %I ADD COLUMN %s', table_name, column_definition);
END;
$$ LANGUAGE plpgsql;
