                if col_names
                else [(i, j) for (i, j) in enumerate(cols)]
            )
            cols = []
            col_indices = []
            for col_name in col_names:
                for (i, j) in enumerated_columns:
                    if col_name == j.name:
                        col_indices.append(i)
                        cols.append(j)
                        break

        rows = t.getNumberOfRows()

        offset = kwargs.get("offset", 0)
        limit = kwargs.get("limit", None)
