from sqlalchemy import create_engine
from sqlalchemy.pool import NullPool

def connect_to_multiple_databases(database_configs):
    engines = {}
    try:
        for db_name, config in database_configs.items():
            engine = create_engine(config['url'], poolclass=NullPool)
            connection = engine.connect()
            engines[db_name] = {
                'engine': engine,
                'connection': connection
            }
        return engines
    except Exception as e:
        for _, db_info in engines.items():
            db_info['connection'].close()
            db_info['engine'].dispose()
        raise e

def close_multiple_database_connections(engines):
    for _, db_info in engines.items():
        db_info['connection'].close()
        db_info['engine'].dispose()
