import json

def deserialize_json(input_string):
    try:
        # Deserialize the JSON string into a Python object
        obj = json.loads(input_string)

        # Optionally decode non-string dictionary keys into Python objects
        def convert_keys(dictionary):
            new_dict = {}
            for key, value in dictionary.items():
                if isinstance(key, str):
                    new_dict[json.loads(key)] = value
                else:
                    new_dict[key] = value
            return new_dict

        # Check if the deserialized object is a dictionary and apply conversion
        if isinstance(obj, dict):
            return convert_keys(obj)
        else:
            return obj
    except json.JSONDecodeError:
        # Handle JSON decoding errors
        raise ValueError("Invalid JSON input")
