import hashlib
from urllib.parse import urlparse

class RFPDupeFilter(object):
    def __init__(self):
        self.seen = set()

    def request_fingerprint(self, request):
        parsed_url = urlparse(request.url)
        netloc_lower = parsed_url.netloc.lower()
        path_lower = parsed_url.path.lower()
        query_string = parsed_url.query.lower() if parsed_url.query else ''
        fingerprint = f"{parsed_url.scheme}://{netloc_lower}{path_lower}?{query_string}"
        return hashlib.sha1(fingerprint.encode()).hexdigest()

    def seen_request(self, request):
        fp = self.request_fingerprint(request)
        if fp in self.seen:
            return True
        else:
            self.seen.add(fp)
            return False

class CaseInsensitiveDuplicateFilter(RFPDupeFilter):
    def __init__(self):
        super().__init__()

    def request_fingerprint(self, request):
        lowercased_url = request.url.lower()
        return hashlib.sha1(lowercased_url.encode()).hexdigest()
