use std::fs;
use std::path::Path;

fn create_or_get_directory(dir_name: &str) -> Result<(), std::io::Error> {
    // Check if the environment variable is already set
    let current_value = env::var(dir_name);
    match current_value {
        Ok(val) => {
            println!("The directory {} already exists at {}", dir_name, val);
            return Ok(());
