use std::env;
use std::path::PathBuf;
use std::process::Command;

fn system_root_directory() -> Result<String, &'static str> {
    // Try to get the root directory from the environment variable if available
    if let Ok(root) = env::var("ROOT") {
        return Ok(root);
    }

    // Use 'readlink -f /proc/self/exe' to get the absolute path of the current executable
    let output = Command::new("readlink")
                         .arg("-f")
                         .arg("/proc/self/exe")
                         .output()?;

    if !output.status.success() {
        return Err("Failed to determine the system root directory");
    }

    let exe_path = String::from_utf8(output.stdout)?;
    let mut path = PathBuf::from(exe_path);

    // Follow symbolic links and make the path absolute
    while let Some(parent) = path.parent() {
        if parent.as_os_str() == "/" {
            break;
        }
        path = parent.to_owned();
    }

    Ok(path.to_string_lossy().into_owned())
}
