use std::fs::File;
use std::io::{self, Write};
use std::path::Path;

fn create_tee_writer<P: AsRef<Path>>(file_paths: Vec<P>) -> io::Result<impl Write> {
    let writers: io::Result<Vec<File>> = file_paths.iter().map(|path| File::create(path)).collect();
    let mut writers = writers?;

    Ok(TeeWriter::new(writers))
}

struct TeeWriter<W: Write> {
    writers: Vec<W>,
}

impl<W: Write> TeeWriter<W> {
    fn new(writers: Vec<W>) -> Self {
        TeeWriter { writers }
    }
}

impl<W: Write> Write for TeeWriter<W> {
    fn write(&mut self, buf: &[u8]) -> io::Result<usize> {
        let mut written_total = 0;
        for writer in &mut self.writers {
            match writer.write(&buf[written_total..]) {
                Ok(n) => {
                    if n == 0 {
                        break;
                    }
                    written_total += n;
                },
                Err(e) => return Err(e),
            }
        }
        for writer in &mut self.writers {
            match writer.flush() {
                Ok(_) => {},
                Err(e) => return Err(e),
            }
        }
        Ok(written_total)
    }

    fn flush(&mut self) -> io::Result<()> {
        for writer in &mut self.writers {
            match writer.flush() {
                Ok(_) => {},
                Err(e) => return Err(e),
            }
        }
        Ok(())
    }
}
