fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <filename>", args[0]);
        return;
    }
    let filename = &args[1];
    match count_lines_with_only_letters(filename) {
        Ok(count) => println!("Number of lines with only letters: {}", count),
        Err(e) => eprintln!("Error: {}", e),
    }
}

fn count_lines_with_only_letters<P>(filename: P) -> io::Result<usize>
where
    P: AsRef<Path>,
{
    let file = File::open(filename)?;
    let reader = io::BufReader::new(file);
    let mut count = 0;

    for line in reader.lines() {
        if is_line_with_only_letters(&line?) {
            count += 1;
        }
    }

    Ok(count)
}

fn is_line_with_only_letters(line: &str) -> bool {
    line.chars().all(|c| c.is_ascii_alphabetic())
}
