use std::net::{TcpListener, TcpStream};
use std::thread;
use std::io::{Read, Write};
use flate2::Compression;
use flate2::write::GzEncoder;
use std::sync::mpsc::{self, Receiver, Sender};

fn handle_client(mut stream: TcpStream) {
    let mut buffer = [0; 1024];
    match stream.read(&mut buffer) {
        Ok(_) => {
            // Compress the data using GzEncoder
            let mut encoder = GzEncoder::new(Vec::new(), Compression::default());
            encoder.write_all(&buffer).unwrap();
            let compressed_data = encoder.finish().unwrap();

            // Send the compressed data back to the client
            stream.write_all(&compressed_data).unwrap();
        }
        Err(e) => {
            eprintln!("Failed to read from stream: {}", e);
        }
    }
}

fn main() {
    let listener = TcpListener::bind("127.0.0.1:8080").unwrap();
    println!("Listening on 127.0.0.1:8080");

    // Create a thread pool with the number of available CPUs
    let num_cpus = num_cpus::get();
    let (sender, receiver): (Sender<Job>, Receiver<Job>) = mpsc::channel();

    for _ in 0..num_cpus {
        let receiver = receiver.clone();
        thread::spawn(move || {
            while let Ok(job) = receiver.recv() {
                job();
            }
        });
    }

    // Accept incoming connections and handle them with the thread pool
    for stream in listener.incoming() {
        match stream {
            Ok(stream) => {
                sender.send(Box::new(move || handle_client(stream))).unwrap();
            }
            Err(e) => {
                eprintln!("Failed to establish connection: {}", e);
            }
        }
    }
}
