use std::str;
use base64::{decode};
use hmac::{Hmac, Mac};
use sha2::Sha256;
use aes::Aes128;
use block_modes::{BlockMode, Cbc};
use block_modes::block_padding::Pkcs7;

type Aes128Cbc = Cbc<Aes128, Pkcs7>;
type HmacSha256 = Hmac<Sha256>;

fn decrypt(encrypted_blob: &str, device_id: &str, username: &str) -> Result<Vec<u8>, String> {
    if encrypted_blob.is_empty() {
        return Err("Encrypted blob is empty".to_string());
    }

    // Derive secret key from device ID and username
    let mut mac = HmacSha256::new_from_slice(device_id.as_bytes())
        .map_err(|e| format!("HMAC initialization failed: {}", e))?;
    mac.update(username.as_bytes());
    let key = mac.finalize().into_bytes();

    // Decode the encrypted blob from base64
    let decoded_data = decode(encrypted_blob)
        .map_err(|e| format!("Base64 decoding failed: {}", e))?;

    // Check if the data is in CBC mode (likely, but not guaranteed)
    if decoded_data.len() < 16 {
        return Err("Decoded data too short to be a valid CBC block".to_string());
    }

    let iv = &decoded_data[..16];
    let ciphertext = &decoded_data[16..];

    // Create AES-CBC decryptor with the derived key and IV
    let cipher = Aes128Cbc::new_from_slices(&key, iv)
        .map_err(|e| format!("AES initialization failed: {}", e))?;

    // Decrypt the ciphertext
    let decrypted_data = cipher.decrypt(ciphertext)
        .map_err(|e| format!("Decryption failed: {}", e))?;

    Ok(decrypted_data.to_vec())
}
