use std::env;
use std::path::PathBuf;

fn find_command(executable_name: &str) -> Option<PathBuf> {
    // List of directories to search, including current working directory and cargo library directory
    let dirs = [env::current_dir().ok()?, PathBuf::from("/usr/local/cargo/bin")];

    for dir in dirs.iter() {
        if let Some(path) = find_in_directory(&dir, executable_name) {
            return Some(path);
        }
    }

    None
}

fn find_in_directory(dir: &PathBuf, executable_name: &str) -> Option<PathBuf> {
    if dir.is_dir() {
        for entry in std::fs::read_dir(dir).ok()? {
            let entry = entry.ok()?;
            let path = entry.path();
            if path.is_file() && path.extension().and_then(|ext| ext.to_str()) == Some("exe") {
                if path.file_name()?.to_str()?.starts_with(executable_name) {
                    return Some(path);
                }
            }
        }
    }
    None
}
