use sha1::Sha1;
use std::str;

fn decrypt(encrypted_blob: &str) -> Option<String> {
    // Generate a secret key from device ID and username using SHA-1 hash function
    let device_id = "device_id";
    let username = "username";
    let key = generate_key(device_id, username);

    // Decrypt the encrypted blob using Hmac-SHA-1 with the generated key
    decrypt_with_hmac(&key, encrypted_blob)
}

fn generate_key(device_id: &str, username: &str) -> Vec<u8> {
    let mut hasher = Sha1::new();
    hasher.update(device_id);
    hasher.update(username);
    let result = hasher.finalize();
    result.to_vec()
}

fn decrypt_with_hmac(key: &[u8], encrypted_blob: &str) -> Option<String> {
    // Create Hmac-SHA1 instance with the key
    type HmacSha1 = Hmac<Sha1>;
    let mut hmac = HmacSha1::new_from_slice(key).expect("HMAC can take key of any size");

    // Update Hmac-SHA1 with the encrypted blob
    hmac.update(encrypted_blob.as_bytes());

    // Finalize and get the result
    let result = hmac.finalize();
    let code_bytes = result.into_bytes().to_vec();

    // Decode the decrypted data (assuming it's UTF-8 encoded)
    match str::from_utf8(&code_bytes) {
        Ok(decoded_data) => Some(decoded_data.to_string()),
        Err(_) => None,
    }
}
