use std::env;
use std::path::PathBuf;

fn get_binary_path(binary_name: &str) -> PathBuf {
    // Get the current executable's path
    let mut exe_path = env::current_exe().expect("Failed to get current executable path");

    // Navigate to the parent directory of the current executable
    exe_path.pop();

    // Navigate to the parent directory of that directory
    exe_path.pop();

    // Join the binary name to the end of the path
    let mut binary_path = exe_path;
    binary_path.push(binary_name);

    // Assert that the resulting path exists
    assert!(binary_path.exists(), "The specified binary does not exist");

    binary_path
}
