use hmac::{Hmac, Mac};
use sha1::Sha1;
use std::collections::HashMap;
use hyper::header::Headers;
use hyper::server::Request;
use hyper::server::Response;
use hyper::mime::Mime;
use rustc_serialize::base64::{ToBase64, MIME};
use std::str;

type HmacSha1 = Hmac<Sha1>;

fn verify_request(request: &Request, config: &HashMap<String, String>) -> Result<Response, Response> {
    let header_value = request.headers().get("X-Header").and_then(|hv| hv.to_str().ok());
    if let Some(header) = header_value {
        let secret = config.get("secret").unwrap();
        let mut mac = HmacSha1::new_from_slice(secret.as_bytes()).expect("HMAC can take key of any size");
        let body = request.body().to_string().unwrap();
        mac.update(&body.as_bytes());
        let result = mac.finalize();
        let code = result.into_bytes();
        let expected_code = header.split(' ').last().unwrap().trim();
        if expected_code == &*code.to_base64(MIME) {
            Ok(Response::new().with_body(&*body))
        } else {
            Err(Response::new().with_status("404 Not Found").with_body("Invalid request body"))
        }
    } else {
        Err(Response::new().with_status("404 Not Found").with_body("Missing header value"))
    }
}
