fn hash_string(input: &str, iterations: usize) -> String {
    let mut hasher = Md5::new();
    for _ in 0..iterations {
        hasher.update(input);
        let result = hasher.finalize();
        hasher = Md5::new(); // Reset the hasher for the next iteration
        hasher.update(&result[..]);
    }
    let final_result = hasher.finalize();
    format!("{:x}", final_result)
}

