use std::process::Command;
use std::fs;
use std::path::Path;

fn generate_fdset(protobuf_file: &str) -> Result<String, std::io::Error> {
    // Create a temporary file with a unique name to write the protobuf content to.
    let temp_dir = std::env::temp_dir();
    let temp_file_path = temp_dir.join(format!("temp_{}", uuid::Uuid::new_v4()));
    
    // Write the protobuf file content to the temporary file.
    fs::write(&temp_file_path, &fs::read(protobuf_file)?)?;
    
    // Define the path for the fdset file.
    let fdset_file_path = temp_dir.join(format!("fdset_{}", uuid::Uuid::new_v4()));
    
    // Run the protoc compiler to generate the fdset.
    Command::new("protoc")
        .arg("--descriptor_set_out=.")
        .arg(&fdset_file_path)
        .arg(&temp_file_path)
        .output()?;
    
    // Remove the temporary file.
    fs::remove_file(&temp_file_path)?;
    
    Ok(fdset_file_path.to_str().unwrap().to_owned())
}
