use std::net::Ipv4Addr;
use std::str::FromStr;

fn update_hosts_file(ip: &str, hostname: &str) -> io::Result<()> {
    let path = "/etc/hosts"; // Path to the hosts file, may vary depending on OS
    let mut content = fs::read_to_string(&path)?;

    if !content.lines().any(|line| line.contains(hostname)) {
        content.push_str("\n");
        content.push_str(ip);
        content.push_str(" ");
        content.push_str(hostname);
    }

    let mut file = fs::OpenOptions::new()
        .write(true)
        .truncate(true)
        .open(&path)?;
    write!(file, "{}", content)?;

    Ok(())
}

