use rust_sha1::Sha1;
use std::collections::HashMap;

fn sha1_hash(data: &[u8]) -> String {
    let mut hasher = Sha1::new();
    hasher.update(data);
    format!("{:x}", hasher.finalize())
}

fn process_chunks(data: Vec<u8>, chunk_size: usize) -> (BDict, usize) {
    let mut final_dict = BDict::new();
    let mut position = 0;

    while position < data.len() {
        let end = std::cmp::min(position + chunk_size, data.len());
        let chunk = &data[position..end];
        let hash = sha1_hash(chunk);

        let mut chunk_dict = BDict::new();
        chunk_dict.insert("hash".to_string(), hash.into());
        chunk_dict.insert("data".to_string(), chunk.to_vec().into());

        final_dict.insert(format!("chunk_{}", position), chunk_dict);
        position += chunk_size;
    }

    (final_dict, position)
}
