use std::fs::File;
use std::io::{self, Write};

struct History {
    max_size: usize,
    entries: Vec<String>,
}

impl History {
    fn new(max_size: usize) -> Self {
        History {
            max_size,
            entries: Vec::new(),
        }
    }

    fn push(&mut self, entry: String) {
        if self.entries.len() >= self.max_size {
            self.entries.remove(0);
        }
        self.entries.push(entry);
    }

    fn commit(&self, filename: &str) -> io::Result<()> {
        let mut file = File::create(filename)?;
        for entry in &self.entries {
            writeln!(file, "{}", entry)?;
        }
        Ok(())
    }
}

fn main() -> io::Result<()> {
    let mut history = History::new(10);
    for i in 0..20 {
        history.push(format!("Entry {}", i));
    }
    history.commit("history.txt")?;

    // Assert the length of the committed history
    let file = File::open("history.txt")?;
    let reader = io::BufReader::new(file);
    let lines: Vec<_> = reader.lines().collect();
    assert_eq!(lines.len(), 10); // Adjust this assertion based on your actual history size

    Ok(())
}
