#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

int create_temp_file(int *read_fd, int *write_fd) {
    char temp_path[] = "/tmp/temp_XXXXXX";
    int fd = mkstemp(temp_path);

    if (fd == -1) {
        perror("Error creating temporary file");
        return -1;
    }

    // Set the O_BINARY flag to ensure binary mode
    int flags = fcntl(fd, F_GETFL, 0);
    if (flags == -1) {
        close(fd);
        perror("Error getting file status flags");
        return -1;
    }

    flags |= O_BINARY;

    if (fcntl(fd, F_SETFL, flags) == -1) {
        close(fd);
        perror("Error setting file status flags");
        return -1;
    }

    // Create a duplicate file descriptor for reading
    *read_fd = dup(fd);
    if (*read_fd == -1) {
        close(fd);
        perror("Error duplicating file descriptor for reading");
        return -1;
    }

    // Close the original write-only file descriptor
    close(fd);

    // Create a new file descriptor for writing, inheriting permissions from the original
    *write_fd = open(temp_path, O_WRONLY | O_CREAT | O_TRUNC, 0666);
    if (*write_fd == -1) {
        close(*read_fd);
        perror("Error creating file descriptor for writing");
        return -1;
    }

    // Remove the temporary file after it is closed or program exits
    unlink(temp_path);

    return 0;
}
