import hashlib

def calculate_hash(input_string, algorithm):
    """
    Calculate the cryptographic hash of an input string using a specified algorithm.

    :param input_string: The input string to be hashed.
    :param algorithm: The hashing algorithm to use (e.g., 'md5', 'sha1', 'sha256').
    :return: A hexadecimal representation of the hash.
    """
    if algorithm == 'md5':
        return hashlib.md5(input_string.encode()).hexdigest()
    elif algorithm == 'sha1':
        return hashlib.sha1(input_string.encode()).hexdigest()
    elif algorithm == 'sha256':
        return hashlib.sha256(input_string.encode()).hexdigest()
    else:
        raise ValueError("Unsupported hashing algorithm")

# Test the function with predefined input strings and expected output hashes
def test_calculate_hash():
    # Define a dictionary of test cases
    test_cases = {
        'md5': {'input': 'hello', 'expected': '5d41402abc4b2a76b9719d911017c592'},
        'sha1': {'input': 'hello', 'expected': 'aaf4c61ddcc5e8a2dabede0f3b482cd9aea9434d'},
        'sha256': {'input': 'hello', 'expected': '2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824'}
    }

    # Iterate over the test cases and verify the results
    for algorithm, case in test_cases.items():
        result = calculate_hash(case['input'], algorithm)
        assert result == case['expected'], f"Test failed for {algorithm}: expected {case['expected']}, got {result}"

    print("All tests passed.")

# Run the test function
test_calculate_hash()
