fn find_command(command: &str) -> Option<String> {
    // Get the current executable's directory and its parent directory
    let exe_dir = env::current_exe().ok()?;
    let exe_parent_dir = exe_dir.parent()?.to_path_buf();

    // Get the PATH environment variable
    if let Ok(path) = env::var("PATH") {
        for dir in path.split(':') {
            let dir_path = Path::new(&dir);

            // Check if the command exists in any of the directories
            if dir_path.join(command).is_file() {
