use std::env;
use std::fs;
use std::path::PathBuf;

fn find_config_file(filename: &str) -> Option<PathBuf> {
    let mut path = env::current_dir().ok()?;
    path.push(filename);
    if path.exists() {
        return Some(path);
    }

    let exe_path = env::current_exe().ok()?;
    let mut exe_parent = exe_path.parent()?.to_owned();
    exe_parent.push(filename);
    if exe_parent.exists() {
        return Some(exe_parent);
    }

    let home_dir = env::var("HOME").ok()?;
    let mut home_path = PathBuf::from(&home_dir);
    home_path.push(filename);
    if home_path.exists() {
        return Some(home_path);
    }

    None
}
