use std::fs;
use std::io::{self, Read};
use md5::{Md5, Digest};

struct FileInfo {
    name: String,
    path: String,
    size: u64,
    md5_hash: String,
}

fn get_file_info(file_path: &str) -> io::Result<FileInfo> {
    let file = fs::File::open(file_path)?;
    let mut buffer = Vec::new();
    file.read_to_end(&mut buffer)?;
    
    let md5_hash = Md5::digest(&buffer);
    let md5_str = format!("{:x}", md5_hash);
    
    let metadata = fs::metadata(file_path)?;
    
    Ok(FileInfo {
        name: file_path.split('/').last().unwrap().to_string(),
        path: file_path.to_string(),
        size: metadata.len(),
        md5_hash: md5_str,
    })
}
