fn get_head_commit_hash(repo_path: &str) -> Result<String, String> {
    let output = Command::new("git")
        .args(&["rev-parse", "HEAD"])
        .current_dir(repo_path)
        .output()
        .map_err(|e| format!("Failed to execute git command: {}", e))?;

    if output.status.success() {
        let commit_hash = String::from_utf8(output.stdout).map_err(|e| format!("Invalid UTF-8 output: {}", e))?;
        Ok(commit_hash.trim().to_string())
    } else {
        Err(String::from_utf8(output.stderr).unwrap_or_else(|e| format!("Git command failed: {}", e)))
    }
}
