use std::process::Command;

fn create_command(command: &str, flavor: Option<&str>) -> Command {
    let mut cmd = if command.contains('.') || !command.contains(' ') {
        // Normal executable case
        Command::new(command)
    } else {
        // Batch script case, use 'cmd' on Windows
        #[cfg(windows)]
        let flavor = match flavor {
            Some("wasm") => "powershell",
            _ => "cmd"
        };
        #[cfg(not(windows))]
        let flavor = "sh";
        
        Command::new(flavor).arg("/c").arg(command)
    }
}
