use std::process::Command;
use std::io::{self, Error};

fn open_file(path: &str) -> Result<String, io::Error> {
    let commands = [
        ("$BROWSER", "open"),
        ("xdg-open", "xdg-open"),
        ("gnome-open", "gnome-open"),
        ("kde-open", "kde-open"),
    ];

    for &(cmd, _) in &commands {
        if cfg!(target_os = "windows") {
            // Windows specific handling
            let output = Command::new("cmd").arg("/C").arg(format!("start {}", path)).output()?;
            if output.status.success() {
                return Ok(String::from("cmd"));
            }
        } else {
            // Unix-like specific handling
            let output = Command::new(cmd).arg(path).output()?;
            if output.status.success() {
                return Ok(String::from(cmd));
            }
        }
    }

    let attempted_commands: Vec<&str> = commands.iter().map(|&(cmd, _)| cmd).collect();
    Err(io::Error::new(io::ErrorKind::Other, format!("No command found to open the file. Attempted commands: {:?}", attempted_commands)))
}
